function gate(kind){return `<div class="gate"><span class="gate-icon" aria-hidden="true">!</span><div class="eyebrow" style="justify-content:center">${t('רגע לפני שיודעים הכול','BEFORE YOU KNOW EVERYTHING')}</div><h2>${t('מכאן, גם הסוף בפנים.','The ending is in here, too.')}</h2><p>${kind==='compare'?t('הבדלים בין הספר למחזמר חושפים מה השתנה, מה נעלם ומה קורה לדמויות. זה מקום נהדר לחזור אליו אחרי הצפייה.','Comparing the novel and musical reveals what changes, what disappears, and what happens to the characters. A good place to return after watching.'):kind==='characters'?t('מפת הקשרים כוללת זהויות, בחירות וגורלות. פתיחתה מאפשרת גם את פרטי העלילה בשאר המדריך.','The relationship map includes identities, choices and fates. Opening it also enables story details elsewhere in the guide.'):t('המסלול המלא עוקב אחרי שתי המערכות, כולל רגעי המפנה וגורל הדמויות. לא נחשוף אותם עד שתבחרו.','The full journey follows both acts, including turning points and the characters’ fates. Nothing is revealed until you choose.')}</p><div class="button-row"><button class="btn" data-action="enable-spoilers">${t('קראתי. לפתוח את הספוילרים','I understand. Reveal spoilers')}${arrow}</button>${link('listening',t('בינתיים, אל המוזיקה','Take me to the music'),'btn secondary')}</div><p class="safe-note">${t('הבחירה נשמרת בלשונית הזאת בלבד. אפשר להסתיר שוב בכל רגע.','Your choice lasts for this tab’s session. You can hide details again at any time.')}</p></div>`}
let homeJourney='first';
const journeyPaths=[{id:'first',title:{he:'לפני הפעם הראשונה',en:'Before your first show'},intro:{he:'קצת כיוון, בלי לקלקל את ההפתעה. התחילו בהכנה לערב, וקחו רק את הרקע שמתחשק לכם.',en:'A few bearings without spoiling the surprise. Start with the evening itself and take only the background you want.'},time:{he:'כ־10 דקות לטעימה · ההעמקה לבחירתכם',en:'About 10 minutes for a first taste · explore further if you wish'},pages:['before','story','map','musical']},{id:'after',title:{he:'אחרי שהמסך ירד',en:'After the show'},intro:{he:'שיר בראש, שאלה בלב? חוזרים לרגע אחד, משווים דרך אחרת לשיר אותו, וממשיכים לשיחה.',en:'A song in your head, a question still open? Return to a moment, hear another interpretation and keep the conversation going.'},time:{he:'כ־15 דקות לפתיחה · לא כולל צפייה בסרטונים',en:'About 15 minutes to get started · video time is extra'},pages:['after','listening','compare','ideas']},{id:'book',title:{he:'מהספר אל הבמה',en:'From page to stage'},intro:{he:'פוגשים את הוגו, מרעננים את הזיכרון, ואז רואים איך רומן רחב יריעה נעשה ערב של מוזיקה.',en:'Meet Hugo, refresh your memory and explore how a sprawling novel becomes an evening of music.'},time:{he:'כ־15 דקות למבט ראשון · הרומן המלא באישור ספוילרים',en:'About 15 minutes for an overview · full-novel recap requires spoiler consent'},pages:['hugo','novel','compare','musical']},{id:'voices',title:{he:'בעקבות הביצועים',en:'Follow the performances'},intro:{he:'אותו שיר יכול לפגוש אתכם אחרת אצל כל מבצע. מתחילים בהשוואה מודרכת, ומרחיבים את האוזניים מעבר לבמה.',en:'The same song can reach you differently through each performer. Start with a guided comparison, then listen beyond the stage.'},time:{he:'כ־10 דקות להתמצאות · אורך ההאזנה לבחירתכם',en:'About 10 minutes to find your way · listen for as long as you like'},pages:['listening','musical','screen','after']},{id:'play',title:{he:'ללמוד דרך משחק',en:'Learn through play'},intro:{he:'שאלה טובה, קשר שלא שמתם לב אליו, מקום שפתאום מסתדר בראש. אפשר להתחיל בחידון קצר ולהמשיך בעקבות הסקרנות.',en:'A good question, a connection you missed, a place that suddenly makes sense. Try a short quiz and follow your curiosity from there.'},time:{he:'כ־10 דקות לסיבוב קצר · אפשר גם 5 שאלות בלבד',en:'About 10 minutes for a short round · a five-question quiz is available'},pages:['quiz','characters','map','history']}];
function journeyCards(){const d=journeyPaths.find(x=>x.id===homeJourney)||journeyPaths[0];return `<div class="journey-intro" aria-live="polite"><h3>${h(d.title)}</h3><p>${h(d.intro)}</p><small>${h(d.time)}</small></div><div class="journey-cards">${d.pages.map((p,i)=>`<a href="${d.id==='voices'&&p==='listening'?galleryHref('_6nTyXcmgLc'):url(p)}" data-enter-journey="${d.id}"><span class="journey-step">0${i+1}</span><div><h3>${h(labels[p])}</h3><p>${h(pageHints[p])}</p></div>${arrow}</a>`).join('')}</div>`}
function journeyArrival(method){const j=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!j)return;const step=j.pages.indexOf(route)+1;if(step<1)return;A.track('journey_step',{journey_id:j.id,step_index:step,entry_method:method});if(step===j.pages.length)A.track('journey_complete',{journey_id:j.id,step_index:step})}
function journeyContinuation(){const d=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!d)return '';const i=d.pages.indexOf(route);if(i<0)return '';const next=d.pages[i+1];return `<aside class="journey-continuation" aria-label="${t('מסלול הביקור שבחרתם','Your chosen visit path')}"><div class="wrap journey-continuation-inner"><div><span>${t('תחנה','STOP')} ${i+1} / ${d.pages.length}</span><b>${h(d.title)}</b></div>${next?`<a class="journey-next" href="${url(next)}"><span>${t('התחנה הבאה','NEXT STOP')}</span><b>${h(labels[next])}</b>${arrow}</a>`:`<p>${t('זו התחנה האחרונה במסלול. אפשר להמשיך לגלות בקצב שלכם.','This is the final stop. Keep exploring at your own pace.')}</p>`}<button class="text-button" data-action="journey-exit">${t('לצאת מהמסלול','Leave this path')} <span aria-hidden="true">×</span></button></div></aside>`}
function homeJourneyChooser(){return `<section class="section home-journeys" aria-labelledby="home-journeys-heading"><div class="section-head"><div><div class="eyebrow">${t('חמש דרכים להיכנס, בלי ללכת לאיבוד','FIVE WAYS IN, WITHOUT GETTING LOST')}</div><h2 id="home-journeys-heading">${t('מה הביא אתכם לכאן?','What brings you here?')}</h2></div><p>${t('בחרו כיוון ותקבלו ארבע תחנות קשורות. זו הצעה למסלול, לא רשימת משימות; אפשר לדלג, לשנות כיוון או להישאר במקום אחד.','Choose a direction for four connected stops. It’s a suggested path, not a checklist; skip ahead, change direction or linger wherever you like.')}</p></div><div class="journey-choices" role="group" aria-label="${t('בחירת מסע','Choose a journey')}">${journeyPaths.map(j=>`<button data-home-journey="${j.id}" aria-pressed="${homeJourney===j.id}" class="${homeJourney===j.id?'active':''}">${h(j.title)}</button>`).join('')}</div><div id="home-journey-content">${journeyCards()}</div><div class="home-discovery-link"><p>${t('רוצים לראות את התמונה כולה?','Want to see the whole picture?')}</p>${link('sitemap',t('מפת האתר: כל החלקים, בלי לפתוח הכול בבת אחת','Site map: every part, without opening everything at once'),'text-link')}</div></section>`}
function sitemapPage(){return top(t('כל העולם הזה.<br>מפה אחת נקייה.','This whole world.<br>One clear map.'),t('הספר, המחזמר, האנשים, המקומות והשאלות. בחרו לפי מה שמעניין אתכם עכשיו; סימוני הספוילרים יעזרו לבחור כמה לפתוח.','The book, the musical, the people, the places and the questions. Choose what interests you now; spoiler labels help you decide how far to go.'),t('18 / למצוא את הדרך','18 / FIND YOUR WAY'))+`<div class="wrap section"><div class="sitemap-start"><div><h2>${t('לא בטוחים מאיפה להתחיל?','Not sure where to begin?')}</h2><p>${t('בדף הבית מחכים חמישה מסעות קצרים: לפני הצפייה, אחריה, מהספר לבמה, בעקבות ביצועים ולמידה דרך משחק.','The home page offers five short paths: before the show, after it, page to stage, performances and learning through play.')}</p></div>${link('home',t('לבחירת מסע','Choose a journey'))}</div><div class="sitemap-groups">${Object.entries(navGroups).map(([id,g],i)=>`<section><div class="sitemap-group-title"><span>0${i+1}</span><h2>${h(g.title)}</h2></div><ul>${g.pages.filter(p=>p!=='sitemap').map(p=>`<li><a href="${url(p)}"><h3>${h(labels[p])}</h3><p>${h(pageHints[p])}</p><small>${['novel','after','quiz','story','characters','compare','ideas'].includes(p)?t('פרטי עלילה באישור','PLOT DETAILS BY CONSENT'):t('אפשר להתחיל בלי לדעת את הסוף','START WITHOUT KNOWING THE ENDING')}</small>${arrow}</a></li>`).join('')}</ul></section>`).join('')}</div><div class="sitemap-foot"><div><h3>${t('המקורות והבחירות מאחורי המדריך','The sources and choices behind the guide')}</h3><p>${t('פרויקט מעריצים עצמאי. כאן נמצאים הקרדיטים, מדיניות הפרטיות והמקורות.','An independent fan project. Find credits, privacy information and research sources here.')}</p></div><div class="button-row">${link('about',t('מאחורי הקלעים','Behind the guide'),'btn secondary')}${link('privacy',t('פרטיות ובחירות','Privacy & choices'),'btn secondary')}${link('terms',t('תנאי שימוש','Terms of use'),'btn secondary')}</div></div></div>`}
function homeClassicPaths(){return `<section class="section home-classic-paths" aria-labelledby="home-classic-heading"><div class="section-head"><div><div class="eyebrow">${t('בחרו את הכניסה שלכם','CHOOSE YOUR WAY IN')}</div><h2 id="home-classic-heading">${t('איפה זה תופס אתכם?','Where does it find you?')}</h2></div><p>${t('תקציר ברור כשצריך כיוון. שאלה טובה כשבא להעמיק. ואם מתחשק לכם להיבחן, יש גם חדר חידונים.','A clear overview when you need your bearings. A good question when you want to dig in. And if a challenge sounds fun, there’s a quiz room too.')}</p></div><div class="path-grid">${[['01','story',t('רגע, מי רודף אחרי מי?','Wait, who’s chasing whom?'),t('מסלול עלילה מסודר, מהחסד הראשון ועד ההד האחרון. עומק בלחיצה, וספוילרים רק ברשות.','A guided story journey, from its first act of grace to its last echo. Go deeper with a click; reveal spoilers by choice.'),t('8 תחנות · שתי מערכות','8 CHAPTERS · TWO ACTS')],['02','listening',t('השיר הזה. שוב.','That song. Again.'),t(R.gallery.groups.length+' בחירות עם סיפור: ביצועים על הבמה, הפתעות, שירה משותפת והומור.',R.gallery.groups.length+' selections with a story: stage performances, surprises, shared singing and humor.'),t(R.gallery.groups.length+' בחירות · 4 זוויות',R.gallery.groups.length+' PICKS · 4 ANGLES')],['03','characters',t('כולם רוצים משהו.','Everyone wants something.'),t('מפת קשרים: מי מחפש התחלה חדשה, מי נאחז בסדר, ומי מבקש שיראו אותו.','A relationship explorer: who wants a fresh start, who needs certainty, and who wants to be seen.'),t('10 מוקדים · אינספור מתחים','10 CHARACTERS & GROUPS')]].map(([n,p,title,body,meta])=>`<a class="path-card" href="${url(p)}${p==='characters'?'#relationship-map':''}"><span class="number">${n}</span><span class="path-kind">${p==='story'?t('סיפור ועלילה','Story guide'):p==='listening'?t('ביצועים לצפייה','Performances'):t('דמויות וקשרים','Characters & relationships')}</span><h3>${title}</h3><p>${body}</p><div class="card-end"><span>${meta}</span>${arrow}</div></a>`).join('')}</div></section>`}
let pendingBookmark=null;
const bookmarkPages=Object.keys(labels).filter(x=>!['home','about','terms','privacy','sitemap'].includes(x));
function savedBookmarks(){if(!P.allowed('functional'))return [];try{const list=JSON.parse(getStored('barricade-bookmarks')||'[]');return Array.isArray(list)?[...new Set(list.filter(x=>bookmarkPages.includes(x)))]:[]}catch{return []}}
function bookmarkControl(){if(!bookmarkPages.includes(route))return '';const marked=savedBookmarks().includes(route);return `<div class="wrap page-utility"><button class="bookmark-control ${marked?'saved':''}" data-action="bookmark-toggle" aria-pressed="${marked}"><svg viewBox="0 0 16 20" aria-hidden="true"><path d="M2 1h12v17l-6-4-6 4z"/></svg><span>${marked?t('נשמר בדפים שלי','Saved in my pages'):t('לשמור לפעם הבאה','Save for another visit')}</span></button></div>`}
function toggleBookmark(page){if(!P.allowed('functional')||!bookmarkPages.includes(page))return;let items=savedBookmarks();items=items.includes(page)?items.filter(x=>x!==page):[...items,page];save('barricade-bookmarks',JSON.stringify(items));A.track('bookmark_change',{content_id:page,bookmark_action:items.includes(page)?'add':'remove'});}
function lastJourney(){if(!P.allowed('functional'))return null;try{const x=JSON.parse(getStored('barricade-last-journey')||'null');const d=journeyPaths.find(j=>j.id===x?.id);return d?.pages.includes(x.route)?{...x,journey:d}:null}catch{return null}}
function rememberJourney(){if(!P.allowed('functional'))return;const d=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!d?.pages.includes(route))return;const old=lastJourney();if(old?.id!==d.id||old?.route!==route)save('barricade-last-journey',JSON.stringify({id:d.id,route,updatedAt:Date.now()}))}
function homeMemory(){if(!P.allowed('functional'))return '';initQuiz();const j=lastJourney(),bookmarks=savedBookmarks(),q=quizRun&&!quizRun.finished?quizRun:null;if(!j&&!bookmarks.length&&!q)return '';return `<section class="home-memory" aria-labelledby="home-memory-title"><div class="home-memory-heading"><div><div class="eyebrow">${t('ברוכים השבים','WELCOME BACK')}</div><h2 id="home-memory-title">${t('המסע שלכם מחכה.','Your journey is waiting.')}</h2></div><button class="text-button" data-action="privacy-open">${t('ניהול הזכירה','Manage remembering')}</button></div><div class="memory-resume-grid">${j?`<a href="${url(j.route)}" data-resume-journey="${j.id}"><span>${h(j.journey.title)}</span><b>${t('לחזור אל','Return to')} ${h(labels[j.route])}</b><small>${t('תחנה','Stop')} ${j.journey.pages.indexOf(j.route)+1} / ${j.journey.pages.length} · ${t('הספוילרים נשארים בשליטתכם','Spoilers stay under your control')}</small>${arrow}</a>`:''}${q?`<a href="${url('quiz')}"><span>${t('החידון שלכם מחכה','Your quiz is waiting')}</span><b>${h(R.quiz.trackInfo[q.track].title)} · ${Q.score(q).answered} / ${q.length} ${t('נענו','answered')}</b><small>${t('ממשיכים מהשאלה שנשמרה, אחרי אישור ספוילרים','Resume at the saved question after spoiler consent')}</small>${arrow}</a>`:''}</div>${bookmarks.length?`<details class="saved-pages"><summary>${t('הדפים שלי','My saved pages')} <span>${bookmarks.length}</span></summary><ul>${bookmarks.map(p=>`<li><a href="${url(p)}"><b>${h(labels[p])}</b><small>${h(pageHints[p])}</small>${arrow}</a><button class="text-button" data-remove-bookmark="${p}" aria-label="${esc(t('הסרת סימנייה: ','Remove bookmark: ')+tr(labels[p]))}">×</button></li>`).join('')}</ul></details>`:''}</section>`}

function home(){return `<div class="wrap">${homeMemory()}<div class="home-opening"><section class="hero"><div class="hero-copy"><div class="eyebrow">${t('עלובי החיים · מדריך למי שרוצה להרגיש יותר','LES MISÉRABLES · A FIELD GUIDE FOR FEELING MORE')}</div><h1>${t('סיפור גדול.<span>לב פתוח.</span>','A big story.<span>An open heart.</span>')}</h1><p class="lede">${t('מדריך עצמאי לעלובי החיים: להכיר את הסיפור והדמויות, לגלות ביצועים ולהעמיק בספר ובמחזמר. בקצב שלכם, עם שליטה בספוילרים.','An independent guide to Les Misérables: meet the story and characters, discover performances, and explore the novel and musical. At your pace, with spoilers under your control.')}</p><div class="home-entry-choices"><a class="home-entry-choice primary" href="${url('before')}" data-enter-journey="first"><span><b>${t('פעם ראשונה? מתחילים כאן.','First time? Start here.')}</b><small>${t('כ־10 דקות להיכרות, בלי לגלות את הסוף.','About ten minutes to get your bearings, without the ending.')}</small></span>${arrow}</a><a class="home-entry-choice" href="${url('listening')}?clip=_6nTyXcmgLc" data-enter-journey="voices"><span><b>${t('הסיפור מוכר? משווים ביצועים.','Know the story? Compare performances.')}</b><small>${t('אותו שיר, שני מבצעים, פרטים חדשים לגלות.','One song, two performers, new details to notice.')}</small></span>${arrow}</a></div><p class="micro">${t('בלי שיעורי בית. בלי ספוילרים בהפתעה. עם מקום לצלול.','No homework. No surprise spoilers. Plenty of room to go deeper.')}</p></div><div class="hero-art"><img src="/scene.svg" width="920" height="920" alt="${t('איור מקורי של בריקדה תיאטרלית, גגות פריז ודגל אדום מול ירח','Original theatrical illustration: a barricade, Paris rooftops and a red flag against the moon')}"><div class="poster-stamp"><span class="poster-stamp-city">${t('פריז','PARIS')}</span><strong>1832</strong><span class="poster-stamp-caption">${t('הסיפור<br>ממשיך','STILL<br>RESONATING')}</span></div><div class="art-caption"><span>LIBERTÉ · HUMANITÉ · MUSIQUE</span><span>${t('פריז עולה על הבמה','PARIS TAKES THE STAGE')}</span></div></div></section>${homeClassicPaths()}<div class="hero-band"><div><strong>01</strong><span>${t('אפשר להתחיל משיר אחד. לא צריך להכיר כל דמות.','Start with one song. No need to know every character.')}</span></div><div><strong>02</strong><span>${t('עברית ואנגלית מלאות. אותה סקרנות, משני הכיוונים.','Full Hebrew and English. The same curiosity, both ways.')}</span></div><div><strong>∞</strong><span>${t('אין כאן “ביצוע מנצח”. יש אוזניים שפתאום שומעות יותר.','No “winning” performance. Just ears that notice more.')}</span></div></div></div></div><section class="section dark"><div class="wrap feature-split"><div class="vinyl" aria-hidden="true"><div class="vinyl-label"><small class="vinyl-title">${t('עלובי החיים','LES MISÉRABLES')}</small><b>${t('להקשיב<br>מקרוב.','LISTEN<br>CLOSER.')}</b><span class="vinyl-hole"></span><small class="vinyl-sides">${t('צד א׳ · הלב<br>צד ב׳ · העולם','SIDE A · HEART<br>SIDE B · WORLD')}</small></div></div><div class="feature-copy"><div class="eyebrow">${t('מעלים את הקשב, לא רק את הווליום','TURN UP THE ATTENTION')}</div><h2>${t('אותו שיר.<br>אדם אחר באוזניות.','Same song.<br>A different human.')} </h2><p>${t('במקום לשאול רק “מי שר הכי טוב?”, נבדוק מה משתנה כשמשתנים הנשימה, המבט, החלל והמצלמה.','Instead of only asking “Who sings it best?”, explore what changes with breath, gaze, space and the camera.')}</p><p>${t('משווים שתי פרשנויות ל־Stars, ממשיכים למפגש של אלפי בו עם המלחין ב־Bring Him Home, ומסיימים עם One Day More. אוזניות מומלצות. התרגשות אינה תקלה.','Compare two interpretations of Stars, meet Alfie Boe and the composer in Bring Him Home, then move to One Day More. Headphones welcome. Feelings are a feature.')}</p><a class="text-link" href="${url('listening')}?clip=_6nTyXcmgLc" data-gallery-link="_6nTyXcmgLc">${t('שתי גרסאות ל־Stars: מה משתנה במבט וביציבה?','Two versions of Stars: what changes in gaze and posture?')}${arrow}</a>${momentsInvitation()}</div></div></section><div class="wrap">${mapInvitation()}${homeJourneyChooser()}<section class="section"><div class="section-head"><div><div class="eyebrow">${t('מעבר לערב אחד בתיאטרון','MORE THAN ONE NIGHT AT THE THEATRE')}</div><h2>${t('הסיפור לא נשאר במקום.','The story doesn’t stay still.')}</h2></div></div><div class="musical-home-promo"><div><div class="eyebrow">${t("המחזמר, מהרעיון ועד ההדרן","THE MUSICAL, FROM IDEA TO ENCORE")}</div><h2>${t("בואו נלך עם המוזיקה.","Let’s follow the music.")}</h2><p>${t("היוצרים, ההפקות, שתי המערכות, והמסע האינטראקטיבי משיר לשיר, כולל ההפסקה.","The creators, the productions, the two acts, and an interactive song-by-song journey, interval included.")}</p></div>${link("musical",t("אל לב המחזמר","Into the musical"))}</div><div class="three-inline"><article class="editorial"><span class="tag">${t("מהספר לבמה","PAGE → STAGE")}</span><h3 style="margin-top:18px">${t('הוגו כתב הרבה. הבמה בחרה.','Hugo wrote big. The stage chose.')}</h3><p>${t('מה קורה כשעולם של רומן הופך לזמן בימתי? לא רשימת “טעויות”, אלא מבט על החלטות של עיבוד.','What happens when a whole novel becomes stage time? Explore adaptation choices rather than a list of “mistakes”.')}</p>${link('novel',t('רענון זיכרון לספר המקורי','Refresh the original novel'),'text-link')}<div style="margin-top:16px">${link('compare',t('ספר מול מחזמר · עם אזהרה','Book vs. musical · spoiler warning'),'text-link')}</div></article><article class="editorial"><span class="tag">${t("מהבמה למסך","STAGE → SCREEN")}</span><h3 style="margin-top:18px">${t('לא כל “עלובי החיים” שר.','Not every Les Mis sings.')}</h3><p>${t('סרטים, סדרות וקונצרט מצולם: מבחר אצור שעוזר להבדיל בין עיבוד לרומן לבין עיבוד למחזמר.','Films, television and a filmed concert: a curated guide to the difference between adapting the novel and adapting the musical.')}</p>${link('screen',t('לעיבודים בקולנוע ובטלוויזיה','Explore film and television adaptations'),'text-link')}</article><article class="editorial"><span class="tag">${t("מהבמה אל החיים","STAGE → EVERYWHERE")}</span><h3 style="margin-top:18px">${t('וכשהקהל מתחיל לשיר?','And when the audience sings?')}</h3><p>${t('חתונות, קניונים ויוצרים עם יותר מקול אחד. פינת המחווה לאנשים שלקחו את השירים לחיים שלהם.','Weddings, shopping centres and creators with more than one voice. A tribute to people who brought these songs into their own lives.')}</p>${link('tribute',t('למחוות מחוץ לבמה','Go beyond the stage'),'text-link')}</article></div></section><section class="question-strip"><span class="q" aria-hidden="true">?</span><div><h3>${t('זו המהפכה הצרפתית? כמעט. כלומר, לא.','The French Revolution? Close. Actually, no.')}</h3><p>${t('הבריקדה שבסיפור קשורה למרד יוני 1832 בפריז, לא למהפכה של 1789. תאריך קטן שעושה הבדל גדול.','The story’s barricade belongs to the June 1832 uprising in Paris, not the Revolution of 1789. A small date makes a big difference.')}</p></div>${link('history',t('הרקע ההיסטורי','The real history'),'btn secondary')}</section><section class="section"><div class="directory-intro"><span class="directory-mark" aria-hidden="true">↗</span><div><div class="eyebrow">${t('המסע ממשיך','THE JOURNEY CONTINUES')}</div><h2 style="font-size:2.3rem">${t('עשר דלתות לעולם גדול יותר.','Ten doors into a bigger world.')}</h2><p>${t('לקרוא את הוגו, להיכנס לביתו, לפגוש את ההפקות או למצוא עוד מעריצים. לכל קישור יש סיבה להיות כאן.','Read Hugo, visit his home, meet the productions or find fellow fans. Every link has a reason to be here.')}</p><div class="button-row">${link('resources',t('לאוסף הקישורים','Explore the collection'),'btn secondary')}</div></div></div></section><section class="section divider">${statsSection()}</section></div>`}
function statNote(note){return esc(tr(note));}
function statsSection(){const stats=R.stats||[];return `<div class="section-head"><div><div class="eyebrow">${t('סיפור שחצה גבולות','A STORY THAT CROSSED BORDERS')}</div><h2>${t('קצת פרופורציות.','A little perspective.')}</h2></div><p>${t('דורות של קוראים. אולמות ברחבי העולם.','Generations of readers. Theatres around the world.')}</p></div><div class="stats-grid">${(route==='home'?stats.slice(0,5):stats).map(s=>`<div class="stat"><strong>${esc(s.value)}</strong><h3>${h(s.label)}</h3>${route==='home'?'':`<p>${statNote(s.note)}</p>${sources(s.sourceIds)}`}</div>`).join('')}</div><p class="stats-review-note">${t('נתוני התפוצה: ההפקה הרשמית בלונדון, אוקטובר 2026.','Worldwide reach: official London production, October 2026.')} <a href="${url('about')}#about-provenance">${t('מקורות ותאריכים','Sources and dates')}</a></p>`}
function provenanceNote(){return `<details class="provenance-note" id="about-provenance"><summary>${t('מאין המספרים, ומתי נבדקו?','Where do the figures come from?')}</summary><p>${t('150 מיליון צופים, 57 מדינות, 22 שפות ו־455 ערים הם נתונים מצטברים שמפרסמת ההפקה הרשמית בלונדון. המקור נבדק ב־10 באוקטובר 2026.','The official London production publishes cumulative totals of 150 million viewers, 57 countries, 22 languages and 455 cities. Source checked 10 October 2026.')}</p><p>${t('שמונה פרסי הטוני מתייחסים לשנת 1987; 1862 היא שנת פרסום הרומן; חגיגת 40 השנה בלונדון נערכה ב־8 באוקטובר 2025. גם המקורות ההיסטוריים והקישורים במדף המשאבים נבדקו ב־10 באוקטובר 2026.','The eight Tony Awards belong to 1987; the novel was published in 1862; London celebrated its 40th anniversary on 8 October 2025. These historical sources and the resource shelf links were also reviewed on 10 October 2026.')}</p>${sources(['london-official-about','stat-3','stat-4','stat-5'])}</details>`}
function mapInvitation(){return `<aside class="map-invitation"><div class="map-invitation-art" aria-hidden="true"><svg viewBox="0 0 190 85"><path d="M18 60L60 24 108 55 168 15" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 6"/><circle cx="18" cy="60" r="7"/><circle cx="60" cy="24" r="7"/><circle cx="108" cy="55" r="7"/><circle cx="168" cy="15" r="9" fill="#ed2939"/></svg></div><div><span class="eyebrow">${t('המקומות מתחברים','CONNECT THE PLACES')}</span><h2>${t('רגע, איפה כל זה קורה?','Wait, where does all this happen?')}</h2><p>${t('מפה גאוגרפית עם תצלומים, ולצדה תשע תחנות סיפור מאוירות ברחבי צרפת ופריז. מוצאים את המקומות, ואז פותחים את התאריכים והחיבורים לדמויות. ספוילרים רק לפי הבחירה שלכם.','A geographic explorer with photographs, plus nine illustrated story stations across France and Paris. Find the places, then follow their dates and character connections. Plot details by choice.')}</p></div>${link('map',t('לפתוח את מפת המסע','Open the interactive story map'),'btn secondary')}</aside>`}
function storyOrientation(){return `<section class="story-orientation"><h2>${t('איפה אנחנו בסיפור הבימתי?','Where are we in the stage story?')}</h2><p>${t('שמונה תחנות לאורך הסיפור הבימתי.','Eight stops through the stage story.')}</p><div>${[['release',t('פרולוג · תחנה 01','Prologue · stop 01'),t('תקופת המאסר מסתיימת; הניסיון להתחיל מחדש רק מתחיל.','A prison term ends; the work of beginning again starts.')],['fantine',t('מערכה ראשונה · תחנות 02–05','Act I · stops 02–05'),t('צרכים שונים ונאמנויות שונות מתכנסים אל אותו משבר.','Different needs and loyalties converge on the same crisis.')],['barricade',t('מערכה שנייה · תחנות 06–08','Act II · stops 06–08'),t('הבחירות של המערכה הראשונה נבחנות במתרס ובמה שבא אחריו.','The first act’s choices are tested at the barricade and in what follows.')]].map(([id,title,body])=>`<button data-jump="story-${id}"><b>${title}</b><span>${body}</span>${arrow}</button>`).join('')}</div></section>`}
function storyFirstLook(){return `<section class="story-first-look" aria-labelledby="story-first-look-heading"><div class="eyebrow">${t('נקודת פתיחה · בלי תפניות ובלי סוף','THE STARTING POINT · NO TWISTS OR ENDING')}</div><h2 id="story-first-look-heading">${t('קודם, להכיר את מה שמונח על הכף.','First, meet what is at stake.')}</h2><p class="story-first-intro">${t('צרפת, 1815. ז׳אן ולז׳אן משתחרר מהכלא, אבל חופש אינו מבטיח מקום בחברה. משם המחזמר נע בין חיים פרטיים לבין הרחוב, עד לפריז של יוני 1832.','France, 1815. Jean Valjean leaves prison, but freedom does not guarantee a place in society. From there, the musical moves between private lives and public streets, reaching Paris in June 1832.')}</p><div class="story-premise-grid"><article><span>01</span><h3>${t('הזדמנות להתחיל מחדש','A chance to begin again')}</h3><p>${t('ולז׳אן מחפש חיים מעבר לזהות של אסיר לשעבר. השאלה אינה רק אם ימצא עבודה ומקום לישון, אלא אם מישהו יהיה מוכן לראות בו אדם שיכול להשתנות.','Valjean looks for a life beyond his identity as an ex-prisoner. The question is not just whether he can find work and shelter, but whether anyone will see a person capable of change.')}</p></article><article><span>02</span><h3>${t('חוק שאמור להישאר יציב','A law meant to stay constant')}</h3><p>${t('ז׳אבר הוא מפקח משטרה שנאחז בחוק ובסדר. כדאי להכיר את המתח הזה מראש: אדם עשוי להשתנות, אבל מה קורה לכללים שנועדו לשפוט אותו?','Javert is an inspector who puts his faith in law and order. Keep this tension in mind: a person may change, but what happens to the rules meant to judge him?')}</p></article><article><span>03</span><h3>${t('עוד חיים נכנסים לתמונה','Other lives enter the picture')}</h3><p>${t('פנטין מנסה לפרנס את בתה; צעירים מחפשים אהבה ואנשים חולמים על חברה צודקת יותר. אין צורך לשנן את כולם. חפשו בכל מפגש מה האדם צריך, ומי מחזיק בכוח לעזור לו.','Fantine tries to support her daughter; young people seek love and others dream of a fairer society. You do not need to memorise everyone. In each encounter, notice what someone needs and who has the power to help.')}</p></article></div><p class="small muted">${t('רוצים להכיר את האנשים לפני שפותחים את העלילה?','Want to meet the people before opening the plot?')} <a href="${url('characters')}#valjean-24601">${t('להכיר את ולז׳אן ואת המספר 24601','Meet Valjean and the number 24601')}</a></p>${sources(['curtain-mti-synopsis','curtain-tour-programme','curtain-june-history'])}</section>`}
function storyPage(){return top(t('הדרך הארוכה<br>להתחיל מחדש.','The long road<br>to beginning again.'),t('האיש, המרד, והאנשים שביניהם. קודם הכיוון הכללי, ואז שמונה תחנות עם אפשרות לפתוח את הפרטים.','The man, the uprising, and the people between them. Get your bearings, then explore eight editorial stops at your own depth.'),t('01 / הסיפור','01 / THE STORY'))+`<div class="wrap section">${storyFirstLook()}${mapInvitation()}<div class="note story-content-note">${t('כדאי לדעת: הסיפור כולל עוני, ניצול, עבודת מין, אלימות ומוות, ובהמשך גם התאבדות. פרטי האירועים נשארים מאחורי אזהרת הספוילרים.','Content note: the story includes poverty, exploitation, sex work, violence and death, and later suicide. Event details remain behind the spoiler warning.')}</div>${!spoiler?gate('story'):banner()+storyOrientation()+`<div class="timeline">${(R.story||[]).map((s,i)=>`<article class="story-chapter" id="story-${esc(s.id)}" tabindex="-1"><span class="chapter-index">${String(i+1).padStart(2,'0')}</span><div class="chapter-meta">${h(s.period)}</div><h2>${h(s.title)}</h2><p class="summary">${h(s.summary)}</p><details><summary>${t('עוד שכבה: מה קורה כאן באמת?','One layer deeper: what’s happening here?')}</summary><div class="detail-body">${h(s.detail).split('\n').filter(Boolean).map(p=>`<p>${p}</p>`).join('')}</div></details>${s.songs?.length?`<div class="song-tags" aria-label="${t('שירים הקשורים לתחנה','Related songs')}">${s.songs.map(song=>`<span lang="en">${esc(song)}</span>`).join('')}</div>`:''}${sources(s.sourceIds)}</article>`).join('')}</div><div class="story-foot"><h3>${t('אחרי הסוף, אפשר לחזור להתחלה.','After the ending, you can return to the beginning.')}</h3><p>${t('מי קיבל הזדמנות להשתנות, וממי נשללה האפשרות?','Who gets a chance to change, and who is denied one?')}</p><div class="button-row">${link('characters',t('לראות את הקשרים','Explore the connections'))}${link('compare',t('ומה קרה בספר?','What happened in the novel?'),'btn secondary')}</div></div>`}</div>`}
function mapCardContext(data,kind){if(!data||(data.spoilerLevel>1&&!spoiler))return '';return `<section class="map-card-context ${kind==='place'?'place-background':'character-depth'}"><h3>${kind==='place'?t('קצת רקע על המקום','A little context for the place'):t('עוד מבט על הדמות','A closer look at the person')}</h3><p>${data.sentences.map(x=>h(x)).join(' ')}</p><div class="source-links">${data.references.map(ref=>external(ref.url,tr(ref.label))).join('')}</div></section>`}
function characterCanonNotes(c){return (c.canonNotes||[]).map(n=>`<section class="character-canon-note" aria-labelledby="canon-${esc(n.id)}"><h3 id="canon-${esc(n.id)}">${h(n.title)}</h3>${n.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${sources(n.sourceIds)}</section>`).join('')}
function characterPanel(){let c=(R.characters||[]).find(c=>c.id===character)||(R.characters||[])[0];if(!c)return '';character=c.id;return `<article class="char-detail" id="character-detail" tabindex="-1" aria-live="polite"><div class="char-head"><div><div class="eyebrow">${t('דמות מקרוב','IN FOCUS')}</div><h2>${h(c.name)}</h2><span class="pill">${h(c.role)}</span></div><span class="char-mark" aria-hidden="true">${esc(tr(c.name).slice(0,1))}</span></div><p>${h(c.summary)}</p>${mapCardContext(c.context,'character')}${characterCanonNotes(c)}<div class="question"><span class="small">${t('שאלה לקחת לצפייה','A question to watch with')}</span><p>${h(c.question)}</p></div><h3>${t('הקשרים שמשנים את הסיפור','Connections that change the story')}</h3><div class="connections">${(c.connections||[]).filter(x=>!x.spoilers||spoiler).map(x=>{const target=R.characters.find(v=>v.id===x.id);return target?`<button class="connection" data-character="${esc(x.id)}"><b>${h(target.name)}</b><small>${h(x.label)}</small>${arrow}</button>`:''}).join('')}</div>${sources(c.sourceIds)}</article>`}
function characterNumberFact(){const d=R.safe24601;return d?`<aside class="safe-character-number" id="${esc(d.id)}" tabindex="-1"><h3>${h(d.title)}</h3><p>${h(d.body)}</p>${sources(d.sourceIds)}</aside>`:''}
function safeCharacters(){return `<section class="safe-character-overview" aria-labelledby="safe-characters-title"><div class="eyebrow">${t('להכיר לפני שנכנסים לעלילה','MEET THE PEOPLE BEFORE THE PLOT')}</div><h2 id="safe-characters-title">${t('עשר דמויות. נקודת פתיחה אחת.','Ten characters. A place to begin.')}</h2><p>${t('מי הם, מה הם צריכים ואילו קשרים כדאי להכיר כשנכנסים לסיפור. למעלה מחכה מפת הקשרים; כאן אפשר להכיר כל דמות בנפרד.','Who they are, what they need and the connections that help you enter the story. Explore their connections in the map above, or meet each person individually here.')}</p><nav class="safe-character-index" aria-label="${t('קפיצה לדמות','Jump to a character')}">${R.characters.map(c=>`<a href="#character-intro-${esc(c.id)}">${h(c.name)}</a>`).join('')}</nav><div class="safe-character-grid">${R.characters.map(c=>`<article class="safe-character-card" id="character-intro-${esc(c.id)}" tabindex="-1"><h3>${h(c.name)}</h3><p>${h(c.safeIntro)}</p>${c.id==='valjean'?characterNumberFact():''}</article>`).join('')}</div><section class="safe-relations" aria-labelledby="safe-relations-title"><h3 id="safe-relations-title">${t('הקשרים הראשונים','The first connections')}</h3><ul>${R.introConnections.map(x=>{const from=R.characters.find(c=>c.id===x.from),to=R.characters.find(c=>c.id===x.to);return `<li><a href="#character-intro-${esc(x.from)}">${h(from.name)}</a> · ${h(x.label)} · <a href="#character-intro-${esc(x.to)}">${h(to.name)}</a></li>`}).join('')}</ul></section><p class="small muted">${t('המקורות החיצוניים כוללים את העלילה המלאה.','External sources include the full story.')}</p>${sources(['novel','mti-synopsis'])}</section>`}
function charactersPage(){return top(t('מפת הקשרים','The relationship map'),t('עשר דמויות. בחרו דמות, עקבו אחרי הקווים, וגלו מה מחבר ביניהם.','Ten characters. Choose a person, follow the lines, and discover what connects them.'),t('02 / הדמויות','02 / THE PEOPLE')).replace('class="page-top"','class="page-top characters-top"').replace(bookmarkControl(),'')+`<div class="wrap section characters-page">${relationshipExplorer()}${bookmarkControl()}${!spoiler?safeCharacters():banner()+characterNumberFact()+`<section class="character-depth"><h2>${t('הדמויות מקרוב','The people in depth')}</h2><div class="character-layout"><div class="character-picker" aria-label="${t('בחירת דמות','Choose a character')}">${R.characters.map((c,i)=>`<button class="char-button ${c.id===character?'active':''}" data-character="${esc(c.id)}" aria-pressed="${c.id===character}"><span class="initial" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span><b>${h(c.name)}</b><small>${h(c.role)}</small></span></button>`).join('')}</div><div id="character-panel">${characterPanel()}</div></div></section>`}${mapInvitation()}</div>`}
