for(const item of R.trailers?.items||[]){if(!videos.some(v=>v.id===item.youtubeId))videos.push({id:item.youtubeId,title:item.title.en,by:item.medium,channel:item.uploader})}
for(const item of [...(R.videoLibrary?.items||[]),...(R.humor?.items||[])]){if(item.embeddable&&!item.externalUrl&&!videos.some(v=>v.id===item.id))videos.push({id:item.id,title:item.title.en,by:item.label,channel:item.uploader})}
for(const item of R.coachVideos||[])if(item.embeddable&&!videos.some(v=>v.id===item.id))videos.push({id:item.id,title:item.originalTitle||item.title.en,channel:item.channel});
const players = new Map();
const playerFrames = new Map();
const initializedFrames = new WeakSet();
let videoGeneration = 0;
let youtubeApiPromise = null;
function clearPlayers(){videoGeneration++;for(const p of players.values()){try{p.destroy()}catch{}}players.clear();playerFrames.clear()}
function getYouTubeAPI(){
 if(window.YT?.Player)return Promise.resolve(window.YT);
 if(youtubeApiPromise)return youtubeApiPromise;
 youtubeApiPromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.async=true;
  const fail=()=>{clearTimeout(timeout);script.remove?.();reject(new Error('Player API unavailable'))};
  const timeout=setTimeout(fail,18000);
  window.onYouTubeIframeAPIReady=()=>{if(!window.YT?.Player){fail();return}clearTimeout(timeout);resolve(window.YT)};
  script.onerror=fail;document.head.append(script);
 }).catch(error=>{youtubeApiPromise=null;throw error});
 return youtubeApiPromise;
}
async function loadPlayer(id,instance=id){
 const v=videos.find(x=>x.id===id);const shell=document.getElementById('video-'+instance);if(!v||!shell)return;
 const generation=videoGeneration;let measuredPlay=false;
 const f=shell.querySelector('iframe')||document.createElement('iframe');if(initializedFrames.has(f))return;initializedFrames.add(f);f.id='yt-'+instance;if(!f.src)f.src=`https://www.youtube-nocookie.com/embed/${id}?autoplay=0&controls=1&playsinline=1&enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}`;
 f.loading='lazy';f.title=v.title+' — '+v.channel;f.allow='accelerometer; encrypted-media; gyroscope; picture-in-picture; web-share';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';if(!f.isConnected)shell.replaceChildren(f);
 const status=document.getElementById('video-status-'+instance);if(status)status.textContent='';
 try{
  const YT=await getYouTubeAPI();if(generation!==videoGeneration||!f.isConnected)return;
  new YT.Player(f,{events:{
   onReady:e=>{if(generation===videoGeneration&&f.isConnected){const previous=players.get(instance);if(previous&&previous!==e.target){try{previous.destroy()}catch{}}players.set(instance,e.target);playerFrames.set(instance,f)}else e.target.destroy()},
   onStateChange:e=>{if(generation!==videoGeneration||!f.isConnected)return;if(e.data===YT.PlayerState.PLAYING){if(!measuredPlay){measuredPlay=A.track('video_play',{video_id:id})}for(const [otherId,p]of players)if(otherId!==instance){try{p.pauseVideo()}catch{}}}},
   onError:()=>{if(generation!==videoGeneration||!f.isConnected)return;if(status)status.textContent=t('הנגן לא הצליח לטעון כאן. נסו את הקישור הישיר ל־YouTube שמופיע מתחתיו.','The player could not load here. Try the direct YouTube link below.')}
  }});
 }catch{initializedFrames.delete(f);if(generation===videoGeneration&&f.isConnected&&status)status.textContent=t('תיאום הנגנים לא נטען. הפעילו נגן אחד בכל פעם, או פתחו את המקור ב־YouTube.','Player coordination did not load. Play one video at a time, or open the original on YouTube.')}
}

function mountPlayers(){for(const [key,p]of players)if(!playerFrames.get(key)?.isConnected){try{p.destroy()}catch{}players.delete(key);playerFrames.delete(key)}return Promise.all([...document.querySelectorAll('[data-video-shell]')].map(shell=>loadPlayer(shell.dataset.videoShell,shell.dataset.videoInstance||shell.dataset.videoShell)))}
function playerFrame(v,instance=v.id){const origin=window.location.origin||window.SITE_METADATA?.origin||'';return `<iframe id="yt-${esc(instance)}" src="https://www.youtube-nocookie.com/embed/${esc(v.id)}?autoplay=0&amp;controls=1&amp;playsinline=1&amp;enablejsapi=1&amp;origin=${encodeURIComponent(origin)}" title="${esc(v.title+' — '+v.channel)}" loading="lazy" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`}

function performerCredits(id,compact=false,secondary=false){const c=R.performerCredits?.[id];if(!c)return '';const people=c.performers||[];if(secondary)return secondaryPerformerCredits(c,people);const bio=p=>`<div class="performer-bio"><h4>${esc(t(p.nameHe,p.nameEn))}</h4><div class="performer-role">${esc(t(p.roleHe,p.roleEn))}</div><p>${esc(t(p.bioHe,p.bioEn))}</p>${p.bioUrl?external(p.bioUrl,t(p.bioLinkHe,p.bioLinkEn)):''}</div>`;return `<div class="performer-credits ${compact?'compact':''}"><div class="credit-kicker">${c.creditHeadingHe?esc(t(c.creditHeadingHe,c.creditHeadingEn)):t('על המבצעים','ABOUT THE PERFORMERS')}</div>${c.contextHe?`<p class="credit-context">${esc(t(c.contextHe,c.contextEn))}</p>`:''}${people.slice(0,2).map(bio).join('')}${people.length>2?`<details class="more-credits"><summary>${t('לעוד '+(people.length-2)+' אנשי צוות הסרט','Meet '+(people.length-2)+' more members of the film cast')}</summary>${people.slice(2).map(bio).join('')}</details>`:''}</div>`}
function secondaryPerformerCredits(c,people){const C=R.secondaryCreditCopy;return `<div class="performer-credits secondary-film-credits"><div class="credit-kicker">${esc(t(c.creditHeadingHe,c.creditHeadingEn))}</div><p class="credit-context">${esc(t(c.contextHe,c.contextEn))}</p><ul class="film-credit-names">${people.map(p=>`<li><b>${esc(t(p.nameHe,p.nameEn))}</b><span>${esc(t(p.roleHe,p.roleEn))}</span></li>`).join('')}</ul><details class="secondary-bios"><summary>${h(C.bioSummary)}</summary>${people.map(p=>`<div class="performer-bio"><h4>${esc(t(p.nameHe,p.nameEn))}</h4><p>${esc(t(p.bioHe,p.bioEn))}</p>${external(p.bioUrl,t(p.bioLinkHe,p.bioLinkEn))}</div>`).join('')}</details></div>`}
function videoReach(id){const r=R.videoReach?.[id];return r?`<p class="video-reach"><strong><bdi>${Number(r.views).toLocaleString('en-US')}</bdi> ${t('צפיות ב־YouTube','YouTube views')}</strong><small>${t('צילום מצב שנבדק ב־','Snapshot checked ')}<bdi>${esc(r.checkedDate)}</bdi> · ${external(r.sourceUrl,t('מקור הנתון','Count source'))}</small></p>`:''}
function videoBackground(id){const c=R.videoBackground?.[id];if(!c||c.reviewedChange!=='enriched')return '';return `<details class="video-background" data-video-background="${esc(id)}"><summary>${t('הסיפור שמאחורי הסרטון','The story behind this video')}</summary><div class="video-background-body"><div class="video-background-occasion">${h(c.occasion)}</div><p>${h(c.background)}</p>${c.watchFor?`<div class="video-background-question"><b>${t('כדאי לשים לב','SOMETHING TO NOTICE')}</b><p>${h(c.watchFor)}</p><small>${t('הצעת צפייה שלנו.','Our viewing prompt.')}</small></div>`:''}${sources(c.sourceIds)}</div></details>`}
function video(v,instance=v.id){return `<div class="video-wrap"><div class="video-shell" id="video-${esc(instance)}" data-video-shell="${esc(v.id)}" data-video-instance="${esc(instance)}">${playerFrame(v,instance)}</div><p class="video-status" id="video-status-${esc(instance)}" role="status"></p><div class="watch-link"><span>${t('העלה: ','UPLOADER: ')}${esc(v.channel==='הבימה - התיאטרון הלאומי'?t('הבימה - התיאטרון הלאומי','Habima National Theatre'):v.channel==='ליאור שליין Lior Schleien'?t('ליאור שליין','Lior Schleien'):v.channel)}</span>${external('https://www.youtube.com/watch?v='+v.id,t('ב־YouTube','On YouTube'))}</div>${videoBackground(v.id)}</div>`}
const listeningLenses={voice:{title:{he:'הקול',en:'The voice'},question:{he:'איזה רושם יוצר כל קול: ודאות, מתח, ספק, או משהו אחר? שימו לב גם לשקט שבין המשפטים.',en:'What impression does each voice create: certainty, tension, doubt, or something else? Notice the space between phrases, too.'}},body:{title:{he:'הגוף והמבט',en:'Body & gaze'},question:{he:'מה מספרים היציבה והמבט? השוו את כיוון הראש, הידיים והמרחק מן המצלמה. איזו תחושה נוצרת מכל בחירה?',en:'What do posture and gaze communicate? Compare the direction of the head, the hands and the distance from the camera. What impression does each choice create?'}},setting:{title:{he:'המסגרת',en:'The setting'},question:{he:'קונצרט מבוים מול הופעה טלוויזיונית: איך החלל, המצלמה והקהל משנים את הרגע?',en:'A staged concert and a television appearance: how do space, camera and audience shape the moment?'}}};
let currentLens='voice';
function performanceCard(v,letter,name,production,year){return `<article class="performance-card performance-${letter.toLowerCase()}" id="performance-${letter}" tabindex="-1"><header class="performance-head"><span class="performance-letter" aria-hidden="true">${letter}</span><div><span class="performance-label">${t('ביצוע','PERFORMANCE')} ${letter}</span><h3>${name}</h3><p>${production}</p><span class="performance-year">${year}</span></div></header>${video(v)}${performerCredits(v.id)}</article>`}
function performanceDoorways(){const groups=['on-my-own','one-day-more','bring-home'].map(id=>R.gallery.groups.find(g=>g.id===id)).filter(Boolean);return `<section class="hebrew-performance-doorways"><div><div class="eyebrow">${t('הקולות הקרובים לבית','THREE SONGS · TWO LANGUAGES')}</div><h2>${t('אותו שיר.<br>עברית ואנגלית.','The same song.<br>English and Hebrew.')}</h2><p>${t('מתחילים בביצוע בעברית, ואז אפשר לעבור לגרסה באנגלית. אלה ביצועים נפרדים של אותו שיר, מן הבמה ומן האולפן; החלפת הביצוע אינה מתרגמת את הסרטון.','Start with an English performance, then switch to Habima’s Hebrew version. These are separate stage and recorded interpretations of the same song; switching performances does not translate the video.')}</p></div><div>${groups.map(g=>{const x=galleryItem(galleryPreferred(g,lang));return `<button data-listen-song="${esc(g.songId)}" data-listen-video="${esc(x.id)}"><span>${h(x.title)}</span><small>${h(x.shortLabel||x.label)}</small>${arrow}</button>`}).join('')}</div></section>`}
let galleryCategory='all';
let galleryClip=null;
let galleryAudio='all';
const audioFilters=['all','en','he','other','zxx'];
function galleryItem(id){return R.gallery?.items.find(x=>x.id===id)}
function galleryGroup(id){return R.gallery?.groups.find(g=>g.clipIds.includes(id))}
function galleryAudioMatch(item,audio=galleryAudio){return audio==='all'||(audio==='other'?!['en','he','zxx'].includes(item.languageCode):item.languageCode===audio)}
function galleryVersions(group,locale=lang){return [...group.clipIds].sort((a,b)=>(galleryItem(b).languageCode===locale)-(galleryItem(a).languageCode===locale))}
function galleryPreferred(group,locale=lang,audio='all'){return galleryVersions(group,locale).find(id=>galleryAudioMatch(galleryItem(id),audio))||group.clipIds[0]}
function galleryGroups(category=galleryCategory,audio=galleryAudio){return R.gallery.groups.filter(g=>(category==='all'||g.category===category)&&g.clipIds.some(id=>galleryAudioMatch(galleryItem(id),audio)))}
function galleryHref(id=null,category='all',locale=lang,audio=route==='listening'?galleryAudio:'all'){const p=[];if(id)p.push('clip='+encodeURIComponent(id));if(category!=='all')p.push('category='+encodeURIComponent(category));if(audio!=='all'&&(!id||galleryAudioMatch(galleryItem(id)||{},audio)))p.push('audio='+audio);return `/${locale}/listening/`+(p.length?'?'+p.join('&'):'')}
function galleryReadLocation(alias=null){const params=new URLSearchParams(location.search||'');const allowed=['all',...(R.gallery?.categories||[]).map(c=>c.id)];galleryCategory=alias||(allowed.includes(params.get('category'))?params.get('category'):'all');galleryAudio=audioFilters.includes(params.get('audio'))?params.get('audio'):'all';galleryClip=galleryItem(params.get('clip'))?.id||null;if(galleryClip&&galleryCategory!=='all'&&galleryGroup(galleryClip)?.category!==galleryCategory)galleryCategory='all';if(galleryClip&&!galleryAudioMatch(galleryItem(galleryClip)))galleryAudio='all'}
function galleryGo(id=null,category=galleryCategory,replace=false,audio=galleryAudio){pendingBookmark=null;const previousClip=galleryClip;galleryClip=galleryItem(id)?.id||null;if(galleryClip&&galleryClip!==previousClip)A.track('video_open',{video_id:galleryClip});galleryCategory=category;galleryAudio=audioFilters.includes(audio)?audio:'all';if(galleryClip&&!galleryAudioMatch(galleryItem(galleryClip)))galleryAudio='all';const previous=history.state?.lesmisJourney||null;const j=journeyPaths.find(x=>x.id===previous&&x.pages.includes('listening'))?.id||null;if(previous&&!j)A.track('journey_offroute',{journey_id:previous,from_page:route,to_page:'listening'});const path=galleryHref(galleryClip,galleryCategory);history[replace?'replaceState':'pushState'](j?{lesmisJourney:j}:null,'',path);focusAfterRender=false;render();const target=document.getElementById(galleryClip?'gallery-detail':'gallery-choices');target?.focus({preventScroll:true});target?.scrollIntoView({block:'start'})}
function galleryLanguageLabel(code){return ({en:t('אנגלית','English'),he:t('עברית','Hebrew'),ja:t('יפנית','Japanese'),fr:t('צרפתית','French'),zxx:t('ללא מילים','Instrumental'),und:t('שפת הביצוע לא אומתה','Audio language not verified')})[code]||t('שפה נוספת','Another language')}
function galleryLanguageBadges(group){return `<div class="gallery-language-badges" aria-label="${t('שפות הביצועים המקוריים','Original performance languages')}">${[...new Set(group.clipIds.map(id=>galleryItem(id).languageCode))].map(code=>`<span class="${code==='he'?'hebrew':''}">${esc(galleryLanguageLabel(code))}</span>`).join('')}</div>`}
function galleryLanguageFilters(){return `<div class="gallery-audio-filter"><span id="gallery-audio-label">${t('שפת הדיבור או השירה המקורית','Original spoken or sung language')}</span><div role="group" aria-labelledby="gallery-audio-label">${audioFilters.map(code=>`<button class="filter ${galleryAudio===code?'active':''}" data-gallery-audio="${code}" aria-pressed="${galleryAudio===code}">${code==='all'?t('כל השפות','All languages'):code==='other'?t('שפות נוספות / לא אומת','Other / not verified'):galleryLanguageLabel(code)} <span>(${galleryGroups(galleryCategory,code).length})</span></button>`).join('')}</div><small>${t('שפת הממשק אינה שפת הסרטון. הרקע והקרדיטים זמינים בשתי השפות; כתוביות תלויות במקור.','The interface language does not change a video’s audio. Context and credits are in both languages; captions depend on the source.')}</small></div>`}
function galleryReading(group){const r=group.reading;if(!r||(r.spoilerLevel>1&&!spoiler))return '';return `<section class="gallery-reading" aria-labelledby="gallery-reading-title"><div class="eyebrow">${t('לקרוא את הרגע','READ THE MOMENT')}</div><h3 id="gallery-reading-title">${h(r.title)}</h3><p>${h(r.scene)}</p><p>${h(r.structure)}</p><h4>${t('מבט על הביצוע','Watch the choices')}</h4><p>${h(r.watchFor)}</p><p class="source-caution">${t('מקורות: כוללים ספוילרים לעלילה המלאה.','Sources include full-plot spoilers.')}</p>${sources(r.sourceIds)}</section>`}
function galleryLesson(group){if(group.id==='stars-pair')return `${galleryReading(group)}${songReading(group.songId,'gallery')}<section class="gallery-lesson"><h3>${t('אותו שיר. שתי פרשנויות.','One song. Two interpretations.')}</h3><p>${t('בחרו ביצוע א׳ או ב׳, ואז שאלה אחת. אפשר לעקוב אחר המשחק, המסגור או הקול, ולבדוק מה משתנה בפרשנות.','Choose performance A or B, then one question. Follow the acting, framing or voice, and consider what changes in the interpretation.')}</p><div class="filter-row">${Object.entries(listeningLenses).map(([id,l])=>`<button data-lens="${id}" class="filter ${currentLens===id?'active':''}" aria-pressed="${currentLens===id}">${h(l.title)}</button>`).join('')}</div><p id="lens-question">${h(listeningLenses[currentLens].question)}</p>${check('stars')}</section>`;return `${galleryReading(group)}${songReading(group.songId,'gallery')}<section class="gallery-lesson"><h3>${t('שאלה לקחת לביצוע','A question to take into the performance')}</h3><p>${h(group.question)}</p>${group.checkKey?check(group.checkKey):''}</section>`}
function galleryDetail(){const item=galleryItem(galleryClip),group=galleryGroup(galleryClip);if(!item||!group)return '';return `<section class="gallery-detail" id="gallery-detail" tabindex="-1" aria-labelledby="gallery-detail-title"><div class="gallery-detail-top"><div><div class="eyebrow">${h(R.gallery.categories.find(c=>c.id===group.category)?.label)}</div><h2 id="gallery-detail-title">${h(group.title)}</h2></div><button class="gallery-close" data-gallery-close aria-label="${t('סגירת הביצוע וחזרה לבחירה','Close performance and return to choices')}">×</button></div>${group.languageNote?`<p class="gallery-language-note">${h(group.languageNote)}</p>`:''}${group.clipIds.length>1?`<div class="gallery-versions" role="group" aria-label="${t('בחירת גרסה','Choose a version')}">${galleryVersions(group).map((id,i)=>{const v=galleryItem(id);return `<button data-gallery-clip="${id}" aria-pressed="${id===galleryClip}" class="${id===galleryClip?'active':''}"><span>${String.fromCharCode(65+i)}</span><div><b>${h(v.shortLabel||v.title)}</b><small>${esc(galleryLanguageLabel(v.languageCode))} · ${h(v.label)}</small></div></button>`}).join('')}</div>`:''}<div class="gallery-detail-grid"><div>${item.spoilerLevel===2&&!spoiler?gallerySpoilerGate():addedMedia(item)}</div><aside>${item.spoilerLevel===2&&!spoiler?'':galleryLesson(group)}<div class="gallery-path-links">${group.songId?`<button class="text-link" data-gallery-song="${esc(group.songId)}">${t('איפה השיר נמצא במחזמר?','Where does this song sit in the musical?')}${arrow}</button>`:''}${link('musical',t('אל המחזמר והיוצרים','Explore the musical and its creators'),'text-link')}</div></aside></div></section>`}
function galleryCardReach(id){const r=R.videoReach?.[id];return r?`<span class="gallery-reach"><bdi>${(r.views/1000000).toFixed(1)}m</bdi> ${t('צפיות · 10.10.2026','views · 10 Oct 2026')}</span>`:''}
function galleryCards(){const groups=galleryGroups();if(!groups.length)return `<div class="gallery-empty"><h3>${t('אין כרגע בחירה בשילוב הזה','No selection matches this combination yet')}</h3><p>${t('אפשר לשנות שפה או לחזור לכל האוסף.','Try another language, or return to the full collection.')}</p><button class="btn" data-gallery-reset>${t('לכל הבחירות והשפות','Show all selections and languages')}</button></div>`;return groups.map(g=>{const first=galleryPreferred(g,lang,galleryAudio);return `<article class="gallery-card ${g.clipIds.includes(galleryClip)?'selected':''}"><div class="gallery-card-meta"><span>${String(R.gallery.groups.indexOf(g)+1).padStart(2,'0')}</span><b>${h(R.gallery.categories.find(c=>c.id===g.category)?.label)}</b></div><h3>${h(g.title)}</h3>${galleryLanguageBadges(g)}<p>${h(g.hook)}</p><small>${h(g.format)}</small>${galleryCardReach(first)}<a class="gallery-card-link" href="${esc(galleryHref(first,galleryCategory))}" data-gallery-link="${first}" aria-label="${esc(tr(g.title)+' — '+t('לפתוח את הביצוע והסיפור','Open the performance and its story'))}">${t('לפתוח את הביצוע והסיפור','Open the performance and its story')}${arrow}</a></article>`}).join('')}
function listeningPage(){const G=R.gallery;if(!G)return legacyListeningPage();const count=galleryGroups().length;return top(t('ביצועים ששווה<br>לראות.','Performances worth<br>watching.'),t('במה גדולה, סלון משפחתי, קולות שנפגשים ובדיחה במקום הנכון. מבחר אחד, עם הסיפור שמאחורי כל בחירה.','A grand stage, a family living room, voices coming together and a well-placed joke. One collection, with the story behind every choice.'),t('03 / סיבה טובה לצפות','03 / A GOOD REASON TO PRESS PLAY'))+`<div class="wrap gallery-room"><div class="gallery-intro"><p>${t('בחרנו לפי הרגע, המבצעים והרעיון, ולא רק לפי מונה הצפיות. בחרו ביצוע והנגן יופיע כאן, בלי הפעלה אוטומטית; מחוות עצמאיות מסוימות נפתחות אצל היוצרים.','Chosen for the occasion, performers and idea, not just the view count. Choose a performance and its player appears here, without autoplay; some independent tributes open with their creators.')}</p><span>${G.groups.length} ${t('בחירות · ארבע זוויות','selections · four angles')}</span></div><div class="gallery-categories" role="group" aria-label="${t('קטגוריות צפייה','Viewing categories')}">${G.categories.map(c=>`<button data-gallery-category="${c.id}" aria-pressed="${galleryCategory===c.id}" class="${galleryCategory===c.id?'active':''}"><span aria-hidden="true">${c.symbol}</span><b>${h(c.label)}</b><small>${h(c.description)} · ${galleryGroups(c.id).length}</small></button>`).join('')}</div>${performanceDoorways()}${galleryLanguageFilters()}<div class="gallery-filter-status"><button class="filter ${galleryCategory==='all'?'active':''}" data-gallery-category="all" aria-pressed="${galleryCategory==='all'}">${t('כל הבחירות','All selections')}</button><p role="status">${count} ${t('בחירות בתצוגה הזאת','selections in this view')}</p></div>${galleryDetail()}<section id="gallery-choices" tabindex="-1" aria-label="${t('בחירת ביצוע','Choose a performance')}"><div class="gallery-grid">${galleryCards()}</div></section><div class="gallery-editor-note"><h2>${t('עוד דרך להקשיב, לא עוד אינסוף קישורים.','Another way to listen, not an endless list.')}</h2><p>${t('ההשוואות, הרקע והקרדיטים נמצאים בתוך כל בחירה. אפשר להגיע לכאן גם ישירות מתוך השיר במדריך המחזמר. הסרטונים עשויים לכלול ספוילרים; קראו את הערת הצפייה לפני הצפייה.','Comparisons, background and credits sit inside each selection. You can also arrive directly from a song in the musical guide. Videos may contain spoilers; read the viewing note before watching.')}</p></div></div>`}
function gallerySongLinks(songId){const groups=R.gallery?.groups.filter(g=>g.songId===songId)||[];if(!groups.length)return '';return `<section class="song-gallery-door"><div class="eyebrow">${t('מהשיר אל הביצוע','FROM SONG TO PERFORMANCE')}</div><h4>${t('לשמוע איך זה מקבל חיים','Hear it come to life')}</h4><div class="song-gallery-links">${groups.flatMap(g=>galleryVersions(g).map(id=>{const item=galleryItem(id);return `<a href="${esc(galleryHref(id))}" data-gallery-link="${id}"><b>${h(item.shortLabel||item.title)}</b><span>${item.provider?h(item.provider)+' · ':''}${h(item.language)} · ${item.embeddable?t('נגן בתוך העמוד','inline player'):t('קישור למקור','original-source link')}</span>${arrow}</a>`})).join('')}</div></section>`}

function gallerySpoilerGate(){return `<div class="gallery-spoiler-gate"><span class="tag">${t('מכיל ספוילרים משמעותיים','CONTAINS MAJOR SPOILERS')}</span><h3>${t('רגע לפני ההקשר והביצוע','Before the context and performance')}</h3><p>${t('הסרטון והרקע שלו נוגעים בחלקים מאוחרים ובסיום הסיפור. נפתח אותם רק אחרי שתבחרו.','This video and its background concern late-story events and the ending. They open only after you choose.')}</p><button class="btn" data-gallery-reveal>${t('קראתי. לפתוח עם ספוילרים','I understand. Open with spoilers')}${arrow}</button></div>`}

function legacyListeningPage(){return top(t('אותו שיר.<br>שתי נקודות מבט.','One song.<br>Two points of view.'),t('צפו בביצוע א׳, עברו לביצוע ב׳, ובחרו דבר אחד להקשיב לו. שני מבצעים, מקום אחד להשוואה.','Watch A, switch to B, and choose one thing to listen for. Two performers, one place to compare.'),t('03 / חדר ההקשבה','03 / THE LISTENING ROOM'))+`<div class="wrap listening-room"><nav class="listening-index" aria-label="${t('חדרי ההקשבה','Listening sections')}"><button data-jump="stars-lab"><span>01</span> Stars <small>${t('השוואת ביצועים','Compare performances')}</small></button><button data-jump="prayer-lab"><span>02</span> Bring Him Home <small>${t('זמר ומלחין','Singer & composer')}</small></button><button data-jump="screen-lab"><span>03</span> One Day More <small>${t('מן הבמה למסך','Stage to screen')}</small></button></nav><section class="comparison-stage" id="stars-lab"><div class="comparison-title"><div><div class="eyebrow">${t('מעבדה 01 · אותו שיר, שני מבצעים','LAB 01 · SAME SONG, TWO PERFORMERS')}</div><h2 lang="en">Stars</h2><p>${t('מייקל בול ובראדלי ג׳יידן, שניהם כז׳אבר. אותו שיר, שתי דרכים לגלם אותו.','Michael Ball and Bradley Jaden, both as Javert. One song, two ways of inhabiting the role.')}</p></div><div class="comparison-instructions"><span><b>1</b>${t('צופים בא׳','Watch A')}</span><span><b>2</b>${t('עוברים לב׳','Switch to B')}</span><span><b>3</b>${t('שמים לב להבדל','Notice a difference')}</span></div></div><div class="pair-toolbar"><div class="player-coordination"><span aria-hidden="true">♫</span>${t('קול אחד בכל פעם. אם נשמעים שניים, עצרו אחד ידנית.','One voice at a time. If both play, pause one manually.')}</div></div><div class="performance-pair">${performanceCard(videos[1],'A',t('מייקל בול','Michael Ball'),t('The Staged Concert · תיאטרון גילגוד, לונדון','The Staged Concert · Gielgud Theatre, London'),'2019')}${performanceCard(videos[2],'B',t('בראדלי ג׳יידן','Bradley Jaden'),'Musical Awards: The Kick-Off · AVROTROS','2024')}</div><div class="mobile-player-nav"><button data-jump="performance-A">${t('לביצוע א׳','Go to A')}</button><button data-jump="performance-B">${t('לביצוע ב׳','Go to B')}</button></div><div class="listening-lens"><div><span class="eyebrow">${t('בחרו עדשה אחת להקשבה','PICK ONE LISTENING LENS')}</span><div class="lens-buttons" role="group" aria-label="${t('מה להקשיב לו','What to listen for')}">${Object.entries(listeningLenses).map(([id,l])=>`<button data-lens="${id}" class="${id===currentLens?'active':''}" aria-pressed="${id===currentLens}">${h(l.title)}</button>`).join('')}</div></div><p id="lens-question" aria-live="polite">${h(listeningLenses[currentLens].question)}</p></div><div class="lab-foot"><p>${t('ההקלטה של בול היא מ־2019; העלאת הקטע ל־YouTube היא מ־2024. ג׳יידן מופיע כאן בשידור טלוויזיה לקידום סיבוב ההופעות, ולא בצילום מתוך הסיבוב עצמו.','Ball’s concert recording is from 2019; this YouTube clip was uploaded in 2024. Jaden appears here in a television performance promoting the tour, rather than footage filmed during the tour.')}</p>${check('stars')}</div>${sources(['stars-ball-credit','stars-jaden-credit'])}</section>
<section class="solo-lab" id="prayer-lab"><div class="solo-lab-heading"><div class="eyebrow">${t('מעבדה 02 · זמר אחד, המלחין לידו','LAB 02 · A SINGER, WITH THE COMPOSER')}</div><h2 lang="en">Bring Him Home</h2><p>${t('אלפי בו שר. קלוד־מישל שנברג מלווה בפסנתר. כאן מקשיבים למפגש בין שני אנשים ולמרווח שבין כוח לעדינות.','Alfie Boe sings. Claude-Michel Schönberg accompanies him at the piano. Listen to their meeting, and to the space between power and tenderness.')}</p></div><div class="solo-lab-grid"><div>${video(videos[0])}<p class="production-caption">${t('מתוך סיבוב ההופעות Bring Him Home של אלפי בו · רויאל פסטיבל הול, לונדון.','From Alfie Boe’s Bring Him Home Tour · Royal Festival Hall, London.')}</p></div><div><div class="single-question"><span>${t('שאלה אחת להקשבה','ONE LISTENING QUESTION')}</span><p>${t('איך הפסנתר והשקט שבין המשפטים משפיעים על הדרך שבה אתם שומעים את הקול?','How do the piano and the space between phrases affect the way you hear the voice?')}</p></div>${check('prayer')}${performerCredits(videos[0].id)}</div></div></section>
<section class="screen-lab" id="screen-lab"><div class="solo-lab-heading"><div class="eyebrow">${t('מעבדה 03 · קודם השיר, אחר כך מאחורי הקלעים','LAB 03 · THE SONG, THEN BEHIND THE SCENES')}</div><h2 lang="en">One Day More</h2><p>${t('צופים בקטע מן הבמה למסך, ואז מציצים אל תהליך השירה והצילום של הסרט.','Watch the stage-to-screen selection, then go behind the scenes of the film’s singing and recording process.')}</p></div><div class="film-pair"><article><div class="film-step"><b>1</b><div><h3>${t('השיר והמסך','The song on screen')}</h3><p>One Day More · Stage to Screen</p></div></div>${video(videos[3])}<div class="single-question"><p>${t('איזה קול מושך את האוזן שלכם כשכמה דמויות חולקות רגע אחד?','Which voice draws your ear when several characters share a moment?')}</p></div>${performerCredits(videos[3].id)}</article><article><div class="film-step"><b>2</b><div><h3>${t('איך צילמו את השירה?','How was the singing filmed?')}</h3><p>Singing Live · 2012 film featurette</p></div></div>${video(videos[4])}<div class="single-question"><p>${t('מה מסביר צוות הסרט על דרך העבודה שלו, ומה זה משנה לכם כצופים?','What does the film team explain about its process, and what does that change for you as a viewer?')}</p></div>${performerCredits(videos[4].id,false,true)}</article></div>${check('ensemble')}</section><aside class="journey-strip"><div><span class="small">${t('מסע ההקשבה שלי','MY LISTENING JOURNEY')}</span><strong id="progress-text">${checked.length} / 3</strong><div class="progress-bar"><i id="progress-fill" style="width:${Math.min(checked.length,3)/3*100}%"></i></div></div><p>${t('הסימונים זמניים לביקור הזה. כדי לזכור אותם לפעם הבאה, אפשר לאפשר זכירת העדפות בהגדרות הפרטיות.','Checkmarks last for this visit. To remember them next time, enable remembered preferences in privacy settings.')}</p><button data-action="reset-checklist">${t('איפוס הסימונים','Reset checkmarks')}</button></aside><div class="media-policy"><p>${t('הנגנים הם נגני YouTube מקוריים, במצב פרטיות משופרת. הם מוצגים ישירות, ללא הפעלה אוטומטית; זמינות וכתוביות תלויות במפרסמים ובמדינה. הקישורים למקור זמינים תמיד.','These are native YouTube players in privacy-enhanced mode. They appear directly without autoplay; availability and captions depend on publishers and region. Original-source links remain available.')}</p></div><div class="link-box"><h3>${t('וכשהקהל מצטרף?','And when the audience joins in?')}</h3><p>${t('מחוות בחתונות, בקניון ובאולפן הביתי, עם קרדיט למי שיצרו אותן.','Tributes at weddings, in a shopping centre and in creators’ studios, with the people behind them credited.')}</p>${link('tribute',t('למחוות מחוץ לבמה','Explore the tributes'),'text-link')}</div>${performanceDoorways()}</div>`}
function check(id){return `<label class="check-label"><input type="checkbox" data-check="${id}" ${checked.includes(id)?'checked':''}>${t('ביקרתי במעבדה הזאת','I’ve visited this lab')}</label>`}
function comparisonExtra(data){if(!data)return '';return `<div class="comparison-example"><h4>${t('עוד פרט שמאיר את ההבדל','Another detail, up close')}</h4><p>${data.sentences.map(h).join(' ')}</p><div class="source-links">${data.references.map(ref=>external(ref.url,tr(ref.label))).join('')}</div></div>`}
function comparisonJourney(){return `<nav class="comparison-index" aria-label="${t('קפיצה להשוואה','Jump to a comparison')}">${R.differences.map((d,i)=>`<button data-jump="compare-${esc(d.id)}"><span>${String(i+1).padStart(2,'0')}</span>${h(d.kicker||d.title)}</button>`).join('')}</nav>${R.differences.map((d,i)=>`<article id="compare-${esc(d.id)}" class="adaptation-card"><header class="adaptation-heading"><span class="adaptation-number">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow">${h(d.kicker||d.title)}</div><h2>${h(d.title)}</h2></div></header>${d.change?`<div class="adaptation-change"><b>${t('מה השתנה?','WHAT CHANGED?')}</b><p>${h(d.change)}</p></div>`:''}<div class="adaptation-pair"><section class="adaptation-side adaptation-book"><div class="adaptation-medium"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 12C16 7 9 7 4 9v29c7-2 13-1 20 3 7-4 13-5 20-3V9c-5-2-12-2-20 3zm0 0v29" fill="none" stroke="currentColor" stroke-width="2"/></svg><div><span>${t('דף','PAGE')}</span><h3>${t('ברומן של הוגו','In Hugo’s novel')}</h3></div></div><p>${h(d.novel)}</p></section><section class="adaptation-side adaptation-stage"><div class="adaptation-medium"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M5 8h38v32H5zM5 9c0 13 8 17 16 17M43 9c0 13-8 17-16 17M5 40l9-16M43 40l-9-16M5 34h38" fill="none" stroke="currentColor" stroke-width="2"/></svg><div><span>${t('במה','STAGE')}</span><h3>${t('במחזמר הבימתי','In the stage musical')}</h3></div></div><p>${h(d.stage)}</p></section></div><div class="adaptation-reading"><span>${t('הקריאה שלנו','OUR READING')}</span><h3>${t('מה זה משנה לחוויה?','What changes for us?')}</h3><p>${h(d.why)}</p></div>${d.closeLook?`<details class="adaptation-depth"><summary>${h(d.closeLook.title)}</summary><p>${h(d.closeLook.body)}</p>${comparisonExtra(d.enrichment)}${d.referenceLabel?`<div class="adaptation-reference"><b>${t('איפה זה ברומן?','WHERE IN THE NOVEL?')}</b><span>${h(d.referenceLabel)}</span></div>`:''}${sources(d.sourceIds)}</details>`:sources(d.sourceIds)}${d.question?`<div class="adaptation-question"><span aria-hidden="true">?</span><div><b>${t('שאלה לקחת איתכם','A QUESTION TO TAKE WITH YOU')}</b><p>${h(d.question)}</p></div></div>`:''}</article>`).join('')}<div class="adaptation-next"><div><h2>${t('אותו סיפור, עוד דרך לראות.','The same story. Another way to see it.')}</h2><p>${t('אפשר לחזור לציר הזמן של הרומן, או לשמוע איך מבצע הופך מחשבה למשהו שמתרחש עכשיו.','Return to the novel’s timeline, or listen to a performer turn a thought into something happening now.')}</p></div><div class="button-row">${link('novel',t('אל חלקי הרומן','Explore the novel'),'btn secondary')}${link('listening',t('בחזרה לאוזניים','Back to listening'),'btn secondary')}</div></div>`}
function comparePage(){return top(t('מאות עמודים.<br>ערב אחד על במה.','Hundreds of pages.<br>One night on stage.'),t('שש בחירות של עיבוד, זו לצד זו. מה עבר לבמה, מה נשאר בין הדפים, ומה כל דרך מאפשרת לנו להרגיש ולהבין.','Six adaptation choices, side by side. What reaches the stage, what stays on the page, and what each form lets us feel and understand.'),t('04 / מהספר לבמה','04 / PAGE → STAGE'))+`<div class="wrap section"><div class="intro-box"><h3>${t('אפשר לאהוב את שתיהן, ולהסתקרן מההבדלים','You can love both and still be curious about the differences')}</h3><p>${t('לפעמים פרט קטן שנעלם משנה את כל הדרך שבה קוראים דמות. לפעמים קיצור הופך לרגע בימתי חזק. התחילו בהשוואה שמסקרנת אתכם, קראו את שני הצדדים, ואז פתחו את המבט מקרוב.','Sometimes a small missing detail changes how we read a character. Sometimes compression creates a powerful stage moment. Choose a comparison, read both sides, then open the closer look.')}</p></div>${!spoiler?gate('compare'):banner()+comparisonJourney()}<div class="note" style="margin-top:30px">${t('נקודות הייחוס הן הרומן של הוגו ותקציר MTI לגרסה הבימתית המורשית של מסע ההופעות הבריטי מ־2009. אין זו השוואה לסרט המוזיקלי מ־2012. נוסחים, פרטים וסדרי שירים עשויים להשתנות בין הפקות; גם תרגומים של הרומן עשויים להשתמש בשמות שונים. היות המקור הצרפתי בנחלת הכלל אינה הופכת תרגומים חדשים, מילים, תווים או הקלטות לחופשיים.','The reference points are Hugo’s novel and MTI’s licensed “UK Tour Version (2009)” stage synopsis. This is not a comparison with the 2012 musical film. Text, details and song order can vary by production; novel translations may also use different names. The French original’s public-domain status does not make modern translations, lyrics, scores or recordings free to reuse.')}<div class="source-links">${external('https://www.mtishows.co.uk/les-miserables',t('פרטי הגרסה ב־MTI','Version details at MTI'))}</div></div></div>`}

function officialTrailers(){return `<section class="screen-gallery-invitation"><div class="eyebrow">${t('מהמסך אל הביצוע','FROM SCREEN TO PERFORMANCE')}</div><h2>${t('רוצים לראות איך זה נשמע?','Want to see how it sounds?')}</h2><p>${t('הביצועים שבחרנו מחכים באוסף אחד, עם הקשר, קרדיטים והשוואות.','Our selected performances live in one collection, with context, credits and comparisons.')}</p>${link('listening',t('אל הביצועים ששווה לראות','Explore performances worth watching'))}<details class="trailer-source-notes"><summary>${t('מקורות לצפייה: טריילרים וקטעי הפקה','Viewing references: trailers and production films')}</summary><p>${t('הקישורים נפתחים אצל המפרסמים. הם עשויים לכלול ספוילרים.','These links open with their publishers and may contain spoilers.')}</p>${R.trailers.items.map(x=>`<article><h3>${external('https://www.youtube.com/watch?v='+x.youtubeId,tr(x.title))}</h3><p>${h(x.value)}</p><small>${esc(x.uploader)} · ${esc(x.productionYear)} · ${t('הועלה','uploaded')} ${esc(x.uploadDate)}</small></article>`).join('')}</details></section>`}

function screenLineage(){const F=R.screenFamilies;return `<section class="screen-lineage"><div><h2>${h(F.title)}</h2><p>${h(F.intro)}</p></div><div class="screen-branches">${F.families.map((f,i)=>`<article><span class="branch-number">0${i+1}</span><div><h3>${h(f.label)}</h3><p>${h(f.description)}</p>${sources(f.sourceIds)}</div></article>`).join('')}</div><p class="screen-family-question">${h(F.question)}</p></section>`}
function screenPage(){return top(t('סיפור אחד.<br>יותר מעדשה אחת.','One story.<br>More than one lens.'),t('תשע תחנות נבחרות בקולנוע, בטלוויזיה ובקונצרט המצולם. חלקן מעבדות את הרומן; אחרות נולדו מן המחזמר.','Nine selected stops in film, television and filmed concert. Some adapt the novel; others come from the musical.'),t('05 / על המסך','05 / ON SCREEN'))+`<div class="wrap section"><div class="note">${h(R.screenNote||{he:'מבחר אצור, לא רשימה של כל העיבודים. דפי המקור עשויים לכלול ספוילרים. זמינות, מחירים וכתוביות משתנים לפי מדינה וספק.',en:'A curated selection, not a list of every adaptation. Source pages may contain spoilers. Availability, prices and subtitles vary by region and provider.'})}</div>${screenLineage()}<div class="screen-section-jumps"><button class="btn secondary" data-jump="screen-grid">${t('9 תחנות בעיבודים','9 adaptation landmarks')}</button><button class="btn" data-jump="screen-videos">${t('7 הצצות רשמיות','7 official production videos')}${arrow}</button></div><div class="filter-row" role="group" aria-label="${t('סינון עיבודים','Filter adaptations')}">${[['all',t('הכול','All')],['film',t('קולנוע · הרומן','Film · the novel')],['tv',t('טלוויזיה','Television')],['musical',t('המחזמר והקונצרט','Musical & concert')]].map(([id,l])=>`<button class="filter ${screenFilter===id?'active':''}" data-screen-filter="${id}" aria-pressed="${screenFilter===id}">${l}</button>`).join('')}</div><p id="screen-count" class="small muted" aria-live="polite" style="margin-bottom:20px">${screenRecords().length} ${t('עיבודים מוצגים','entries shown')}</p><div class="screen-grid" id="screen-grid">${screenCards()}</div>${officialTrailers()}<div class="link-box"><h3>${t('שאלת צפייה אחת, לכל הגרסאות','One viewing question for every version')}</h3><p>${t('איפה העיבוד נותן לנו להתעכב: על פנים, על מוסדות, על רחוב, על שיר? מה שאנחנו רואים יותר ממנו משנה את הסיפור שאנחנו מרגישים.','Where does an adaptation let us linger: on a face, an institution, a street, a song? What we see more of changes the story we feel.')}</p>${link('compare',t('לעוד החלטות של עיבוד','More adaptation choices'),'text-link')}</div></div>`}
function screenRecords(){return (R.adaptations||[]).filter(s=>screenFilter==='all'||s.type===screenFilter)}
function screenCards(){return screenRecords().map(s=>`<article class="screen-card"><span class="year">${esc(s.year)}</span><div><div class="format">${h(s.format)}</div><span class="screen-family">${h(R.screenFamilies.families.find(f=>f.id===R.screenFamilyMap[s.id])?.label)}</span><h2>${h(s.title)}</h2><p>${h(s.summary)}</p><p class="lens"><b>${t('בזמן הצפייה: ','WATCHING LENS: ')}</b>${h(s.lens)}</p>${s.watchUrl?`<div class="screen-watch">${external(s.watchUrl,t('לעמוד הצפייה הרשמי','Official viewing page'))}<small>${h(s.watchNote)}</small></div>`:''}${sources(s.sourceIds)}</div></article>`).join('')}
function tributePage(){return top(t('התיאטרון נגמר.<br>השירה ממשיכה.','The theatre closes.<br>The singing goes on.'),t('מחוות בחתונות, בקניון ובאולפן הביתי. לא כל סרטון ברשת, אלא מבחר קטן עם מקור שאפשר לעקוב אחריו.','Tributes at weddings, in a shopping centre and in creators’ studios. A small, traceable selection rather than every video on the internet.'),t('06 / מעבר לבמה','06 / BEYOND THE STAGE'))+`<div class="wrap section"><div class="intro-box"><h3>${t('הקהל לוקח את התור','The audience takes a turn')}</h3><p>${t('שיר שנכתב לדמות יכול להפוך גם למחווה בין אנשים. כיף לראות את ההקשר החדש, בלי לשכוח שהמקור מספר גם על אובדן, עוני ומאבק.','A song written for a character can become a gesture between people. Enjoy its new setting without forgetting that the original also speaks of loss, poverty and struggle.')}</p></div><div class="note">${t('המחוות נפתחות אצל היוצרים. הסרטונים עשויים לכלול ספוילרים.','Tributes open on their creators’ pages. Videos may contain spoilers.')}</div><div class="filter-row" role="group" aria-label="${t('סינון מחוות','Filter tributes')}">${[['all',t('כל המחוות','All tributes')],['wedding',t('חתונות','Weddings')],['flashmob',t('קניונים ופלאש־מוב','Shopping centres & flash mobs')],['creator',t('ביצועים מיוחדים','Creator performances')]].map(([id,l])=>`<button class="filter ${tributeFilter===id?'active':''}" data-tribute-filter="${id}" aria-pressed="${tributeFilter===id}">${l}</button>`).join('')}</div><p id="tribute-count" class="small muted" aria-live="polite" style="margin-bottom:20px">${tributeRecords().length} ${t('מחוות מוצגות','tributes shown')}</p><div class="tribute-grid" id="tribute-grid">${tributeCards()}</div><div class="link-box lockdown-invitation"><h3>${t('עוד יום, בסלון','One more day, in the living room')}</h3><p>${t('איך הפך One Day More לשיר על החיים בסגר? משפחת מארש מופיעה בפרק ההומור, עם ההקשר של מרץ 2020 וקישור ליוצרים.','How did One Day More become a song about lockdown life? Meet the Marsh Family in the humor section, with its March 2020 context and a link to the creators.')}</p>${link('humor',t('אל הסיפור והסרטון','Explore the story and clip'))}</div><div class="link-box"><h3>${t('רעיון לצפייה: מה השתנה כשכולם הכירו את השיר?','A viewing thought: what changes when everyone knows the song?')}</h3><p>${t('שימו לב למרחק בין במה לקהל. האם המצלמה מחפשת את הזמרים, או את מי שמופתעים לשמוע אותם?','Notice the distance between performers and audience. Does the camera look for the singers, or for the people surprised to hear them?')}</p></div></div>`}
function tributeRecords(){return (R.tributes||[]).filter(s=>tributeFilter==='all'||s.category===tributeFilter)}
function tributeCards(){return tributeRecords().map((s,i)=>`<article class="tribute-card">${s.id==='DXgCrhIevwU'?video(videos.find(v=>v.id===s.id)):`<div class="tribute-art art-${esc(s.category)}" aria-hidden="true"><span>${s.category==='wedding'?'&':s.category==='flashmob'?'Σ':'×'}</span><small>${s.category==='wedding'?'A SONG FOR TWO':s.category==='flashmob'?'MANY VOICES, ONE SPACE':'ONE SONG, NEW POSSIBILITIES'}</small></div>`}<div class="tribute-body"><div class="eyebrow">${h(s.categoryLabel)}</div><h2>${h(s.title)}</h2><p class="small muted">${esc(s.creator)} · ${esc(s.year)}</p>${videoReach(s.id)}<p style="margin-top:15px">${h(s.summary)}</p><div class="tribute-question"><b>${h(R.tributePrompts.questionLabel)}</b><p>${h(R.tributePrompts.items.find(x=>x.id===s.id)?.watchQuestion)}</p><small>${h(R.tributePrompts.interpretationNote)}</small></div><p class="lens"><b>${h(R.tributePrompts.sourceLabel)}: </b>${h(s.lens)}</p><div class="button-row">${external(s.url,t('למחווה במקור','Open the original tribute'))}</div><p class="rights-note">${h(s.note)}</p>${s.id!=='DXgCrhIevwU'?videoBackground(s.id):''}${performerCredits(s.id,true)}${sources(s.sourceIds)}</div></article>`).join('')}
function bibliography(){const map=new Map();for(const s of R.sources){if(!map.has(s.url))map.set(s.url,{url:s.url,label:s.label,aliases:[],groups:new Set()});const item=map.get(s.url);item.aliases.push(s);for(const g of R.sourceGroups)if(g.sourceIds.includes(s.id))item.groups.add(g.id)}return [...map.values()].map(x=>({...x,groups:[...x.groups],search:x.aliases.map(a=>typeof a.label==='object'?Object.values(a.label).join(' '):a.label).join(' ').toLocaleLowerCase()}))}
function sourceMatches(){const q=sourceSearch.trim().toLocaleLowerCase();return bibliography().filter(x=>(sourceTopic==='all'||x.groups.includes(sourceTopic))&&(!q||x.search.includes(q)||x.url.toLocaleLowerCase().includes(q)))}
function sourceResults(){const F=R.sourceFinder,all=bibliography(),items=sourceMatches(),shown=items.slice(0,sourceLimit);return `<p class="source-result-count" id="source-result-count" role="status" tabindex="-1">${t('מוצגים','Showing')} <bdi>${shown.length}</bdi> ${t('מתוך','of')} <bdi>${items.length}</bdi> ${t('מקורות מתאימים','matching sources')} · <bdi>${all.length}</bdi> ${t('במאגר המלא','in the full catalogue')}</p>${items.length?`<ul class="source-list evidence-results">${shown.map((x,i)=>`<li id="source-${esc(x.aliases[0].id)}" data-source-index="${i}"><div class="source-result-topics">${x.groups.map(id=>h(R.sourceGroups.find(g=>g.id===id).label)).join(' · ')}</div>${external(x.url,tr(x.label))}<small dir="ltr">${esc(x.url.replace(/^https?:\/\//,'').split('/')[0])}</small></li>`).join('')}</ul><div class="source-pagination">${shown.length<items.length?`<button class="btn" data-source-expand="more" aria-controls="source-results">${t('עוד','Show')} ${Math.min(sourcePageSize,items.length-shown.length)} ${t('מקורות','more sources')} ↓</button><button class="text-button" data-source-expand="all" aria-controls="source-results">${t('להציג את כל התוצאות','Show all matches')} (${items.length})</button>`:`<p>${t('הגעתם לסוף הרשימה הנוכחית. אפשר לבחור נושא אחר או לחפש בכל המקורות.','You’ve reached the end of this list. Choose another topic or search the catalogue.')}</p>`}${shown.length>sourcePageSize?`<button class="text-button" data-source-expand="less" aria-controls="source-results">${t('לחזור לרשימה קצרה','Return to the short list')} ↑</button>`:''}</div>`:`<div class="source-empty"><h3>${h(F.emptyTitle)}</h3><p>${h(F.emptyBody)}</p><button class="btn secondary" data-action="source-clear">${h(F.clear)}</button></div>`}`}
function expandSources(mode){const previous=Math.min(sourceLimit,sourceMatches().length);sourceLimit=mode==='less'?sourcePageSize:mode==='all'?sourceMatches().length:sourceLimit+sourcePageSize;document.getElementById('source-results').innerHTML=sourceResults();const target=mode==='less'?document.getElementById('source-result-count'):document.querySelector('[data-source-index="'+previous+'"] a');target?.focus({preventScroll:true});target?.scrollIntoView({block:'nearest',behavior:'instant'});}
function sourceFinder(){const F=R.sourceFinder,all=bibliography();return `<section class="source-finder" aria-label="${h(F.searchLabel)}"><p class="source-finder-note">${h(F.note)}</p><p class="source-reading-help">${t('המאגר כולו נשאר כאן. בחרו נושא או חפשו בשם, ביוצר או באתר; הרשימה נפתחת בכל פעם לעוד 24 מקורות.','The complete catalogue is here. Choose a topic or search by title, creator or website; reveal another 24 sources at a time.')}</p><label class="source-search-label" for="source-search">${h(F.searchLabel)}</label><input id="source-search" type="search" data-source-search aria-controls="source-results" placeholder="${h(F.searchPlaceholder)}" value="${esc(sourceSearch)}" autocomplete="off"><div class="source-topic-filters" role="group" aria-label="${h(F.filterLabel)}">${[{id:'all',label:F.allTopics},...R.sourceGroups].map(g=>`<button data-source-topic="${g.id}" aria-controls="source-results" aria-pressed="${sourceTopic===g.id}" class="${sourceTopic===g.id?'active':''}">${h(g.label)} <span>${g.id==='all'?all.length:all.filter(x=>x.groups.includes(g.id)).length}</span></button>`).join('')}</div><button class="text-button source-clear" data-action="source-clear">${h(F.clear)}</button><div id="source-results">${sourceResults()}</div><noscript><div class="source-static-fallback"><h3>${t("כל המקורות, ללא JavaScript","All sources, without JavaScript")}</h3><p>${t("החיפוש והסינון דורשים JavaScript. כאן זמינה גם הרשימה המלאה.","Search and filters require JavaScript. The full list is also available here.")}</p><ul>${all.map(x=>`<li>${external(x.url,tr(x.label))}</li>`).join('')}</ul></div></noscript></section>`}
function aboutPage(){return top(t('גם לרגש<br>מגיעות הערות שוליים.','Even feelings<br>deserve footnotes.'),t('היוצרים, ההקשר, המספרים והמקורות שמחזיקים את המדריך. כשהטקסט מציע פרשנות, הוא מסומן כשאלה או נקודת מבט.','The creators, context, figures and sources behind this guide. Interpretive writing is framed as a question or a point of view.'),t('07 / מאחורי המדריך','07 / BEHIND THE GUIDE'))+`<div class="wrap about-page"><nav class="about-reading-nav" aria-label="${t('ניווט בין חלקי עמוד האודות','Navigate the About page')}">${[['about-guide',t('איך נבנה המדריך','How the guide is made'),t('עובדות, פרשנות והקשר','Facts, interpretation and context')],['about-history',t('מרומן לבמה','From novel to stage'),t('ציר הזמן של המחזמר','The musical’s timeline')],['about-numbers',t('קצת פרופורציות','A little perspective'),t('הנתונים והמקורות שמאחוריהם','Figures and the sources behind them')],['privacy',t('פרטיות וזכויות','Privacy and rights'),t('מה נשמר ומה נשאר לבחירתכם','What stays here and what you choose')],['about-sources',t('מדף המקורות','The source catalogue'),bibliography().length+' '+t('מקורות, בחיפוש ובחלוקה לנושאים','sources to search and browse by topic')]].map(([id,title,note],i)=>`<button data-jump="${id}"><span aria-hidden="true">0${i+1}</span><b>${title}</b><small>${note}</small></button>`).join('')}</nav><section class="about-section" id="about-guide" tabindex="-1"><div class="about-section-mark" aria-hidden="true">01 /</div><h2>${t("איך נבנה המדריך","How the guide is made")}</h2><p class="curator-credit">${t('יצירה ועריכה: דן־אייל גזית.','Created and edited by Dan-Eyal Gazit.')} <a href="${url('contact')}">${t('תגובות, תיקונים ורעיונות','Comments, corrections and ideas')}${arrow}</a></p><div class="about-context-grid"><div class="credit-box"><h3>${t('1832, לא 1789','1832, not 1789')}</h3><p>${t('המרד שמופיע בעלילה הוא מרד יוני 1832 בפריז. הוגו משלב את האירוע בעולם הרומן; המחזמר מעבד את העולם הזה לבמה. בריקדה אינה הופכת כל אירוע לאותה מהפכה.','The uprising in the story is Paris’s June 1832 rebellion. Hugo incorporates that event into the novel’s world; the musical adapts that world for the stage. A barricade does not make every event the same revolution.')}</p>${sources(['mti-synopsis','novel'])}</div><div class="credit-box"><h3>${t('איך קוראים את המדריך','How to read this guide')}</h3><p>${t('עובדות עלילה נבדקו מול מקורות המופע והרומן. פרטי מסך מול מפיקים, מפיצים וקטלוגים. שאלות ההקשבה, ההשוואה והמשמעות הן הצעות מקוריות שלנו, ולא ציטוטים של היוצרים.','Plot facts were checked against musical and novel sources; screen details against producers, distributors and catalogs. Listening questions, comparisons and thematic lenses are our original prompts, not quotations from the creators.')}</p></div><div class="credit-box"><h3>${t('הצהרה קטנה, חשובה','A small, important note')}</h3><p>${t('זהו אתר מעריצים עצמאי ולא רשמי. אין קשר מסחרי, חסות או אישור של בעלי הזכויות. האיור הראשי הוא יצירה גרפית מקורית בהשראת במה ופריז, לא פוסטר רשמי ולא צילום היסטורי.','This is an independent, unofficial fan site. It has no commercial affiliation, sponsorship or endorsement from rights holders. The main illustration is original stage-and-Paris-inspired artwork, not an official poster or historical photograph.')}</p></div></div></section><section class="about-section" id="about-history" tabindex="-1"><div class="about-section-mark" aria-hidden="true">02 /</div><h2 >${t('מרומן לבמה','From novel to stage')}</h2><p>${h(R.musicalHistory?.intro)}</p>${sources(R.musicalHistory?.sourceIds)}<div class="about-timeline">${(R.musicalHistory?.milestones||[]).map(m=>`<div class="about-timeline-item"><strong>${esc(m.year)}</strong><div><b>${h(m.title)}</b><p>${h(m.text)}</p>${sources(m.sourceIds)}</div></div>`).join('')}</div></section><section class="about-section about-numbers" id="about-numbers" tabindex="-1"><div class="about-section-mark" aria-hidden="true">03 /</div>${statsSection()}${provenanceNote()}</section><section class="about-section" id="privacy" tabindex="-1"><div class="about-section-mark" aria-hidden="true">04 /</div><h2>${t('פרטיות, גישה וזכויות','Privacy, access & rights')}</h2><div class="about-choice-grid"><div class="credit-box"><h3>${t('מה נשמר כאן?','What stays here?')}</h3><p>${t('השפה, סימוני ההקשבה והמקצה האחרון יכולים להישמר בדפדפן רק לאחר בחירה בזכירת העדפות. בלעדיה הכלים פועלים בזיכרון הביקור. הסכמה לספוילרים נשמרת בלשונית. מדידה היא בחירה נפרדת; פרטים על שירותי המדיה ועדכון הבחירות בעמוד הפרטיות.','Language, listening checkmarks and your latest quiz round can be remembered in this browser only after you choose that option. Otherwise the tools use this visit’s memory. Spoiler consent lasts for the tab. Measurement is a separate choice; see the Privacy page for media-service details and controls.')}</p><button class="btn secondary small" data-action="privacy-open" style="margin-top:18px">${t('ניהול הפרטיות והשמירה','Manage privacy and storage')}</button></div><div class="credit-box"><h3>${t('YouTube, ישירות בעמוד','YouTube, directly on the page')}</h3><p>${t('נגני YouTube מוצגים ישירות לצד הביצוע שנבחר, ללא מסך אישור נוסף וללא הפעלה אוטומטית. טעינת הנגן יוצרת חיבור ל־YouTube. אנו משתמשים במצב פרטיות משופרת; הוא אינו מבטיח אפס איסוף מידע.','YouTube players appear directly with the selected performance, without an extra permission screen or autoplay. Loading a player connects to YouTube. We use privacy-enhanced mode; it does not promise zero data collection.')}</p>${sources(['youtube-embed-help','youtube-terms'])}</div><div class="credit-box"><h3>${t('כבוד למקור','Respect for the source')}</h3><p>${t('אין כאן מילות שירים מלאות, תרגומי שירים, תווים או הקלטות אודיו או וידאו להורדה. הסרטונים נשארים אצל המפרסמים שלהם. זכויות ברומן המקורי, תרגומים, עיבודים, צילומים והקלטות הן עניינים נפרדים.','There are no full lyrics, lyric translations, scores or audio or video recordings to download here. Videos remain with their publishers. Rights in the original novel, translations, adaptations, images and recordings are separate matters.')}</p></div><div class="credit-box"><h3>${t('נגישות ובחירה','Access & choice')}</h3><p>${t('ניווט מקלדת, כיוון קריאה מלא בכל שפה, תמיכה בהפחתת תנועה וספוילרים לפי בחירה. כתוביות וזמינות של הסרטונים תלויות במפרסם וב־YouTube. קישורים חיצוניים נפתחים בלשונית חדשה.','Keyboard navigation, full reading direction in each language, reduced-motion support and opt-in spoilers. Video captions and availability depend on the publisher and YouTube. External links open in a new tab.')}</p></div></div><div class="about-policy-links">${link("privacy",t("מדיניות הפרטיות המלאה","Full privacy policy"),"btn secondary")}${link("terms",t("תנאי השימוש","Terms of use"),"btn secondary")}</div></section><section class="about-section" id="about-sources" tabindex="-1"><div class="about-section-mark" aria-hidden="true">05 /</div><div class="section-head"><div><div class="eyebrow">${t('לבדוק, להעמיק, לחזור','VERIFY, EXPLORE, RETURN')}</div><h2>${t('המדף שמאחורי המדריך','The shelf behind the guide')}</h2></div><p>${t('מאגר המקורות עודכן ב־11 באוקטובר 2026. מקורות חיצוניים עשויים לכלול ספוילרים.','Source catalogue updated 11 October 2026. External sources may contain spoilers.')}</p></div>${sourceFinder()}</section></div>`}
function resourceGroup(s){if(s.typeEn==='Official production')return 'official';if(s.id.startsWith('gutenberg'))return 'read';if(s.id.startsWith('reddit'))return 'community';if(s.typeEn.toLowerCase().includes('community'))return 'community';return 'history'}
function resourceRecords(){return (R.resources||[]).filter(s=>resourceFilter==='all'||resourceGroup(s)===resourceFilter)}
function resourceIcon(s){const group=resourceGroup(s);const paths={official:'M8 12h48v34H8zM14 12v-5h36v5M22 46v10m20-10v10M8 28h48M30 12v34',read:'M32 16c-8-8-17-9-25-8v42c9-1 17 1 25 8 8-7 16-9 25-8V8c-8-1-17 0-25 8zM32 16v42',history:'M6 24L32 7l26 17H6zM10 54h44M16 27v22m16-22v22m16-22v22M6 59h52',community:'M22 23a8 8 0 1 0 0-.1M48 24a7 7 0 1 0 0-.1M5 55c0-14 34-14 34 0M40 42c10-1 18 5 18 13'};return `<svg viewBox="0 0 64 64" aria-hidden="true"><path d="${paths[group]}" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>`}
function resourceCards(){return resourceRecords().map((s,i)=>`<article class="resource-card resource-${resourceGroup(s)}"><div class="resource-visual">${resourceIcon(s)}<span class="mono">${String((R.resources||[]).indexOf(s)+1).padStart(2,'0')} / OPEN A DOOR</span></div><div class="resource-copy"><div class="resource-type">${esc(t(s.typeHe,s.typeEn))}</div><h2>${esc(t(s.titleHe,s.titleEn))}</h2><p>${esc(t(s.hookHe,s.hookEn))}</p><div class="resource-start"><b>${t('מאיפה מתחילים?','WHERE TO START')}</b><span>${esc(t(s.startHe,s.startEn))}</span></div><div class="resource-language">${t('שפה: ','LANGUAGE: ')}${esc(t(s.languageHe,s.languageEn))}</div><div class="resource-end">${external(s.url,t('פותחים את הדלת','Open this door'))}<svg class="external-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 12 12 4M4 4h8v8" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div></div></article>`).join('')}
function relatedWorksSection(){const d=R.relatedWorks;if(!d)return '';const languageNames={en:t('אנגלית','English'),fr:t('צרפתית','French'),ja:t('יפנית','Japanese')};return `<section id="related-works" class="section divider related-works" aria-labelledby="related-works-heading"><div class="section-head"><div><div class="eyebrow">${t('אותו שורש, צורה חדשה','THE SAME ROOTS, A NEW FORM')}</div><h2 id="related-works-heading">${h(d.title)}</h2></div><p>${h(d.intro)}</p></div><p class="note related-note">${t('אלה אתרי היוצרים והמפיקים של היצירות המקושרות. מופע המחווה Beyond the Barricade הוא מופע עצמאי הכולל כמה מחזות זמר; המדריך הזה אינו קשור אליו. הדפים החיצוניים עשויים לכלול ספוילרים.','These are the linked works’ own creator and producer sites. The independent Beyond the Barricade concert covers several musicals; this guide is not affiliated with it. External pages may contain spoilers.')}</p><div class="resource-grid">${d.items.map((s,i)=>`<article class="resource-card related-work-card resource-${s.relationship==='TRIBUTE'?'community':'read'}"><div class="resource-visual">${resourceIcon({id:s.id==='manga-classics'?'gutenberg-related':s.id,typeEn:s.id==='manga-classics'?'Library':'Official production'})}<span class="mono">${String(i+1).padStart(2,'0')} / NEW FORMS</span></div><div class="resource-copy"><div class="resource-type">${h(s.relationshipLabel)} · ${h(s.medium)}</div><h3>${h(s.title)}</h3><p>${h(s.hook)}</p><div class="resource-start"><b>${t('מה הקשר?','THE CONNECTION')}</b><span>${h(s.relationshipNote)}</span></div><div class="resource-language">${t('שפת האתר: ','SITE LANGUAGE: ')}${s.sourceLanguages.map(x=>esc(languageNames[x]||x)).join(' / ')}</div><div class="resource-end">${external(s.url,tr(s.linkLabel))}<svg class="external-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 12 12 4M4 4h8v8" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div><details class="related-source-details"><summary>${t('מקורות רשמיים','Official sources')}</summary><ul>${s.sources.map((u,j)=>`<li>${external(u,t('מקור רשמי ','Official source ')+(j+1))}</li>`).join('')}</ul></details></div></article>`).join('')}</div><p class="small muted related-checked">${t('המשך הדרך: בדפי ההפקות והיוצרים המקושרים.','Keep exploring on the linked production and creator sites.')}</p></section>`}
function resourcesPage(){return top(t('הגעתם עד כאן.<br>יש עוד דלתות.','You made it this far.<br>There are more doors.'),t('עשר כניסות לעולם הסיפור, ועוד ארבע יצירות שמוצאות לו צורה חדשה. הפקות, ספריות, היסטוריה ואנשים שאוהבים לדבר על כל זה.','Ten ways into the story’s world, plus four works that find it a new form. Productions, libraries, history and people who love talking about it all.'),t('08 / עוד דלתות','08 / OPEN ANOTHER DOOR'))+`<div class="wrap section"><div class="directory-intro"><span class="directory-mark" aria-hidden="true">↗</span><div><h3>${t('האינטרנט גדול. הנה כמה כניסות טובות.','The internet is big. Here are some good entrances.')}</h3><p>${t('כל כרטיס אומר מה תמצאו ואיפה להתחיל, מאתרי ההפקות ועד קהילות הקוראים והצופים.','Each card shows you what you’ll find and where to start, from production websites to reading and theatre communities.')}</p><button class="btn secondary" style="margin-top:18px" data-jump="related-works">${t('למופע המחווה ולעיבודים המפתיעים','Jump to the concert tribute & new forms')}</button></div></div><div class="filter-row" role="group" aria-label="${t('סינון קישורים','Filter destinations')}">${[['all',t('כל הדלתות','All doors')],['official',t('ההפקות','Productions')],['read',t('לקרוא','Read')],['history',t('לחקור','Explore history')],['community',t('לפגוש מעריצים','Meet other fans')]].map(([id,l])=>`<button class="filter ${resourceFilter===id?'active':''}" data-resource-filter="${id}" aria-pressed="${resourceFilter===id}">${l}</button>`).join('')}</div><p id="resource-count" class="small muted" aria-live="polite" style="margin-bottom:20px">${resourceRecords().length} ${t('דלתות פתוחות','doors to explore')}</p><div id="resource-grid" class="resource-grid">${resourceCards()}</div><div class="note" style="margin-top:30px">${t('קישורים נפתחים בלשונית חדשה ועשויים לכלול ספוילרים. בקהילות התוכן נכתב בידי משתמשים, ועשויים להידרש חשבון או כללי השתתפות. Project Gutenberg מציין מעמד של נחלת הכלל בארה״ב; במקום אחר יש לבדוק את הדין המקומי. תרגומים מודרניים הם יצירות נפרדות.','Links open in a new tab and may contain spoilers. Community content is user-generated; accounts or participation rules may apply. Project Gutenberg states US public-domain status; elsewhere, check local law. Modern translations have separate rights.')}</div>${relatedWorksSection()}</div>`}

const graphPositions={bishop:[110,155],valjean:[255,340],javert:[315,140],fantine:[115,520],cosette:[430,520],marius:[480,200],eponine:[670,355],thenardiers:[705,535],enjolras:[865,140],gavroche:[880,460]};
const edgeKinds={care:{he:'דאגה ועזרה',en:'Care & help'},family:{he:'משפחה',en:'Family'},love:{he:'אהבה',en:'Love'},conflict:{he:'עימות וניצול',en:'Conflict & exploitation'},solidarity:{he:'מאבק משותף',en:'Shared struggle'}};
const edgeKindPairs={care:['bishop-valjean','fantine-valjean','marius-valjean','cosette-eponine'],family:['cosette-fantine','cosette-valjean','eponine-thenardiers','gavroche-thenardiers','eponine-gavroche'],love:['cosette-marius','eponine-marius'],conflict:['javert-valjean','fantine-javert','gavroche-javert','cosette-thenardiers','fantine-thenardiers'],solidarity:['enjolras-marius','enjolras-gavroche','enjolras-valjean']};
function edgeKind(a,b){const key=[a,b].sort().join('-');return Object.keys(edgeKindPairs).find(k=>edgeKindPairs[k].includes(key))||'care'}
function graphSet(){return relationshipFilter==='care'?['bishop','valjean','javert','fantine','cosette','thenardiers']:relationshipFilter==='love'?['marius','cosette','eponine']:relationshipFilter==='barricade'?['marius','enjolras','gavroche']:R.characters.map(c=>c.id)}
let relationshipEdge=null;
const relationshipPair=(a,b)=>[a,b].sort().join('-');
function relationshipRecords(){
 if(spoiler)return R.characters.flatMap(c=>c.connections.map(e=>({owner:c.id,target:e.id,label:e.label})));
 const safe=(R.relationships||[]).filter(e=>e.spoilerLevel===0&&e.safeLabel&&e.safeContext);
 return safe.length?safe.map(e=>({owner:e.from,target:e.to,label:e.safeLabel})):R.introConnections.map(e=>({owner:e.from,target:e.to,label:e.label}));
}
function relationshipKind(a,b){const edge=relationshipEnrichment(a,b);return !spoiler&&edge?.safeKind?edge.safeKind:edgeKind(a,b)}
function relationshipEnrichment(a,b){return (R.relationships||[]).find(e=>relationshipPair(e.from,e.to)===relationshipPair(a,b))}
function relationshipHref(language=lang){const q=new URLSearchParams({person:character,view:relationshipFilter});if(relationshipEdge)q.set('edge',relationshipEdge);return `/${language}/characters/?${q.toString()}#relationship-map`}
function readRelationshipLocation(){
 const q=new URLSearchParams(location.search||'');if(!q.has('person'))return;
 character=R.characters.some(c=>c.id===q.get('person'))?q.get('person'):'valjean';
 relationshipFilter=['all','care','love','barricade'].includes(q.get('view'))?q.get('view'):'all';
 if(!graphSet().includes(character))relationshipFilter='all';
 const edge=q.get('edge');relationshipEdge=relationshipRecords().some(e=>relationshipPair(e.owner,e.target)===edge)?edge:null;
}
function rememberRelationshipLocation(){if(route!=='characters')return;history.pushState(history.state,'',relationshipHref());renderedPath=(location.pathname||'')+(location.search||'');renderedJourney=history.state?.lesmisJourney||null}
function focusRelationshipMap(){const map=document.getElementById('relationship-map');map?.focus?.({preventScroll:true});map?.scrollIntoView?.({block:'start',behavior:'auto'})}
function updateRelationshipView(){
 const graph=document.getElementById('relationship-graph');if(graph)graph.innerHTML=relationshipGraph();
 const panel=document.getElementById('character-panel');if(panel&&spoiler)panel.innerHTML=characterPanel();
 document.querySelectorAll('.char-button').forEach(x=>{x.classList.toggle('active',x.dataset.character===character);x.setAttribute('aria-pressed',x.dataset.character===character)});
 document.querySelectorAll('[data-relationship-filter]').forEach(x=>{const on=x.dataset.relationshipFilter===relationshipFilter;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on)});
 const select=document.getElementById('relationship-person');if(select)select.value=character;const person=R.characters.find(c=>c.id===character);const count=new Set(incidentConnections(character).map(e=>e.owner===character?e.target:e.owner)).size;const status=document.getElementById('relationship-status');if(status)status.textContent=tr(person.name)+' · '+count+' '+t('קשרים במבט הזה','connections in this view');
}
function selectRelationshipPerson(id,focusNode=false){
 if(!R.characters.some(c=>c.id===id))return;character=id;relationshipEdge=null;
 if(!graphSet().includes(id))relationshipFilter='all';updateRelationshipView();rememberRelationshipLocation();
 A.track('content_open',{content_type:'character',content_id:id});
 if(focusNode){const node=Array.from(document.querySelectorAll('.graph-node.selected')).find(n=>n.offsetParent!==null);node?.focus?.({preventScroll:true})}
}
function selectRelationshipEdge(pair){
 const edge=relationshipRecords().find(e=>relationshipPair(e.owner,e.target)===pair);if(!edge)return;
 if(![edge.owner,edge.target].includes(character))character=edge.owner;
 if(![edge.owner,edge.target].every(id=>graphSet().includes(id)))relationshipFilter='all';
 relationshipEdge=pair;updateRelationshipView();rememberRelationshipLocation();
 const detail=document.getElementById('relationship-'+pair);detail?.focus?.({preventScroll:true});detail?.scrollIntoView?.({block:'center',behavior:'auto'});
}
function incidentConnections(id,allowed=new Set(graphSet())){return relationshipRecords().filter(e=>(e.owner===id||e.target===id)&&allowed.has(e.owner)&&allowed.has(e.target))}
function relationshipContext(c,current,records){
 const pair=relationshipPair(c.id,current.id),edge=relationshipEnrichment(c.id,current.id),text=edge&&(spoiler?edge.context:edge.safeContext),label=edge&&(spoiler?edge.label:edge.safeLabel);
 return `<article id="relationship-${pair}" tabindex="-1" data-connection-person="${esc(c.id)}" class="connection-type-${relationshipKind(current.id,c.id)} ${relationshipEdge===pair?'relationship-selected':''}"><span class="relation-type">${h(edgeKinds[relationshipKind(current.id,c.id)])}</span><h4>${h(current.name)} <span aria-hidden="true">·</span> ${h(c.name)}</h4>${label?`<b class="relationship-label">${h(label)}</b>`:''}${text?`<p>${h(text)}</p>`:''}${spoiler?records.filter(x=>x.owner===c.id||x.target===c.id).map(x=>`<p class="relationship-direction"><b>${h(R.characters.find(y=>y.id===x.owner).name)}:</b> ${h(x.label)}</p>`).join(''):!text?records.filter(x=>x.owner===c.id||x.target===c.id).map(x=>`<p>${h(x.label)}</p>`).join(''):''}${spoiler&&edge?.canonNote?`<p class="relationship-canon">${h(edge.canonNote)}</p>`:''}<div class="relationship-actions"><button data-relationship-edge="${pair}" aria-pressed="${relationshipEdge===pair}">${t('להדגיש את הקו','Highlight this connection')}</button><button data-character="${esc(c.id)}">${t('לעקוב אחרי ','Follow ')}${h(c.name)}${arrow}</button></div>${edge?`<details class="relationship-sources"><summary>${t('מקורות · כוללים פרטי עלילה','Sources · contain plot details')}</summary>${((spoiler?edge.references:edge.safeReferences)||[]).map(r=>external(r.url,tr(r.label))).join('')}${sources(edge.sourceIds||[])}</details>`:''}</article>`;
}
function relationshipIcon(id){const paths={valjean:'M9 7H7a5 5 0 0 0 0 10h3m4-10h3a5 5 0 0 1 0 10h-2M8 12h8m-4-5v10',javert:'M12 3v17M5 20h14M4 7h16M6 7l-4 7h8L6 7m12 0-4 7h8l-4-7',bishop:'M7 21h10M9 20V9h6v11M12 2c4 4 3 6 0 6s-4-2 0-6',fantine:'M12 21V11m0 6-5-4m5 3 5-3M12 11C4 13 3 6 8 6c-1-5 7-5 7 0 5-2 7 5-3 5',cosette:'M5 20c9 0 15-6 15-16C8 4 3 10 5 20Zm0 0L16 9',marius:'M12 6v15M12 6C8 3 4 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-4-1-7 0-10 2',eponine:'M4 12h16M12 4v16M6 6l12 12M6 18 18 6M9 9h6v6H9Z',thenardiers:'M4 9V5h16v4M3 10h18v11H3ZM8 10V7m8 3V7M8 15h8M12 13v6',enjolras:'M5 22V3m0 1c5-5 9 5 15 0v10c-6 5-10-5-15 0',gavroche:'M3 16h18M6 15c0-7 3-11 10-10v7l4 3M7 20h10'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]||paths.valjean}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function relationshipGraph(){
 const current=R.characters.find(c=>c.id===character)||R.characters[0],allowed=new Set(graphSet()),records=incidentConnections(current.id,allowed),neighbors=[...new Set(records.map(x=>x.owner===current.id?x.target:x.owner))],edges=[],seen=new Set();
 relationshipRecords().forEach(x=>{const key=relationshipPair(x.owner,x.target);if(!seen.has(key)&&allowed.has(x.owner)&&allowed.has(x.target)){seen.add(key);edges.push([x.owner,x.target])}});
 const line=(a,b,coordinates)=>{const [[x1,y1],[x2,y2]]=coordinates,pair=relationshipPair(a,b),selected=a===current.id||b===current.id,k=relationshipKind(a,b);return `<path d="M${x1} ${y1} Q${(x1+x2)/2+18} ${(y1+y2)/2-22} ${x2} ${y2}" data-edge="${pair}" data-relationship-edge="${pair}" class="relation-line edge-${k} ${selected?'selected-edge':'muted-edge'} ${relationshipEdge===pair?'focused-edge':''}"/>`};
 const node=(c,x,y)=>`<a href="${spoiler?`/${lang}/characters/?person=${esc(c.id)}&view=all#relationship-map`:`#character-intro-${esc(c.id)}`}" class="graph-node ${c.id===current.id?'selected':neighbors.includes(c.id)?'connected':'distant'} ${allowed.has(c.id)?'':'dim'}" data-character="${esc(c.id)}" aria-current="${c.id===current.id?'true':'false'}" style="left:${x}%;top:${y}%"><span class="graph-dot" aria-hidden="true">${relationshipIcon(c.id)}</span><strong>${h(c.name)}</strong></a>`;
 const friends=neighbors.map(id=>R.characters.find(c=>c.id===id)),fpos=friends.map((c,i)=>{const angle=(-90+i*360/friends.length)*Math.PI/180;return [c,50+31*Math.cos(angle),50+28*Math.sin(angle)]});
 return `<div class="graph-focus-heading"><div><span>${t('עכשיו עוקבים אחרי','NOW FOLLOWING')}</span><h3>${h(current.name)}</h3></div><p><b>${neighbors.length}</b> ${t('קשרים במבט הזה','connections in this view')}</p></div><div class="graph-full"><div class="graph-zone zone-mercy"><span>${t('חוק וחסד','LAW & MERCY')}</span></div><div class="graph-zone zone-bonds"><span>${t('קשרים פרטיים','PRIVATE BONDS')}</span></div><div class="graph-zone zone-public"><span>${t('המאבק הציבורי','PUBLIC STRUGGLE')}</span></div><svg viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true">${edges.map(([a,b])=>line(a,b,[graphPositions[a],graphPositions[b]])).join('')}</svg>${R.characters.map(c=>node(c,graphPositions[c.id][0]/10,graphPositions[c.id][1]/6.5)).join('')}</div><div class="graph-focused ${neighbors.length>3?'many-connections':''}"><div class="graph-orbit" aria-hidden="true"></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${fpos.map(([c,x,y])=>`<line x1="50" y1="50" x2="${x}" y2="${y}" data-relationship-edge="${relationshipPair(current.id,c.id)}" class="relation-line edge-${relationshipKind(current.id,c.id)} selected-edge ${relationshipEdge===relationshipPair(current.id,c.id)?'focused-edge':''}"/>`).join('')}</svg>${node(current,50,50)}${fpos.map(([c,x,y])=>node(c,x,y)).join('')}</div><div class="graph-legend" aria-label="${t('מקרא סוגי קשרים','Relationship types legend')}">${Object.entries(edgeKinds).map(([k,l])=>`<span><svg viewBox="0 0 42 8" aria-hidden="true"><line x1="1" y1="4" x2="41" y2="4" class="edge-${k}"/></svg>${h(l)}</span>`).join('')}</div>${relationshipFilters()}<div class="graph-person-context"><p>${h(current.safeIntro)}</p><a href="#${spoiler?'character-detail':'character-intro-'+current.id}" class="text-link">${t('לדמות מקרוב','Read about this character')}${arrow}</a></div><section class="graph-connections" aria-labelledby="graph-connections-title"><h3 id="graph-connections-title">${t('מה מחבר ביניהם?','What connects them?')}</h3><div class="graph-connection-list">${friends.map(c=>relationshipContext(c,current,records)).join('')}</div>${!friends.length?`<p>${spoiler?t('במסנן הזה אין קו אל הדמות שבחרתם. נסו את המפה המלאה.','This filter has no connection to the selected person. Try the whole map.'):t('הקשרים של הדמות נפתחים בהמשך העלילה. אפשר להכיר אותה כאן, ולהוסיף את הקשרים כשמוכנים לספוילרים.','This person’s connections unfold later in the story. Read their introduction here, and add the connections when you are ready for plot details.')}</p>`:''}</section>`;
}
function relationshipFilters(){return `<div class="filter-row" role="group" aria-label="${t('סינון מפת הקשרים','Filter the relationship map')}">${[['all',t('כל המפה','The whole map')],['care',t('סביב ולז׳אן','Around Valjean')],['love',t('מריוס, קוזט ואפונין','Marius, Cosette & Éponine')],['barricade',t('סביב המתרס','Around the barricade')]].map(([id,l])=>`<button class="filter ${relationshipFilter===id?'active':''}" data-relationship-filter="${id}" aria-pressed="${relationshipFilter===id}">${l}</button>`).join('')}</div>`}
function relationshipExplorer(){return `<section id="relationship-map" class="relationship-explorer" tabindex="-1" aria-labelledby="relationship-map-title"><div class="relationship-intro"><h2 class="sr-only" id="relationship-map-title">${t('מי משנה את חייו של מי?','Who changes whose life?')}</h2></div><div class="relationship-tools"><label for="relationship-person">${t('בחרו דמות','Choose a character')}<select id="relationship-person">${R.characters.map(c=>`<option value="${c.id}" ${c.id===character?'selected':''}>${h(c.name)}</option>`).join('')}</select></label><div class="relationship-mode"><span>${spoiler?t('כל קשרי העלילה פתוחים','Full-story connections are open'):t('קשרי הפתיחה · בלי לגלות את הסוף','Opening connections · the ending stays hidden')}</span><button class="btn ${spoiler?'secondary':''}" data-action="relationship-${spoiler?'hide':'reveal'}">${spoiler?t('להסתיר קשרי עלילה','Hide plot connections'):t('להוסיף קשרי עלילה · כולל הסיום','Add plot connections · includes the ending')}</button></div></div><div id="relationship-status" class="sr-only" role="status" aria-live="polite"></div><div id="relationship-graph" class="relationship-graph">${relationshipGraph()}</div></section>`}

let mapScope='france';
const atlasPositions={toulon:[66,80],digne:[77,61],montreuil:[36,20],montfermeil:[63,33],paris:[41,42],waterloo:[82,16],luxembourg:[60,74],plumet:[24,64],chanvrerie:[70,24]};
function atlasPlaces(){return (R.map?.places||[]).filter(p=>mapScope==='paris'?p.scope==='paris':p.scope!=='paris')}
function atlasArtwork(){return mapScope==='france'?`<defs><pattern id="atlas-water" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M0 12h9m7 0h8" stroke="#c7d8eb" stroke-width="1"/></pattern></defs><rect width="900" height="680" fill="url(#atlas-water)"/><path d="M295 100L400 85 458 150 550 158 602 229 694 241 727 345 695 432 721 504 654 555 573 558 534 601 438 580 373 563 282 525 236 448 246 359 171 311 100 272 111 220 194 233 238 193 280 198Z" class="atlas-land"/><path d="M294 104L392 163 343 230 458 285 392 390 502 434 554 553M247 360L390 390M458 285L602 229M502 434L695 432" class="atlas-terrain"/><path d="M699 275l17-21 18 21m-19 57 20-24 20 24m-38 53 24-25 18 25" class="atlas-mountains"/><path d="M274 183C325 217 402 247 462 271" class="atlas-small-river"/><text x="200" y="396" class="atlas-area-title">${t('צרפת','FRANCE')}</text><text x="58" y="137" class="atlas-water-label">${t('תעלת למאנש','ENGLISH CHANNEL')}</text><text x="306" y="636" class="atlas-neighbor-label">${t('ספרד','SPAIN')}</text><text x="792" y="329" text-anchor="middle" class="atlas-neighbor-label">${t('שווייץ','SWITZERLAND')}</text><text x="111" y="466" class="atlas-water-label">${t('האוקיינוס האטלנטי','ATLANTIC')}</text><text x="610" y="642" class="atlas-water-label">${t('הים התיכון','MEDITERRANEAN')}</text><rect x="647" y="35" width="214" height="132" rx="10" class="atlas-inset"/><text x="757" y="60" text-anchor="middle">${t('בלגיה · הרחבה היסטורית','BELGIUM · HISTORY INSET')}</text><path d="M567 581l35-1 12-11 6 18 16-4" class="atlas-harbour"/>`:`<defs><pattern id="atlas-blocks" width="85" height="65" patternUnits="userSpaceOnUse" patternTransform="rotate(-14)"><rect x="8" y="8" width="62" height="43" rx="5" fill="#e5ebf5" stroke="#d3dfef"/></pattern></defs><rect width="900" height="680" fill="#f7f9ff"/><ellipse cx="450" cy="337" rx="414" ry="287" fill="url(#atlas-blocks)" stroke="#bccfe4" stroke-width="2" stroke-dasharray="7 8"/><path d="M-20 346C150 492 280 304 432 333S666 379 923 195" class="atlas-seine-bank"/><path d="M-20 346C150 492 280 304 432 333S666 379 923 195" class="atlas-seine"/><path d="M330 305l16 66M513 323l-8 65M682 263l27 53" class="atlas-bridge"/><path d="M115 487L753 131M189 563L666 415M242 168L324 522" class="atlas-streets"/><rect x="442" y="427" width="180" height="147" rx="38" fill="#d9e9df" stroke="#b6d4c2"/><path d="M458 492h148m-73-47v111" stroke="#fff" stroke-width="7"/><g class="atlas-trees"><circle cx="475" cy="449" r="8"/><circle cx="588" cy="450" r="8"/><circle cx="476" cy="550" r="8"/><circle cx="590" cy="550" r="8"/></g><text x="450" y="80" text-anchor="middle" class="atlas-area-title">${t('פריז','PARIS')}</text><text x="355" y="220">${t('הגדה הימנית','RIGHT BANK')}</text><text x="320" y="605">${t('הגדה השמאלית','LEFT BANK')}</text><text x="680" y="362" class="atlas-water-label">${t('הסיין','SEINE')}</text><path d="M624 119v-47m1 0q26-12 50 0v27q-25-12-50 0" fill="#ed2939" stroke="#b52135" stroke-width="3"/>`}
function atlasDrawing(){
 const places=atlasPlaces();if(!places.some(p=>p.id===selectedPlace))selectedPlace=places[0]?.id;const thread=places.filter(p=>p.kind!=='historicalConnection'),segments=thread.slice(1).map((p,i)=>{const prev=thread[i],[x,y]=atlasPositions[prev.id],[xx,yy]=atlasPositions[p.id];return `<path d="M${x*9} ${y*6.8} Q${(x+xx)*4.5+24} ${(y+yy)*3.4-25} ${xx*9} ${yy*6.8}" class="atlas-reading-line ${p.id===selectedPlace||prev.id===selectedPlace?'active':''}"/>`}).join('');
 return `<div class="atlas-map-heading"><span>${mapScope==='paris'?t('02 / מקרוב','02 / CLOSE UP'):t('01 / המבט הרחב','01 / WIDE VIEW')}</span><b>${mapScope==='paris'?t('פריז של הסיפור','The story’s Paris'):t('מצרפת אל פריז','Across France, into Paris')}</b></div><div class="atlas-canvas atlas-${mapScope}"><svg viewBox="0 0 900 680" preserveAspectRatio="none" aria-hidden="true">${atlasArtwork()}${segments}<g transform="translate(50,40)" class="atlas-compass"><path d="M0 36V0L-6 14M0 0l6 14"/><text x="0" y="-8" text-anchor="middle">N</text></g></svg>${places.map((p,i)=>{const pos=atlasPositions[p.id]||[50,50];return `<button class="place-node ${selectedPlace===p.id?'active':''} place-${p.kind}" data-place="${esc(p.id)}" aria-label="${h(p.name)}" aria-pressed="${selectedPlace===p.id}" style="left:${pos[0]}%;top:${pos[1]}%"><span>${String(i+1).padStart(2,'0')}</span><strong>${h(p.name)}</strong></button>`}).join('')}<div class="map-stamp">${t('איור סכמטי<br>ללא קנה מידה','SCHEMATIC ART<br>NOT TO SCALE')}</div></div><div class="atlas-reading-key"><i aria-hidden="true"></i>${t('קו מקווקו = חוט קריאה בין המקומות, לא תוואי נסיעה.','Dashed line = a reading thread between places, not a travel route.')}</div>`}

function atlasDate(value){return h(value).replace(/\d+(?:[–-]\d+)+/g,range=>`<bdi dir="ltr">${range}</bdi>`)}
function placeDetail(){const places=atlasPlaces(),p=(R.map?.places||[]).find(p=>p.id===selectedPlace)||places[0];if(!p)return '';const index=places.indexOf(p),j=p.journey;const type=p.kind==='realPlace'?t('מקום אמיתי, עלילה בדיונית','REAL PLACE, FICTIONAL ACTION'):p.kind==='fictionalScene'?t('סצנה בדיונית במרחב היסטורי','FICTIONAL SCENE, HISTORICAL SETTING'):t('הקשר היסטורי','HISTORICAL CONNECTION');return `<article class="place-detail" aria-live="polite"><div class="place-position">${index+1} / ${places.length} · ${mapScope==='paris'?t('בתוך פריז','IN PARIS'):t('במבט האזורי','WIDER VIEW')}</div><div class="eyebrow">${type}</div><h2>${h(p.name)}</h2><div class="place-region">${h(p.region)}</div>${j?`<div class="place-era"><b>${p.id==='waterloo'?t('תאריך היסטורי','HISTORICAL DATE'):t('זמן הסיפור ברומן','NOVEL STORY TIME')}</b><span>${atlasDate(j.dateLabel)}</span></div>`:''}${({luxembourg:"luxembourg",plumet:"rue-plumet",chanvrerie:"chanvrerie",montfermeil:"montfermeil"})[p.id]?`<a class="text-link" href="/${lang}/places/?place=${({luxembourg:"luxembourg",plumet:"rue-plumet",chanvrerie:"chanvrerie",montfermeil:"montfermeil"})[p.id]}" data-place-essay="${({luxembourg:"luxembourg",plumet:"rue-plumet",chanvrerie:"chanvrerie",montfermeil:"montfermeil"})[p.id]}">${t("לקרוא את המסע המצולם במקום הזה","Read this place’s photo essay")} →</a>`:""}${mapCardContext(p.context,'place')}<p>${h(p.storyRole)}</p>${p.id==='paris'?`<button class="btn secondary" data-map-scope="paris">${t('להתקרב למקומות בתוך פריז','Zoom into the Paris locations')}</button>`:''}${j?spoiler?`<div class="place-plot"><h3>${t('מה קורה כאן בסיפור?','WHAT HAPPENS HERE IN THE STORY?')}</h3><p>${h(j.event)}</p><p class="place-memory">${h(j.remember)}</p>${j.characterIds.length?`<div class="place-people"><b>${t('לפגוש את הדמויות הקשורות','MEET THE CONNECTED CHARACTERS')}</b><div>${j.characterIds.map(id=>`<button data-map-character="${esc(id)}">${h(R.characters.find(c=>c.id===id)?.name)}${arrow}</button>`).join('')}</div></div>`:''}<button class="text-button" data-map-novel="${esc(j.partId)}">${t('לתחנות האלה ברומן','Find these events in the novel')}${arrow}</button><small>${t('התקציר המלא של הרומן דורש אישור ספוילרים נפרד.','The full novel recap asks for separate spoiler consent.')}</small><div class="source-links">${j.references.map(r=>external(r.url,tr(r.label))).join('')}</div></div>`:`<div class="place-plot-gate"><p>${t('רוצים גם את האירוע, הדמויות והקשר להמשך? הפרטים האלה כוללים ספוילרים.','Want the event, connected characters and what follows? Those details contain spoilers.')}</p><button class="text-button" data-action="enable-spoilers">${t('הצגת פרטי העלילה · כולל ספוילרים','Show story details · includes spoilers')}</button></div>`:''}${sources(p.sourceIds)}<div class="place-pagination"><button data-map-step="prev" ${index===0?'disabled':''}>${t('המקום הקודם','Previous place')}</button><button data-map-step="next" ${index===places.length-1?'disabled':''}>${t('המקום הבא','Next place')}</button></div><p class="place-order-note">${t('דפדוף במקומות המבט הנוכחי, לא מסלול נסיעה או רשימה של כל מסעות הדמויות.','Browse the places in this view, not a travel route or a list of every character journey.')}</p></article>`}

function storyAtlasPage(){return `<div class="atlas-legacy-divider"><div class="eyebrow">${t('עוד דרך להתמצא','ANOTHER WAY TO FIND YOUR BEARINGS')}</div><h2>${t('מפת הקריאה: מצרפת אל פריז','The reading atlas: across France into Paris')}</h2><p>${t('תשע תחנות הסיפור המקוריות, עם המבט האזורי, המבט הפריזאי והקשרים לדמויות. האיור הבא סכמטי; המפה הגאוגרפית נמצאת למעלה.','The original nine story stations, with regional and Paris views and character connections. The drawing below is schematic; the geographic map is above.')}</p></div><div class="atlas-intro"><h3>${t('מקומות אמיתיים, חיים שהוגו המציא.','Real places, lives imagined by Hugo.')}</h3><p>${t('רקע גאוגרפי סכמטי להתמצאות, לא מפת גבולות היסטורית. החופים, המדינות השכנות והסיין עוזרים לקבל כיוון; הסמנים והמרחקים משוערים. תיאורי המקומות מציגים את הנחת היסוד של העלילה.','A schematic geography backdrop for orientation, not a map of historical borders. Coastlines, neighboring countries and the Seine give you bearings; markers and distances are approximate. The places introduce the story’s premise.')}</p></div><div class="atlas-instructions"><b>${t("בחרו נקודה. פגשו את המקום.","Pick a point. Meet the place.")}</b><p>${t("לחצו על סמן או על שם ברשימה. הכרטיס מתעדכן עם זמן הסיפור והקשר למקום; פרטי העלילה והדמויות נפתחים רק באישור. אפשר לדפדף גם בכפתורי המקום הבא והקודם.","Click a marker or a name in the list. The card updates with the story’s time and setting; plot details and characters require consent. You can also use Previous and Next place.")}</p></div><div class="atlas-switch" role="group" aria-label="${t('בחירת אזור','Choose an area')}"><button data-map-scope="france" class="${mapScope==='france'?'active':''}" aria-pressed="${mapScope==='france'}">${t('צרפת וההקשר האזורי','France & the wider setting')}</button><button data-map-scope="paris" class="${mapScope==='paris'?'active':''}" aria-pressed="${mapScope==='paris'}">${t('מבט אל פריז','Closer to Paris')}</button></div><div class="atlas-key"><span><i></i>${t('נבחר','SELECTED')}</span><span><i class="key-real"></i>${t('מקום אמיתי','REAL PLACE')}</span><span><i class="key-fiction"></i>${t('זירה בדיונית','FICTIONAL SCENE')}</span><span><i class="key-history"></i>${t('הקשר היסטורי','HISTORY INSET')}</span></div><div class="atlas-layout"><div id="atlas-drawing">${atlasDrawing()}</div><div id="place-detail">${placeDetail()}</div></div><div class="place-tabs" id="place-tabs" role="group" aria-label="${t('מקומות במפה, כחלופה טקסטואלית','Map locations, text alternative')}">${placeTabs()}</div><div class="note" style="margin-top:28px">${t('רחוב לה שאנבררי היה רחוב אמיתי. הפונדק קורינת והמתרס המסוים של גיבורי הרומן הם חלק מן הבדיון. ווטרלו הוא הקשר היסטורי של הרומן, ולא תחנה באותו מרד בפריז.','Rue de la Chanvrerie was a real street. Corinthe and the protagonists’ particular barricade are fictional. Waterloo is part of the novel’s historical context, not a stop in the same Paris uprising.')}</div><div class="button-row">${link('history',t('ומה קרה במציאות?','What happened in real life?'))}${link('characters',t('ממפת מקומות למפת אנשים','From places to people'),'btn secondary')}</div>`}
function recipesPage(){return top(h(window.RECIPE_CONTENT?.title),h(window.RECIPE_CONTENT?.subtitle),t('22 / ארוחת ערב בפונדק','22 / DINNER AT THE INN'))+(window.InnKitchen?.page(lang)||'')}
function placesPage(){return top(t('המקומות שמחוץ לדף.','Places beyond the page.'),t('מסע מצולם בעקבות מקומות אמיתיים ששמם מופיע ברומן של ויקטור הוגו.','A photo journey through real places named in Victor Hugo’s novel.'),t('21 / המקומות שמחוץ לדף','21 / PLACES BEYOND THE PAGE'))+(window.PlaceAtlas?.page({lang,spoiler})||'')}
function mapPage(){return top(t('המפה נפתחת.<br>הסיפור מקבל כתובת.','Unfold the map.<br>Find the story’s places.'),t('מפה גאוגרפית עם תצלומים וקשרים לרומן, ולצדה אטלס הקריאה האזורי.','A geographic map with photographs and novel connections, alongside the regional reading atlas.'),t('09 / מפת המסע','09 / THE STORY ATLAS'))+`<div class="wrap section">${window.PlaceAtlas?.mapSection({lang,spoiler})||''}${storyAtlasPage()}</div>`}
function placeTabs(){return atlasPlaces().map((p,i)=>`<button data-place="${esc(p.id)}" class="${selectedPlace===p.id?'active':''}" aria-pressed="${selectedPlace===p.id}"><span class="place-tab-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span><b>${h(p.name)}</b><small>${atlasDate(p.journey?.dateLabel)}</small></span></button>`).join('')}
function historyTimeline(){return (R.history.timeline||[]).map(e=>e.spoilerLevel>=2&&!spoiler?`<article class="history-event locked-history"><span class="history-date">${esc(e.date)}</span><div class="history-event-copy"><span class="history-kind">${t('המשך ההיסטוריה · מוסתר לפי בחירתכם','LATER HISTORY · HIDDEN BY YOUR CHOICE')}</span><h2>${t('מה קרה בהמשך?','What happened later?')}</h2><p>${t('המשך ההיסטוריה עשוי לרמוז על תוצאות המרד שבסיפור.','Later history may hint at the outcome of the story’s uprising.')}</p><button class="text-button" data-action="enable-spoilers">${t('פתיחת המשך ההיסטוריה','Reveal the historical aftermath')}</button></div></article>`:`<article class="history-event ${e.id==='1832'?'history-highlight':''}" data-history-event="${esc(e.id)}"><span class="history-date">${esc(e.date)}</span><div class="history-event-copy"><span class="history-kind">${e.id==='1862'?t('פרסום היצירה · אירוע מתועד','PUBLICATION · DOCUMENTED EVENT'):t('רקע היסטורי · אירוע אמיתי','HISTORICAL CONTEXT · REAL EVENT')}</span><h2>${h(e.title)}</h2><p>${h(e.body)}</p>${e.importance?`<div class="history-connections"><div><h3>${t('למה זה חשוב?','WHY IT MATTERS')}</h3><p>${h(e.importance)}</p></div><div><h3>${t('איך זה פוגש את הסיפור?','HOW IT MEETS THE STORY')}</h3><p>${h(e.storyConnection)}</p></div></div>`:''}${e.context?`<details class="history-depth"><summary>${h(e.context.title)}</summary><p>${h(e.context.body)}</p><small>${t('ההקשר ההיסטורי מבוסס על המקורות; הקישור לדמויות הוא קריאה ביצירה הבדיונית.','Historical context follows the sources; connections to characters are readings of the fictional work.')}</small></details>`:''}${sources(e.sourceIds)}</div></article>`).join('')}
function historyPage(){const H=R.history||{};return top(t('לא כל דגל אדום<br>שייך לאותה מהפכה.','Not every red flag<br>belongs to the same revolution.'),h(H.intro),t('10 / ההיסטוריה האמיתית','10 / REAL HISTORY'))+`<div class="wrap section"><div class="history-anchor"><span>1789</span><i>≠</i><strong>1832</strong><div><h3>${t('המתרס שלנו: 5–6 ביוני 1832','Our barricade: 5–6 June 1832')}</h3><p>${t('שישה רגעים אמיתיים, והחיבורים שהוגו יוצר בינם לבין חיים בדיוניים. תאריכים אינם רשימת פרקים: ווטרלו, מהפכת יולי ומרד יוני הם אירועים שונים.','Six real moments and the connections Hugo makes with fictional lives. Dates are not chapter numbers: Waterloo, the July Revolution and the June uprising are different events.')}</p></div></div><div class="history-timeline">${historyTimeline()}</div><div class="section-head" style="margin-top:55px"><div><div class="eyebrow">${t('העולם שמסביב לרחוב','THE WORLD AROUND THE STREET')}</div><h2>${t('מה הביא אותם לשם?','What brought them there?')}</h2></div></div><div class="history-context">${(H.contextCards||[]).map((c,i)=>`<article><span class="context-number">0${i+1}</span><h3>${h(c.title)}</h3>${h(c.body).split('\n\n').map(p=>`<p>${p}</p>`).join('')}${sources(c.sourceIds)}</article>`).join('')}</div><section class="historical-outcome"><div class="eyebrow">${t('תוצאות · עם אזהרת ספוילרים','THE OUTCOME · SPOILER WARNING')}</div><h2>${h(H.outcome?.title)}</h2>${spoiler?`<p>${h(H.outcome?.body)}</p>${sources(H.outcome?.sourceIds)}<div class="history-outcome-reflection"><b>${t("נקודת מבט למחשבה","A PERSPECTIVE TO CONSIDER")}</b><p>${h(H.outcome?.reflection)}</p></div><button class="btn secondary small" data-action="hide-spoilers">${t('להסתיר שוב','Hide again')}</button>`:`<p>${t('ההיסטוריה האמיתית נותנת הקשר גם לסוף הסיפור. לחצו רק אם מתאים לכם לדעת מה עלה בגורל ההתקוממות.','The real history also gives context to the story’s ending. Continue only if you want to know the uprising’s fate.')}</p><button class="btn" data-action="enable-spoilers">${t('כן, לקרוא איך זה הסתיים','Yes, show me how it ended')}${arrow}</button>`}</section><div class="myth-grid">${(H.mythChecks||[]).map(m=>`<article><h3>${h(m.question)}</h3><p>${h(m.answer)}</p>${sources(m.sourceIds)}</article>`).join('')}</div><p class="small muted history-source-note">${t('מקורות נבדקו ב־10 באוקטובר 2026. קישורים חיצוניים עשויים לכלול את תוצאות המרד ואת סוף הסיפור.','Sources checked 10 October 2026. External links may reveal the uprising’s outcome and the story’s ending.')}</p><div class="button-row">${link('ideas',t('ומה עושים עם השאלות?','What do we do with the questions?'))}${link('map',t('לראות את המקומות במפה','See the places on the map'),'btn secondary')}${link('hugo',t('להכיר את האיש שכתב','Meet the man who wrote it'),'btn secondary')}</div></div>`}
function momentMark(){return `<svg class="moment-mark" viewBox="0 0 100 70" aria-hidden="true"><path d="M12 59 34 17 59 59Z" fill="#d9e4ff"/><path d="M41 59 66 17 88 59Z" fill="#ffdce0"/><circle cx="34" cy="17" r="11" fill="#002395"/><circle cx="66" cy="17" r="11" fill="#d51f35"/><path d="M20 61h60" stroke="currentColor" stroke-width="2"/></svg>`}
function momentBody(){const M=R.moments;if(!M)return '';if(!spoiler)return `<div class="moment-gate"><div><span class="tag">${t('קריאה משותפת · ספוילרים','A CLOSER READING · SPOILERS')}</span><h3>${t('להחליף נקודת מבט, לא לבחור מנצח.','Change your viewpoint, not pick a winner.')}</h3><p>${t('שלושה רגעים, שתי דמויות בכל פעם, ומה שהמוזיקה מוסיפה. הקריאה כוללת פרטים מסיום הסיפור ועיסוק במוות ובהתאבדות.','Three moments, two characters at a time, and what the music adds. The reading includes the story’s ending and discussion of death and suicide.')}</p></div><button class="btn" data-moment-open>${t('להיכנס עם ספוילרים','Enter with spoilers')}${arrow}</button></div>`;return `<div class="moment-tabs" role="group" aria-label="${t('בחירת רגע בסיפור','Choose a story moment')}">${M.moments.map((m,i)=>`<button data-moment="${i}" aria-pressed="${i===momentIndex}" class="${i===momentIndex?'active':''}"><span>0${i+1}</span>${h(m.title)}</button>`).join('')}</div><div id="moment-detail" tabindex="-1">${momentDetail()}</div>`}
function momentViewContent(){const m=R.moments?.moments[momentIndex],v=m?.views[momentView];if(!spoiler||!v)return '';return `<span class="eyebrow">${t('קריאה פרשנית שלנו','OUR INTERPRETIVE READING')} · ${h(v.name)}</span><h3>${h(v.title)}</h3><p>${h(v.body)}</p>`}
function momentDetail(){const m=R.moments?.moments[momentIndex];if(!m||!spoiler)return '';const v=m.views[momentView];return `<article class="moment-reading"><div class="moment-fact"><b>${t('הרגע בסיפור','THE STORY MOMENT')}</b><p>${h(m.scene)}</p></div><div class="moment-view-switch" role="group" aria-label="${t('דרך איזו דמות לקרוא?','Whose perspective will you consider?')}">${m.views.map((x,i)=>`<button data-moment-view="${i}" aria-controls="moment-view-panel" aria-pressed="${i===momentView}" class="${i===momentView?'active':''}"><span aria-hidden="true">${i===0?'A':'B'}</span>${h(x.name)}</button>`).join('')}</div><div class="moment-columns"><div class="moment-view-panel view-${momentView}" id="moment-view-panel" aria-live="polite" aria-atomic="true">${momentViewContent()}</div><aside class="moment-music"><span class="eyebrow">${t('ומה עושה המוזיקה?','WHAT DOES THE MUSIC ADD?')}</span><h3>${h(m.music.title)}</h3>${tr(m.music.fact)?`<small class="moment-fact-label">${t('קשר מוזיקלי מתועד','Documented musical link')}</small><p>${h(m.music.fact)}</p>`:''}<p class="moment-listen-prompt">${h(m.music.prompt)}</p>${m.links?.songId?`<button class="text-link" data-gallery-song="${esc(m.links.songId)}">${t('לרגע הזה במסע המחזמר','Find this moment in the musical')}${arrow}</button>`:''}</aside></div><div class="moment-question"><b>${t('ומה נשאר אצלכם?','WHAT STAYS WITH YOU?')}</b><p>${h(m.question)}</p><small>${t('אין תשובה נכונה, ניקוד או שמירה של עמדה אישית. אפשר פשוט לחשוב או לדבר על זה.','No right answer, score or saved personal response. Take a moment to think, or talk it through.')}</small></div><div class="moment-foot"><div class="moment-character-links">${(m.links?.characterIds||[]).map(id=>`<button class="text-link" data-map-character="${esc(id)}">${h(R.characters.find(c=>c.id===id)?.name||id)}${arrow}</button>`).join('')}</div><details class="moment-references"><summary>${t('מקורות ומיקום בסיפור','Sources and scene references')}</summary>${(m.sourceLocators||[]).map(x=>`<p>${h(x.locator)}</p>`).join('')}${sources(m.sourceIds)}</details></div></article>`}
function momentsExperience(){const M=R.moments;if(!M)return '';return `<section class="moments-experience" id="another-view" tabindex="-1" aria-labelledby="moments-title"><header class="moments-header">${momentMark()}<div><div class="eyebrow">${t('להסתכל. להקשיב. לשנות זווית.','LOOK. LISTEN. CHANGE YOUR ANGLE.')}</div><h2 id="moments-title">${h(M.title)}</h2><p>${h(M.intro)}</p></div></header><div id="moment-body">${momentBody()}</div></section>`}
function momentsInvitation(){return `<div class="moments-invitation"><b>${t('אותו רגע, מבט אחר','One moment, another view')}</b><p>${t('מה משתנה כשעוברים לצד השני של הסצנה? שלושה רגעים שמחברים דמויות, מוזיקה ושאלה שלכם.','What changes when you move to the other side of a scene? Three moments connect characters, music and a question of your own.')}</p><button class="text-link" data-moment-entry>${t('להיכנס לקריאה · אזהרת ספוילרים בכניסה','Explore the reading · spoiler warning at entry')}${arrow}</button></div>`}
function ideasPage(){const P=R.philosophy||{};const d=P.dilemmas?.[selectedDilemma]||P.dilemmas?.[0];if(!d)return top(t('חדר הדילמות','The dilemma room'),'',t('11 / הדילמות','11 / THE DILEMMAS'));return top(t('אין תשובה אחת.<br>יש שאלה שלא מרפה.','No single answer.<br>A question that stays.'),h(P.intro),t('11 / חדר הדילמות','11 / THE DILEMMA ROOM'))+`<div class="wrap section"><div class="ideas-disclaimer">${t('לכל עמדה יש טיעון חזק וגם שאלה קשה. נסו לתת מקום לשניהם.','Each position has a strong argument and a difficult question. Give both a hearing.')}</div><div class="ideas-contents" role="group" aria-label="${t('לבחור כיוון למחשבה','Choose a direction to explore')}"><button data-idea-jump="another-view">${t('אותו רגע, מבט אחר','One moment, another view')}</button><button data-idea-jump="dilemma-content">${t('הדילמות של הדמויות','The characters’ dilemmas')}</button><button data-idea-jump="love-line">${t('אהבה ופני האלוהים','Love and the face of God')}</button><button data-idea-jump="people-power">${t('כוח ההמון','The power of a crowd')}</button><button data-idea-jump="director-lab">${t('מעבדת בימוי','Director Lab')}</button></div>${momentsExperience()}<div class="dilemma-tabs" role="group" aria-label="${t('בחירת דילמה','Choose a dilemma')}">${P.dilemmas.map((x,i)=>`<button data-dilemma="${i}" class="${selectedDilemma===i?'active':''}" aria-pressed="${selectedDilemma===i}"><span>0${i+1}</span>${h(x.title)}</button>`).join('')}</div><div id="dilemma-content" tabindex="-1">${dilemmaDetail()}</div>${loveLineDiscussion()}${peoplePowerDiscussion()}${directorLab()}</div>`}
function loveLineDiscussion(){const L=R.loveLine;if(!L)return '';return `<section class="love-line" id="love-line" tabindex="-1" aria-labelledby="love-line-title"><div class="love-line-heading"><div class="eyebrow">${t('שורה אחת, יותר מדרך אחת לקרוא','ONE LINE, MORE THAN ONE READING')}</div><h2 id="love-line-title">${h(L.title)}</h2><blockquote lang="en" dir="ltr">${esc(L.userProvidedQuotation)}</blockquote><p class="love-attribution">${h(L.attribution)}</p></div><div class="love-origin"><h3>${t('מהמחזמר או מהספר?','The musical or the book?')}</h3><p>${t('הניסוח האנגלי המוכר הוא שורה מן המחזמר. כדאי לייחס אותה למילים האנגליות של הרברט קרצמר, ולא להציג אותה כציטוט מילולי מן הפרוזה של הוגו. בהמשך אפשר לפתוח גם הקבלה מדויקת ברומן, עם אזהרת ספוילרים.','The familiar English wording is a line from the musical. Credit it to Herbert Kretzmer’s English lyrics rather than presenting it as a verbatim quotation from Hugo’s prose. A precise parallel in the novel is available below, behind an ending-spoiler warning.')}</p>${sources(['love-line-official-study-guide','love-line-official-credits'])}</div><div class="love-lenses"><article><span>01</span><h3>${t('קריאה דתית: חסד הוא מפגש','A religious reading: grace as an encounter')}</h3><p>${t('אהבת אדם נעשית דרך לפגוש את האלוהי: בחמלה, בחסד ובנכונות למחול. הדימוי מזמין לחפש קדושה גם ביחסים עם אדם שהחברה מעדיפה לא לראות.','Loving another person becomes a way to encounter the divine through compassion, grace and forgiveness. The image invites us to look for holiness in our relationship with someone society would rather overlook.')}</p></article><article><span>02</span><h3>${t('קריאה חילונית: לראות אדם שלם','A secular reading: seeing a whole person')}</h3><p>${t('אפשר לשמוע כאן ביטוי פיוטי לכבודו ולערכו של אדם, מעבר לעברו ולתוויות שהוצמדו לו. אהבה משנה את אופן ההתבוננות, גם בלי לקבל את הדימוי כאמירה אמונית.','The image can express a person’s dignity and value beyond their past and the labels attached to them. Love changes how we see, even if we do not hear the line as a statement of faith.')}</p></article></div><div class="love-questions"><h3>${t('והשאלה שלא כדאי לדלג עליה','The question worth staying with')}</h3><p>${t('האם אהבה משנה את מי שאוהב, את מי שנאהב, או את שניהם? האם די בחסד אישי כדי לתקן עוול חברתי? ואיך רואים את אנושיותו של אדם שפגע באחרים, ועדיין דורשים אחריות ושומרים על גבולות?','Does love transform the person giving it, the person receiving it, or both? Can individual kindness repair systemic injustice? How do we recognize someone’s humanity while still requiring accountability and maintaining boundaries?')}</p></div><details class="love-biblical"><summary>${t('עוד שתי הקבלות שאפשר לחשוב איתן','Two more parallels to think with')}</summary><p>${h(L.optionalBiblicalConnections)}</p>${sources(['love-line-genesis','love-line-john'])}</details>${spoiler?`<div class="love-context" id="love-context" tabindex="-1"><div class="eyebrow">${h(L.spoilerNotice)}</div><h3>${t('כשהשורה פוגשת חיים שלמים','When the line meets a whole life')}</h3><p>${esc(L.body[lang][0])}</p><div class="love-novel-parallel"><span>${t('המקור הצרפתי · הוגו','HUGO’S ORIGINAL FRENCH')}</span><blockquote lang="fr" dir="ltr">${esc(L.novelParallel.french)}</blockquote><p>${esc(lang==='he'?L.novelParallel.heOriginalTranslation:L.novelParallel.enOriginalTranslation)}</p><small>${t('הקבלה ברומן · חלק ה׳, ספר ט׳, פרק ה׳. תרגום שלנו מן הצרפתית.','A parallel in the novel · Part V, Book IX, Chapter V. Our translation from French.')}</small></div><p>${esc(L.body[lang][2].split(lang==='he'?' כאן מתחיל הדיון:':' Does love transform')[0])}</p>${sources(['love-line-stage-synopsis','love-line-hugo-original'])}<div class="button-row">${link('novel',t('לחזור לחמשת חלקי הרומן','Revisit the novel’s five parts'),'secondary')}${link('after',t('לקחת את השאלה הביתה','Take the question home'),'secondary')}</div></div>`:`<div class="love-gate"><h3>${t('איך זה נשמע בתוך הסיום?','What does it mean within the ending?')}</h3><p>${t('הדיון הבא נכנס לסצנות האחרונות ולהקבלה בסיום הרומן. פתיחה מפעילה את מצב הספוילרים באתר.','This discussion enters the protagonist’s final scene and the novel’s ending. Opening it turns on the site’s spoiler mode.')}</p><button class="btn" data-action="love-open">${t('אפשר לפתוח את דיון הסיום','Open the ending discussion')}</button></div>`}</section>`}
function peoplePowerDiscussion(){const P=R.peoplePower;if(!P)return '';return `<section class="people-power" id="people-power" tabindex="-1" aria-labelledby="people-power-title"><header class="people-heading"><div><div class="eyebrow">${t('כשקול פרטי נעשה ציבור','WHEN A PRIVATE VOICE BECOMES PUBLIC')}</div><h2 id="people-power-title">${h(P.title)}</h2><p lang="en" dir="ltr">${esc(P.songTitle)}</p></div><svg viewBox="0 0 180 115" aria-hidden="true"><path d="M25 106V10" stroke="currentColor" stroke-width="5"/><path d="M28 10C72-10 110 35 168 7L158 70C103 94 71 37 28 68Z" fill="#ef3340"/><path d="M28 26C72 8 104 54 162 29" fill="none" stroke="#ff8d95" stroke-width="2"/><circle cx="83" cy="96" r="7" fill="currentColor"/><circle cx="115" cy="96" r="7" fill="currentColor"/><circle cx="147" cy="96" r="7" fill="currentColor"/></svg></header><div class="people-setup"><p>${h(P.intro.body)}</p><div class="people-interpretation"><span>${h(P.labels.interpretation)}</span><p>${h(P.interpretation.body)}</p></div>${sources(P.intro.sourceIds)}</div><div class="people-context-grid"><article><span class="eyebrow">${h(P.labels.history)}</span><h3>${t('פריז, 1832','Paris, 1832')}</h3><p>${h(P.historicalContext.body)}</p>${sources(P.historicalContext.sourceIds)}</article><article><span class="eyebrow">${h(P.labels.terminology)}</span><h3>${h(P.proletariatConnection.title)}</h3><p>${h(P.proletariatConnection.body)}</p>${sources(P.proletariatConnection.sourceIds)}</article></div><div class="people-listen"><h3>${h(P.labels.lenses)}</h3><div class="people-lens-tabs" role="group" aria-label="${h(P.labels.lenses)}">${P.lenses.map((l,i)=>`<button data-people-lens="${l.id}" aria-pressed="${peopleLens===l.id}" class="${peopleLens===l.id?'active':''}"><span>0${i+1}</span>${h(l.title)}</button>`).join('')}</div><div id="people-lens-detail" aria-live="polite" aria-atomic="true">${peopleLensDetail()}</div></div><div class="people-more"><details><summary>${t('מילון קטן, הבדל גדול','A small glossary, a big difference')}</summary><div class="people-glossary">${P.glossary.map(g=>`<article><h4>${h(g.term)}</h4><p>${h(g.body)}</p>${sources(g.sourceIds)}</article>`).join('')}</div></details><details><summary>${t('רגע, איזו מהפכה?','Wait, which revolution?')}</summary><div class="people-dates">${P.timeline.filter(x=>spoiler||x.spoilerLevel<2).map(x=>`<article><b>${esc(x.date)}</b><p>${h(x.body)}</p>${sources(x.sourceIds)}</article>`).join('')}</div>${link('history',h(P.historyLink.label),'secondary')}</details></div><div class="people-outcome" id="people-outcome" tabindex="-1"><div class="eyebrow">${h(P.labels.spoilerNotice)}</div>${spoiler?`<h3>${h(P.outcome.title)}</h3><p>${h(P.outcome.body)}</p>${sources(P.outcome.sourceIds)}`:`<p>${t('מה קורה כשהתקווה הקולקטיבית פוגשת את תוצאות העלילה? פתיחה מפעילה את מצב הספוילרים באתר.','What happens when collective hope meets the story’s outcome? Opening this discussion turns on the site’s spoiler mode.')}</p><button class="btn" data-action="people-open">${h(P.labels.spoilerReveal)}</button>`}</div><div class="people-next">${link('history',t('לפרוש את ציר ההיסטוריה','Explore the historical timeline'),'secondary')}${link('map',t('לראות איפה זה מתרחש','See where the story happens'),'secondary')}</div></section>`}
function peopleLensDetail(){const P=R.peoplePower,l=P.lenses.find(x=>x.id===peopleLens)||P.lenses[0];return `<article class="people-lens"><span>${h(P.labels.interpretation)}</span><h4>${h(l.title)}</h4><p>${h(l.body)}</p><div><b>${h(P.labels.question)}</b><p>${h(l.question)}</p></div>${sources(l.sourceIds)}</article>`}
function clearReadingSearchTarget(){const q=new URLSearchParams(location.search||'');if(!q.has('focus'))return;q.delete('focus');const suffix=q.toString();history.replaceState(history.state,'',url(route)+(suffix?'?'+suffix:'')+(location.hash||''));renderedPath=(location.pathname||'')+(location.search||'')}
function readingReferences(refs,fold=true){return refs?.length?`${fold?`<details class="reading-references"><summary>${t('אל הסצנות והמקורות','Explore the scenes and sources')}</summary>`:'<div class="reading-references">'}<ul>${refs.map(r=>`<li>${external(r.url,tr(r.label))}${r.note?`<p>${h(r.note)}</p>`:''}</li>`).join('')}</ul>${fold?'</details>':'</div>'}`:''}
function dilemmaDetail(){
 const d=R.philosophy?.dilemmas?.[selectedDilemma];if(!d)return '';
 if(d.spoilerLevel>=2&&!spoiler)return `<div class="gate"><h2>${h(d.title)}</h2><button class="btn" data-action="enable-spoilers">${t('לפתוח את הדילמה · כולל ספוילרים','Open the dilemma · includes spoilers')}</button></div>`;
 return `<section class="dilemma-room" data-dilemma-reading="${esc(d.id)}"><div class="dilemma-vignette"><h2>${h(d.title)}</h2><p>${h(d.vignette)}</p></div><div class="dilemma-context">${(d.contextParagraphs||[]).map(p=>`<p>${h(p)}</p>`).join('')}</div><div class="perspectives">${d.perspectives.map((p,i)=>`<article class="perspective"><span class="perspective-index">${String.fromCharCode(65+i)}</span><h3>${h(p.title)}</h3><p>${h(p.argument)}</p><details class="challenge"><summary>${t('והשאלה הקשה לעמדה הזאת','The difficult question for this position')}</summary><p>${h(p.challenge)}</p></details></article>`).join('')}</div>${d.deepening?(spoiler?`<details class="dilemma-deepening"><summary>${h(d.deepening.title)}</summary><div>${d.deepening.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${readingReferences(d.deepening.references,false)}</div></details>`:`<div class="dilemma-story-invitation"><p>${t('הבחירות של הדמויות מסבכות את השאלה עוד יותר.','The characters’ decisions make the question more difficult still.')}</p><button class="text-button" data-dilemma-reveal>${t('אל הרגעים בעלילה · כולל ספוילרים','Explore the story moments · includes spoilers')}${arrow}</button></div>`):''}<div class="reflection"><div><h3>${t('עכשיו, בלי שהמחזמר יענה במקומכם.','Now, without the musical answering for you.')}</h3><p>${h(d.askYourself)}</p><div class="reflection-choices" role="group" aria-label="${t('התגובה שלי כרגע','My response right now')}"><button data-reflection="a">${t('נטיית הלב שלי התחדדה','My view is clearer')}</button><button data-reflection="b">${t('אני עדיין מתלבט/ת','I’m still thinking')}</button><button data-reflection="c">${t('שיניתי כיוון','I changed my mind')}</button></div><p class="reflection-feedback" id="reflection-feedback" role="status"></p></div></div>${readingReferences(d.references)}${sources(d.sourceIds)}</section>`;
}
function coachAnalysis(songId,view='journey'){
 const items=(R.coachVideos||[]).filter(v=>v.songId===songId);if(!items.length)return '';
 return items.map(v=>{const instance='coach-'+view+'-'+v.id,allowed=spoiler||v.spoilerLevel<2;
  return `<aside class="coach-analysis" data-coach-analysis="${esc(v.id)}" aria-labelledby="${instance}-title"><header><span class="coach-symbol" aria-hidden="true">♪</span><div><div class="eyebrow">${t('מבט של מורה לפיתוח קול','A VOCAL COACH’S PERSPECTIVE')}</div><h4 id="${instance}-title">${h(v.title)}</h4><p class="coach-credit">${external(v.coach.url,v.coach.name)} · ${h(v.coach.credential)}</p></div></header><div class="coach-meta"><span>${t('ניתוח ביצוע','Performance analysis')}</span><span>${v.language==='en'?t('הסרטון באנגלית','Video in English'):v.language==='he'?t('הסרטון בעברית','Video in Hebrew'):esc(v.language)}</span>${v.durationLabel?`<bdi>${esc(v.durationLabel)}</bdi>`:''}</div>${allowed?`<p class="coach-intro">${h(v.body)}</p>${v.embeddable?video(videos.find(x=>x.id===v.id),instance):`<p>${external('https://www.youtube.com/watch?v='+v.id,t('לצפות בניתוח בערוץ המקורי','Watch the analysis on the original channel'))}</p>`}${v.watchFor?`<div class="coach-question"><b>${t('לחזור לשיר עם שאלה','TAKE A QUESTION BACK TO THE SONG')}</b><p>${h(v.watchFor)}</p></div>`:''}${v.analysedPerformanceId?`<a class="text-link coach-return" href="${url('listening')}?clip=${esc(v.analysedPerformanceId)}" data-gallery-link="${esc(v.analysedPerformanceId)}">${t('בחזרה לביצוע של אלפי בו ושנברג','Return to Boe and Schönberg’s performance')}${arrow}</a>`:''}<details class="coach-sources"><summary>${t('על המורה ומקור הסרטון','About the coach and video source')}</summary>${v.suggestedChapter?`<p>${external(v.suggestedChapter.url,tr(v.suggestedChapter.label))}</p>`:''}${sources(v.sourceIds)}</details>`:`<div class="coach-plot-gate"><p>${t('הניתוח נכנס גם לסיפור שסביב השיר.','This analysis also explores the story around the song.')}</p><button class="text-button" data-coach-reveal="${esc(instance)}">${t('לפתוח את הניתוח · כולל ספוילרים','Open the analysis · includes spoilers')}${arrow}</button></div>`}</aside>`;
 }).join('');
}
function songReading(id,view='journey'){
 const r=R.musical?.songAnalysis?.[id];if(!r)return '';
 const allowed=(r.blocks||[]).filter(b=>spoiler||b.spoilerLevel<2),blocks=view==='gallery'?allowed.filter(b=>b.kind==='listening'):allowed;
 if(!blocks.length)return '';
 const order=view==='spotlight'?['musical','listening','dramatic']:['dramatic','musical','listening'];blocks.sort((a,b)=>order.indexOf(a.kind)-order.indexOf(b.kind));
 const block=b=>`<section class="song-reading-block" data-song-reading-kind="${esc(b.kind)}"><h4>${h(b.title)}</h4><p>${h(b.body)}</p></section>`;
 const first=view==='spotlight'?blocks.filter(b=>b.kind==='musical'):view==='gallery'?blocks:blocks.filter(b=>b.kind!=='listening'),more=blocks.filter(b=>!first.includes(b));
 const craft=spoiler?(r.craftNotes||[]).filter(b=>spoiler||b.spoilerLevel<2):[];
 return `<section class="song-reading song-reading-${view}" data-song-reading="${esc(id)}" aria-label="${t('בתוך השיר','Inside the song')}">${view==='gallery'?`<div class="eyebrow">${t('ניסוי קטן בצפייה ובהאזנה','A SMALL WATCHING AND LISTENING EXPERIMENT')}</div>`:''}${first.map(block).join('')}${more.length?`<details class="song-reading-more"><summary>${view==='spotlight'?(spoiler?t('להמשיך: ניסוי בהאזנה והסיפור שמאחורי הרגע','Read on: a listening experiment and the scene’s story'):t('ניסוי להאזנה הבאה','A listening experiment to try')):t('לנסות בהאזנה הבאה','Try it on your next listen')}</summary>${more.map(block).join('')}</details>`:''}${craft.map(b=>`<aside class="song-craft-note"><h4>${h(b.title)}</h4><p>${h(b.body)}</p>${sources(b.sourceIds)}</aside>`).join('')}${view!=='gallery'&&spoiler&&r.relatedSongIds?.length?`<div class="song-reading-related"><b>${t('עוד רגעים שכדאי להשוות','Other moments worth comparing')}</b>${r.relatedSongIds.map(id=>{const s=R.musical.songentries.find(s=>s.id===id);return s?`<button class="text-button" data-song-journey="${esc(id)}">${h(s.title)}${arrow}</button>`:''}).join('')}</div>`:''}${view!=='gallery'?`<details class="song-reading-sources"><summary>${t('מקורות והקשר בימתי','Sources and stage context')}</summary>${sources(r.sourceIds)}</details>`:''}</section>${coachAnalysis(id,view)}`;
}

function policySources(ids=[]){const lookup=Object.fromEntries(window.SITE_POLICIES.sources.map(x=>[x.id,x]));return `<div class="source-links">${ids.filter(id=>lookup[id]).map(id=>external(lookup[id].url,tr(lookup[id].title))).join('')}</div>`}
function policySections(sections,prefix){return sections.map((x,i)=>`<article class="policy-section" id="${prefix}-${x.id}" tabindex="-1"><span class="policy-number">${String(i+1).padStart(2,'0')}</span><div><h2>${h(x.title)}</h2>${x.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${policySources(x.sourceIds)}</div></article>`).join('')}
function policyStorage(){const items=window.SITE_POLICIES.storageInventory;return `<details class="storage-inventory"><summary>${t('מה בדיוק נשמר, ואיפה?','What exactly is stored, and where?')}</summary><div>${items.map(x=>`<article><h3>${h(x.purpose)}</h3><code dir="ltr">${esc(x.key)}</code><p>${esc(x.technology)}</p><p>${x.category==='necessary'?t('רישום ההסכמה: 180 יום.','Consent record: 180 days.'):x.category==='functional'?t('רק לאחר אישור; עד מחיקה יזומה או הסרה בידי הדפדפן.','Only with permission; until cleared by you or removed by the browser.'):x.category==='requested-session-function'?t('ביקור או רשומת היסטוריה בלשונית; הדפדפן עשוי לשחזר ביקור.','Tab session or history entry; a browser may restore a session.'):x.category==='analytics'?t('לא פעיל. מתוכננת תפוגת עוגיות של 180 יום; תקופת השמירה בדוחות טרם אומתה.','Inactive. Planned cookie expiry: 180 days; reporting retention is not yet verified.'):t('אחסון בשליטת ספק השירות או הדפדפן, לפי מדיניותם.','Storage controlled by the provider or browser, under their policies.')}</p></article>`).join('')}</div></details>`}
function policyPage(kind){const D=window.SITE_POLICIES,d=D[kind];return top(h(d.title),h(d.intro),kind==='terms'?t('19 / תנאי שימוש','19 / TERMS OF USE'):t('20 / פרטיות ובחירות','20 / PRIVACY & CHOICES'))+`<div class="wrap section policy-page"><p class="policy-draft">${h(D.meta.draftNotice)}</p>${kind==='privacy'?`<div class="policy-controls"><div><h2>${t('השליטה כאן, בכל רגע','Your controls, at any time')}</h2><p>${t('קריאה ושימוש בכלים אינם מחייבים אישור למדידה. בחירות פרטיות אינן פותחות ספוילרים.','Reading and using the tools do not require analytics consent. Privacy choices never reveal spoilers.')}</p></div><button class="btn" data-action="privacy-open">${t('ניהול הבחירות שלי','Manage my choices')}</button></div>`:''}<nav class="policy-index" aria-label="${t('סעיפי העמוד','Sections on this page')}">${d.sections.map(x=>`<button data-jump="policy-${x.id}">${h(x.title)}</button>`).join('')}</nav>${policySections(d.sections,'policy')}${kind==='privacy'?`<section class="policy-cookies"><div class="eyebrow">${t('עוגיות ושמירה בדפדפן','COOKIES + LOCAL STORAGE')}</div><h2>${h(D.cookies.title)}</h2><p>${h(D.cookies.intro)}</p>${policySections(D.cookies.sections,'storage')}${policyStorage()}</section>`:''}<div class="button-row">${link(kind==='privacy'?'terms':'privacy',kind==='privacy'?t('תנאי השימוש','Terms of use'):t('פרטיות ובחירות','Privacy and choices'),'btn secondary')}${link('about',t('למקורות ולקרדיטים','Sources and credits'),'btn secondary')}</div></div>`}
function privacyUI(){const choice=P.choice(),a=window.SiteAnalytics,configured=!!a?.configured;return `${choice?'':`<section class="privacy-banner" aria-labelledby="privacy-banner-title"><div><h2 id="privacy-banner-title">${t('הפרטיות שלכם','Your privacy')}</h2><p>${t('אפשר לאשר זכירת העדפות ומדידה ב־Google Analytics, לדחות את שתיהן, או לבחור בנפרד בהגדרות.','Allow remembered preferences and Google Analytics, reject both, or choose separately in Settings.')}</p></div><div class="privacy-banner-actions"><button class="btn secondary" data-action="privacy-accept">${t('אישור הכול','Accept all')}</button><button class="btn secondary" data-action="privacy-reject">${t('דחיית הכול','Reject all')}</button><button class="btn secondary" data-action="privacy-open">${t('הגדרות','Settings')}</button></div></section>`}<dialog class="modal privacy-modal" id="privacy-dialog" aria-labelledby="privacy-dialog-title"><div class="eyebrow">${t('הבחירות שלכם','YOUR CHOICES')}</div><h2 id="privacy-dialog-title">${t('פרטיות, בלי משחקי מחבואים','Privacy, in plain sight')}</h2><p>${t('בחירה נשמרת ל־180 יום. אפשר לשנות אותה בכל רגע דרך תחתית העמוד. הסכמה לספוילרים נשארת בחירה נפרדת.','Your choice is remembered for 180 days. Change it at any time from the footer. Spoiler consent remains separate.')}</p><p class="privacy-essential"><b>${t('נחוץ לפעולה','Necessary for operation')}</b> · ${t('רישום בחירות הפרטיות וההחלטות המפורשות על ספוילרים בלשונית.','The privacy-choice record and explicit spoiler choices in this tab.')}</p><label class="privacy-option"><input type="checkbox" id="privacy-functional" ${choice?.functional?'checked':''}><span><b>${t('לזכור העדפות והתקדמות','Remember preferences and progress')}</b><small>${t('שפה, סימוני הקשבה, סימניות, המסע האחרון ומקצה החידון יישמרו בדפדפן הזה. בלי אישור הם נשארים בזיכרון הביקור בלבד.','Language, listening checkmarks, bookmarks, your last journey and quiz round stay in this browser. Without permission, they use this visit’s memory only.')}</small></span></label><label class="privacy-option"><input type="checkbox" id="privacy-analytics" ${choice?.analytics?'checked':''}><span><b>${t('מדידה באמצעות Google Analytics','Measurement with Google Analytics')}</b><small>${t('עוזרת למדוד עמודים, מסלולים, התקדמות בחידון, הפעלת סרטונים, בחירות במפה, מספר תוצאות בחיפוש, תוצאות שליחת פנייה, החלפת שפה, שיתוף וסימניות. בלי שמות, דוא״ל, טקסט חיפוש או טופס, תשובות אישיות או עמדות בדילמות.','Helps measure pages, paths, quiz progress, video playback, map selections, search result counts, contact submission outcomes, language changes, sharing and bookmarks. No names, email addresses, search text, form text, individual answers or dilemma positions.')}</small><small class="analytics-availability">${configured?t('מוגדר, ונטען רק לאחר הסכמה.','Configured; loads only with consent.'):t('עדיין לא פעיל: מזהה המדידה הוגדר; בדיקת הגדרות Google Analytics ממתינה. אישור מאפשר הפעלה רק לאחר הבדיקה.','Not active yet: the measurement ID is set; the Google Analytics settings check is pending. Approval permits activation only after that check.')}</small></span></label><div class="button-row"><button class="btn" data-action="privacy-save">${t('שמירת הבחירות','Save choices')}</button><button class="btn secondary" data-action="privacy-reject">${t('דחיית כל האפשרויות','Reject all optional')}</button><button class="text-button" data-action="privacy-close">${t('סגירה בלי שינוי','Close without changes')}</button></div><div class="privacy-erase"><p>${t('כיבוי הזכירה מפסיק שימוש בשמירה הקיימת. אם רוצים גם להסיר אותה מהמכשיר:','Turning remembering off stops using existing saved data. To remove it from this device too:')}</p><button class="text-button" data-action="privacy-erase-open">${t('ביטול זכירה ומחיקת ההתקדמות השמורה','Turn off remembering and erase saved progress')}</button></div><div class="privacy-policy-links"><a href="${url('privacy')}">${t('מדיניות הפרטיות המלאה','Full privacy policy')}</a><a href="${url('terms')}">${t('תנאי השימוש','Terms of use')}</a></div></dialog><dialog class="modal" id="privacy-erase-dialog" aria-labelledby="privacy-erase-title"><h2 id="privacy-erase-title">${t('למחוק את השמירה מהמכשיר?','Erase saved data from this device?')}</h2><p>${t('פעולה זו תמחק רק את השפה השמורה, סימוני ההקשבה, הסימניות, המסע האחרון ומקצה החידון של האתר הזה. אין אפשרות לשחזר אותם דרך האתר. בחירות הפרטיות יישארו, והזכירה תכובה. היא לא תמחק נתונים שכבר נמסרו לספק חיצוני או קבצים ששיתפתם או הורדתם.','This removes only this guide’s saved language, listening checkmarks, bookmarks, last journey and quiz round. The site cannot restore them. Privacy choices stay, and remembering turns off. It does not erase data already sent to an external provider or files you shared or downloaded.')}</p><div class="button-row"><button class="btn secondary" data-action="privacy-erase-cancel">${t('לבטל ולשמור','Cancel and keep data')}</button><button class="btn" data-action="privacy-erase-confirm">${t('כן, למחוק את השמירה הזאת','Yes, erase this saved data')}</button></div></dialog>`}
function privacyTransition(old,current){if(old?.functional&&!current?.functional){P.forgetMemory();checked=[];quizRun=null;quizInitialized=false;quizConsent=false;save('barricade-quiz-consent','off',true)}else if(!old?.functional&&current?.functional){try{const saved=JSON.parse(getStored('barricade-listening')||'[]');if(Array.isArray(saved))checked=saved.filter(x=>['stars','prayer','ensemble'].includes(x))}catch{}if(!quizRun){quizInitialized=false;initQuiz();quizConsent=false;save('barricade-quiz-consent','off',true)}}A.consent();}
function applyPrivacy(values){const change=P.choose(values);privacyTransition(change.previous,change.current);if(pendingBookmark&&change.current.functional&&!savedBookmarks().includes(pendingBookmark)){save('barricade-bookmarks',JSON.stringify([...savedBookmarks(),pendingBookmark]));A.track('bookmark_change',{content_id:pendingBookmark,bookmark_action:'add'});}pendingBookmark=null;focusAfterRender=true;render();announce(t('העדפות הפרטיות עודכנו','Privacy choices updated'))}

function privacyAction(action){if(action==='privacy-open'){pendingBookmark=null;document.getElementById('privacy-dialog').showModal();return true}if(action==='privacy-close'){pendingBookmark=null;document.getElementById('privacy-dialog').close();return true}if(action==='privacy-accept'||action==='privacy-reject'){const yes=action==='privacy-accept';applyPrivacy({functional:yes,analytics:yes,media:P.choice()?.media===true});return true}if(action==='privacy-save'){applyPrivacy({functional:document.getElementById('privacy-functional').checked,analytics:document.getElementById('privacy-analytics').checked,media:P.choice()?.media===true});return true}if(action==='privacy-erase-open'){pendingBookmark=null;document.getElementById('privacy-dialog').close();document.getElementById('privacy-erase-dialog').showModal();return true}if(action==='privacy-erase-cancel'){document.getElementById('privacy-erase-dialog').close();document.getElementById('privacy-dialog').showModal();return true}if(action==='privacy-erase-confirm'){pendingBookmark=null;const c=P.choice()||{};P.eraseOptional();P.choose({...c,functional:false});checked=[];quizRun=null;quizInitialized=false;quizConsent=false;save('barricade-quiz-consent','off',true);focusAfterRender=true;render();announce(t('הזכירה כובתה והשמירה המקומית נמחקה','Remembering is off and saved local data was erased'));return true}return false}

function dialogs(){return `<dialog class="modal" id="spoiler-dialog" aria-labelledby="spoiler-dialog-title"><div class="eyebrow">${t('בחירה שלכם','YOUR CHOICE')}</div><h2 id="spoiler-dialog-title">${t('לפתוח את כל הסיפור?','Reveal the whole story?')}</h2><p>${t('הפעלת ספוילרים פותחת פרטי עלילה והסיום בטקסטים המוגנים באתר. אפשר להסתיר אותם שוב בכל רגע. סרטונים וקישורים חיצוניים עשויים לחשוף פרטים נוספים.','Turning spoilers on reveals protected plot details and the ending in this guide. You can hide them again at any time. Videos and external links may reveal more.')}</p><div class="button-row"><button class="btn" data-action="confirm-spoilers">${t('כן, לפתוח את הספוילרים','Yes, reveal spoilers')}</button><button class="btn secondary" data-action="close-dialog">${t('עוד לא','Not yet')}</button></div></dialog>`}
// Insert inside app.js's existing IIFE, immediately before function render().
function applySearchSelection(){
 const target=window.SiteSearch?.readTarget(location.search,route);
 if(!target)return null;
 const key=target.key;
 if(target.kind==='character'){
  if(!(R.characters||[]).some(x=>x.id===key))return null;
  character=key;relationshipFilter='all';
 }else if(target.kind==='song'){
  const featured=R.musical?.spotlight?.songs.some(x=>x.id===key);
  const index=showStops().findIndex(x=>x.id===key);
  if(!featured&&(!spoiler||index<0))return null;
  if(featured)featuredSong=key;
  if(index>=0){showAct='all';showIndex=index;}
 }else if(target.kind==='atlas'){
  const place=R.map?.places?.find(x=>x.id===key);if(!place)return null;
  mapScope=place.scope;selectedPlace=key;
 }else if(target.kind==='dilemma'){
  const index=R.philosophy?.dilemmas.findIndex(x=>x.id===key);if(index===undefined||index<0)return null;
  selectedDilemma=index;
 }else if(target.kind==='craft'){
  if(!R.musical?.creationStory?.craft.some(x=>x.id===key))return null;
 }else if(target.kind==='extra'){
  if(!afterConsent||!spoiler||(key!=='collection'&&!R.hugoExtras?.stories.some(x=>x.id===key)))return null;
 }else if(target.kind==='novel'){
  if(!novelConsent||!spoiler||!R.novel?.milestones.some(x=>x.id===key))return null;
  novelPart='all';
 }
 return target;
}
function navigateSearchResult(href){
 // All destinations are same-site known records; never put free-text queries in history.
 if(!/^\/(he|en)\/[a-z]+\/(?:\?(?:focus|place|clip)=[A-Za-z0-9_%:-]+)?$/.test(href))return;
 window.SiteSearch?.close(false);
 pendingBookmark=null;history.pushState(null,'',href);focusAfterRender=true;render();
 if(!new URLSearchParams(location.search||'').get('focus')&&route!=='places')window.scrollTo({top:0,behavior:'instant'});
}

function render(){window.SiteContact?.cleanup();window.PlaceAtlas?.cleanup();menuGroup=null;clearPlayers();const part=routeLocation();if(part)lang=part[1];route=part&&Object.hasOwn(labels,part[2])?part[2]:'home';const alias=route==='humor'?'humor':route==='tribute'?'together':null;if(alias){route='listening';galleryReadLocation(alias);history.replaceState(history.state,'',galleryHref(null,alias))}else{if((location.hash||'').startsWith('#/')||!part)history.replaceState(history.state,'',url(route));if(route==='listening')galleryReadLocation()}if(route==='characters')readRelationshipLocation();const searchTarget=applySearchSelection();save('barricade-lang',lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';document.title=`${tr(labels[route])} · LesMisNotes`;updatePageMetadata();rememberJourney();A.context(route,lang,history.state?.lesmisJourney);const pages={home,israel:israelPage,watch:watchPage,contact:()=>window.SiteContact?.render({lang})||top(t('צור קשר','Contact'),t('טופס הפנייה לא זמין כרגע.','The feedback form is currently unavailable.'),'CONTACT'),recipes:recipesPage,places:placesPage,humor:humorPage,terms:()=>policyPage('terms'),privacy:()=>policyPage('privacy'),sitemap:sitemapPage,story:storyPage,characters:charactersPage,listening:listeningPage,compare:comparePage,screen:screenPage,tribute:tributePage,resources:resourcesPage,about:aboutPage,map:mapPage,history:historyPage,ideas:ideasPage,quiz:quizPage,musical:musicalPage,novel:novelPage,hugo:hugoPage,before:()=>curtainPage('before'),after:()=>curtainPage('after')};app.innerHTML=header()+`<main id="main" class="main" tabindex="-1">${journeyContinuation()}${pages[route]()}${relatedRoutes()}</main>`+footer()+dialogs()+privacyUI();if(focusAfterRender){document.getElementById('main').focus({preventScroll:true});focusAfterRender=false}window.SiteContact?.mount({lang,route});window.PlaceAtlas?.mount({lang,spoiler,route});mountPlayers();window.SiteSearch?.mount({lang,spoiler,novelConsent,afterConsent,route,onNavigate:navigateSearchResult});window.SiteSearch?.focusTarget(searchTarget);renderedPath=(location.pathname||'')+(location.search||'');renderedJourney=history.state?.lesmisJourney||null;mountQuizAchievement();if(route==='characters'&&location.hash==='#relationship-map')focusRelationshipMap();}
function announce(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(announce.timer);announce.timer=setTimeout(()=>el.classList.remove('visible'),3200)}

function setSpoilers(value){focusAfterRender=true;spoiler=value;if(!value){directorConsent=false;afterConsent=false;save('barricade-after-consent','off',true);novelConsent=false;save('barricade-novel-consent','off',true);quizConsent=false;save('barricade-quiz-consent','off',true)};save('barricade-spoilers',value?'on':'off',true);render();announce(value?t('הספוילרים פתוחים','Spoilers revealed'):t('הספוילרים הוסתרו','Spoilers hidden'))}

let seatChoice='whole-stage';
function practicalLinks(links=[]){return `<div class="source-links">${links.map(l=>external(l.url,tr(l.label))).join('')}</div>`}
function seatAdvice(){const S=R.beforePractical.seats,c=S.choices.find(x=>x.id===seatChoice)||S.choices[0];return `<div class="seat-advice" aria-live="polite"><div><b>${t('איפה להתחיל להשוות','WHERE TO START COMPARING')}</b><p>${h(c.consider)}</p></div><div><b>${t('הפשרה שכדאי להכיר','THE TRADEOFF')}</b><p>${h(c.tradeoff)}</p></div><div><b>${t('לפני שבוחרים מושב מסוים','BEFORE CHOOSING A SPECIFIC SEAT')}</b><p>${h(c.check)}</p></div></div>`}
function beforePrimer(){const d=R.curtain.before.primer;return `<section id="before-primer" class="before-primer" aria-labelledby="before-primer-title"><div><span class="eyebrow">${t('לבחירתכם','ONLY IF YOU WANT')}</span><h2 id="before-primer-title">${h(d.title)}</h2><p>${h(d.subtitle)}</p></div><button id="before-primer-toggle" class="btn secondary" data-action="before-primer" aria-expanded="${beforePrimerOpen}" aria-controls="before-primer-body">${h(beforePrimerOpen?d.closeLabel:d.openLabel)}</button><div id="before-primer-body" ${beforePrimerOpen?'':'hidden'}>${beforePrimerOpen?`${d.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}<p class="source-caution">${t('מקור התקציר החיצוני מגלה את העלילה המלאה.','The external synopsis source reveals the full plot.')}</p>${sources(d.sourceIds)}<div class="primer-next">${link('story',h(d.storyLabel),'text-link')}<small>${h(d.storyWarning)}</small></div>`:''}</div></section>`}
function familyExtra(){const F=R.beforePractical.family;return `<details class="practical-details family-themes"><summary>${h(F.themeDetails.title)}</summary><div class="family-theme-grid">${F.themeDetails.items.map(x=>`<article><h3>${h(x.title)}</h3><p>${h(x.body)}</p></article>`).join('')}</div><p class="source-caution">${t('התקציר במקור החיצוני חושף את העלילה כולה.','The external synopsis source reveals the full plot.')}</p>${sources(['practical-mti-synopsis','practical-london-show'])}</details><details class="practical-details family-preparation"><summary>${h(F.preparation.title)}</summary><p>${h(F.preparation.intro)}</p><ol>${F.preparation.steps.map(x=>`<li>${h(x)}</li>`).join('')}</ol><p class="family-opening">${h(F.preparation.openingLine)}</p></details>`}
function beforePractical(){const P=R.beforePractical;if(!P)return '';return `<section class="before-practical" id="before-practical"><div class="section-head"><div><div class="eyebrow">${t('תוספת מעשית למסלול · לפני שמזמינים','A PRACTICAL EXTRA · BEFORE BOOKING')}</div><h2>${h(P.title)}</h2></div><p>${h(P.intro)}</p></div><div class="production-scope">${h(P.scope)}</div><div class="practical-facts">${P.quickFacts.map(f=>`<article class="fact-${esc(f.id)}"><span>${h(f.label)}</span><h3>${h(f.value)}</h3><p>${h(f.body)}</p>${sources(f.sourceIds)}</article>`).join('')}</div><section class="family-guidance"><div class="family-heading"><div><span class="tag">${t('משפחות · בלי לגלות מי עושה מה','FAMILIES · NO CHARACTER OUTCOMES')}</span><h2>${h(P.family.title)}</h2></div><span class="family-recommendation">${t("המלצת לונדון הרשמית","OFFICIAL LONDON RECOMMENDATION")}<b>7+</b></span></div><p class="family-judgment">${h(P.family.judgmentNote)}</p><div class="content-warning"><h3>${h(P.family.editorialContentNote.title)}</h3><p>${h(P.family.editorialContentNote.body)}</p>${sources(P.family.editorialContentNote.sourceIds)}</div>${familyExtra()}<div class="admission-box"><h3>${h(P.family.admissionTitle)}</h3><ul>${P.family.admissionRules.map(r=>`<li>${h(r.text)}</li>`).join('')}</ul>${practicalLinks(P.family.links)}</div><details class="practical-details"><summary>${t('שלוש שאלות שיעזרו לכם להחליט','Three questions to help you decide')}</summary><ul>${P.family.parentQuestions.map(q=>`<li>${h(q)}</li>`).join('')}</ul><p>${h(P.family.usefulIdea)}</p>${sources(P.family.usefulIdeaSources.sourceIds)}</details></section><section class="seat-workshop"><div class="eyebrow">${t('לבחור את מקום הישיבה','CHOOSING YOUR SEAT')}</div><h2>${h(P.seats.title)}</h2><p>${h(P.seats.intro)}</p><div class="seat-choice-buttons" role="group" aria-label="${h(P.seats.selectionLabel)}">${P.seats.choices.map((c,i)=>`<button data-seat-choice="${esc(c.id)}" class="${seatChoice===c.id?'active':''}" aria-pressed="${seatChoice===c.id}"><span>0${i+1}</span>${h(c.label)}</button>`).join('')}</div><div id="seat-advice">${seatAdvice()}</div><div class="note">${h(P.seats.accessCaution)}${sources(P.seats.accessCautionSources.sourceIds)}</div>${practicalLinks(P.seats.links)}</section><div class="practical-bottom"><details class="practical-details"><summary>${h(P.visit.title)}</summary><ul class="visit-checklist">${P.visit.checklist.map(c=>`<li><p>${h(c.text)}</p>${c.sourceIds.length?sources(c.sourceIds):`<small>${t('הצעה שלנו','Our suggestion')}</small>`}</li>`).join('')}</ul><h3>${h(P.visit.homeward.title)}</h3><p>${h(P.visit.homeward.body)}</p>${sources(P.visit.homeward.sourceIds)}${practicalLinks(P.visit.links)}</details><details class="practical-details"><summary>${h(P.access.title)}</summary><p>${h(P.access.body)}</p><div class="access-contact"><b>${t('צוות הנגישות הרשמי','OFFICIAL ACCESS TEAM')}</b><span dir="ltr">${esc(P.access.contact.email)}</span><span dir="ltr">${esc(P.access.contact.phoneDisplay)}</span></div>${practicalLinks(P.access.links)}</details></div></section>`}

let beforePrimerOpen=false;
let afterConsent=getStored('barricade-after-consent',true)==='on';
let curtainChecked={before:[],after:[]};
let directorConsent=false;
let directorScene=0;
let directorSelections={};
function curtainStopChooser(kind){const d=R.curtain[kind];return `<section class="curtain-chooser"><h3>${kind==='before'?t('מה יעזור לכם לקראת הערב?','What would help before the evening?'):t('לאיזה רגע תרצו לחזור?','Which moment would you like to return to?')}</h3><p>${kind==='before'?t('אפשר להתחיל בתחנה אחת: קצת רקע, פנים מוכרות או דרך חדשה להקשיב. להכנת הביקור, עברו למדריך המעשי.','Start with one stop: a little context, familiar faces or another way to listen. For the visit itself, jump to the practical guide.'):t('בחרו שאלה שנשארה איתכם. אפשר לדלג בין התחנות בלי לסמן את כולן.','Choose a question that stayed with you. You can move between stops without checking them all off.')}</p><div role="group" aria-label="${t('קפיצה לתחנה במסלול','Jump to a stop in this journey')}">${d.stops.map((x,i)=>`<button data-jump="curtain-${kind}-${esc(x.id)}"><span>0${i+1}</span>${h(x.title)}</button>`).join('')}</div>${kind==='before'?`<button class="text-button" data-jump="before-practical">${t('זמן, מושבים, ילדים ונגישות','Time, seats, children and access')}${arrow}</button>`:''}</section>`}
const hugoStoryOpen=new Set();
function afterStoryHref(nextLang=lang,key='collection'){return `/${nextLang}/after/?focus=${encodeURIComponent('extra:'+key)}`}
function hugoStories(){const d=R.hugoExtras;if(!afterConsent||!spoiler||!d)return '';return `<section class="hugo-extras" id="hugo-extra-stories" aria-labelledby="hugo-extra-title" tabindex="-1"><div class="hugo-extras-heading"><span class="hugo-book-mark" aria-hidden="true">1862</span><div><div class="eyebrow">${t('עוד מהעולם של הוגו','MORE OF HUGO’S WORLD')}</div><h2 id="hugo-extra-title">${h(d.title)}</h2><p>${h(d.intro)}</p></div></div><nav class="hugo-extras-index" aria-label="${t('בחירת סיפור מהספר','Choose a story from the novel')}">${d.stories.map((x,i)=>`<button class="text-button" data-jump="extra-story-${esc(x.id)}"><span>${String(i+1).padStart(2,'0')}</span>${h(x.title)}</button>`).join('')}</nav><div class="hugo-extras-grid">${d.stories.map((x,i)=>`<article class="hugo-extra-card" id="extra-story-${esc(x.id)}" tabindex="-1"><div class="hugo-story-top"><span class="hugo-story-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow">${h(x.kicker)}</div><h3>${h(x.title)}</h3></div></div><p>${h(x.paragraphs[0])}</p><details data-hugo-story="${esc(x.id)}" ${hugoStoryOpen.has(x.id)?'open':''}><summary>${t('להמשיך את הסיפור','Continue the story')}</summary>${x.paragraphs.slice(1).map(p=>`<p>${h(p)}</p>`).join('')}<div class="hugo-story-sources"><b>${t('אצל הוגו, בפרקים האלה','Find it in Hugo’s chapters')}</b><div class="source-links">${x.references.map(r=>external(r.url,tr(r.label))).join('')}</div></div><div class="button-row">${link(x.related.routeKey,h(x.related.label),'text-link')}</div></details></article>`).join('')}</div><div class="hugo-extras-footer"><p>${t('רוצים לראות איך הסיפור משנה צורה בדרך לבמה?','Want to see how the story changes on its way to the stage?')}</p>${link('compare',t('מהספר למחזמר: הבחירות הגדולות','From novel to musical: the big choices'),'text-link')}</div></section>`}
function curtainContents(kind){const d=R.curtain[kind],selected=curtainChecked[kind];return `<div class="curtain-intro"><div class="curtain-door" aria-hidden="true"><span>${kind==='before'?'01':'02'}</span><div></div><b>${kind==='before'?t('לפני<br>המסך','BEFORE<br>THE CURTAIN'):t('אחרי<br>המסך','AFTER<br>THE CURTAIN')}</b></div><div><div class="eyebrow">${h(d.durationLabel)}</div><h2>${h(d.introTitle||d.title)}</h2><p>${h(d.intro)}</p><div class="curtain-progress-label"><span>${t('המסלול שלכם · אפשר לבחור רק תחנה אחת','Your journey · one stop is enough')}</span><b id="curtain-progress-text">${selected.length} / ${d.stops.length}</b></div><div class="curtain-progress"><div id="curtain-progress-fill" style="width:${selected.length/d.stops.length*100}%"></div></div><p class="small muted">${t('הסימונים זמניים בלשונית הזאת, ללא שמירה או שליחה.','Checkmarks are temporary in this tab, with no saving or uploading.')}</p></div></div>${curtainStopChooser(kind)}${kind==='after'?`<button class="hugo-stories-invitation" data-jump="hugo-extra-stories"><span>${t('עוד מהעולם של הוגו','MORE OF HUGO’S WORLD')}</span><b>${t('ארבעה סיפורים מעבר לשירים','Four stories beyond the songs')}</b>${arrow}</button>`:''}${kind==='before'?beforePrimer():''}<div class="curtain-stops">${d.stops.map((s,i)=>`<article class="curtain-stop" id="curtain-${kind}-${esc(s.id)}" tabindex="-1"><div class="curtain-stop-number"><span>${String(i+1).padStart(2,'0')}</span>${s.durationLabel?`<small>${h(s.durationLabel)}</small>`:''}</div><div class="curtain-stop-content"><h2>${h(s.title)}</h2><p>${h(s.body)}</p>${s.characterIntros?`<div class="safe-character-intros">${s.characterIntros.map(c=>`<article><h3>${h(c.name)}</h3><p>${h(c.body)}</p></article>`).join('')}</div>`:''}${s.prompt?`<div class="curtain-prompt"><b>${t('לקחת אתכם','TAKE THIS WITH YOU')}</b><p>${h(s.prompt)}</p></div>`:''}${s.extra?`<details class="curtain-extra"><summary>${h(s.extra.title)}</summary><p>${h(s.extra.body)}</p></details>`:''}<div class="curtain-links">${(s.links||[]).map(l=>`<div>${link(l.routeKey,h(l.label),'text-link')}${l.spoilerNotice?`<small>${h(l.spoilerNotice)}</small>`:''}</div>`).join('')}</div>${kind==='before'?`<p class="source-caution">${t('שימו לב: המקורות החיצוניים עלולים לחשוף את העלילה כולה.','External source pages may reveal the full plot.')}</p>`:''}${sources(s.sourceIds)}<label class="curtain-check"><input type="checkbox" data-curtain-check="${kind}:${esc(s.id)}" ${selected.includes(s.id)?'checked':''}>${t('לקחתי את זה איתי','I’m taking this with me')}</label></div></article>`).join('')}</div><p class="curtain-completion" id="curtain-completion" ${selected.length===d.stops.length?'':'hidden'}>${h(d.completion)}</p>${kind==='after'?hugoStories()+`<button class="btn secondary" data-action="after-hide">${t('סגירת מסלול הספוילרים','Close this spoiler journey')}</button>`:''}`}
function curtainPage(kind){const d=R.curtain?.[kind];if(!d)return top(t('לפני ואחרי המסך','Before and after the curtain'),'',t('המסך','THE CURTAIN'));const open=kind==='before'||afterConsent;return top(h(d.title),h(d.subtitle),kind==='before'?t('16 / לפני שהמסך עולה','16 / BEFORE THE CURTAIN'):t('17 / אחרי שהמסך יורד','17 / AFTER THE CURTAIN'))+`<div class="wrap section">${open?curtainContents(kind)+(kind==='before'?beforePractical():''):`<div class="gate curtain-gate"><span class="gate-icon" aria-hidden="true">Ⅱ</span><h2>${h(d.gate.title)}</h2><p>${h(d.gate.body)}</p><button class="btn" data-action="after-open">${h(d.gate.acceptLabel)}${arrow}</button><p class="small muted" style="margin-top:20px">${t('זהו אישור נפרד גם אם ספוילרים כבר פעילים במקום אחר באתר.','This is a separate choice, even if spoilers are enabled elsewhere on the site.')}</p></div>`}</div>`}
function directorDetail(){const d=R.curtain?.directorLab,s=d?.scenes?.[directorScene];if(!s)return '';const chosen=s.choices.find(c=>c.id===directorSelections[s.id]);return `<div class="director-scene"><div class="director-scene-intro"><span class="director-slate" aria-hidden="true">SCENE<br><b>0${directorScene+1}</b></span><div><h3>${h(s.title)}</h3><p>${h(s.setup)}</p></div></div><div class="director-choices" role="group" aria-label="${t('החלטת הבימוי שלך','Your directing choice')}">${s.choices.map((c,i)=>`<button data-director-choice="${esc(c.id)}" class="${chosen?.id===c.id?'active':''}" aria-pressed="${chosen?.id===c.id}"><span>${String.fromCharCode(65+i)}</span>${h(c.label)}</button>`).join('')}</div>${chosen?`<div class="director-consequence" role="status"><div><b>${t('מה הבחירה הזאת עשויה להדגיש','WHAT THIS CHOICE MIGHT EMPHASISE')}</b><p>${h(chosen.consequence)}</p></div><div><b>${t('ומה עלול ללכת לאיבוד','WHAT YOU MIGHT LOSE')}</b><p>${h(chosen.tradeoff)}</p></div></div>`:`<div class="director-empty">${t('בחרו גישה. נגלה מה היא מדגישה, ועל מה היא מוותרת. אין כאן תשובה נכונה אחת.','Choose an approach. See what it brings forward and what it gives up. There is no single correct answer.')}</div>`}${sources(s.sourceIds)}</div>`}
function directorLab(){const d=R.curtain?.directorLab;if(!d)return '';return `<section class="director-lab" id="director-lab" tabindex="-1"><div class="section-head"><div><div class="eyebrow">${t('מעבדת בימוי · פרשנות מקורית','DIRECTOR LAB · ORIGINAL INTERPRETATION')}</div><h2>${h(d.title)}</h2></div></div>${!directorConsent?`<div class="director-gate"><h3>${h(d.gate.title)}</h3><p>${h(d.gate.body)}</p><button class="btn" data-action="director-open">${h(d.gate.acceptLabel||{he:'אפשר לפתוח את המעבדה',en:'Open the lab'})}</button></div>`:`<p class="director-intro">${h(d.intro)}</p><div class="director-tabs" role="group" aria-label="${t('בחירת סצנה','Choose a scene')}">${d.scenes.map((s,i)=>`<button data-director-scene="${i}" class="${directorScene===i?'active':''}" aria-pressed="${directorScene===i}">${h(s.title)}</button>`).join('')}</div><div id="director-detail">${directorDetail()}</div><p class="small muted">${t('הבחירות אינן נשמרות.','Choices are not saved.')}</p><button class="text-button" data-action="director-hide">${t('לסגור את המעבדה','Close the lab')}</button>`}</section>`}

function hugoClusters(){const H=R.hugo;return `<div class="hugo-clusters">${[{ids:['many-voices','changing-mind','island'],title:t('חיים שלא נשארו במקום','A life that kept changing'),intro:t('היצירה, העמדות והגלות, לפני שמתקרבים אל כתב היד.','The writing, convictions and exile, before we turn to the manuscript.')},{ids:['making','reading','arrival'],title:t('מכתב היד אל הקוראים','From manuscript to readers'),intro:t('שתי תקופות עבודה, רומן רחב יריעה, וקהל שלא קרא אותו בקול אחד.','Two periods of work, a sprawling novel, and readers who did not all respond alike.')},{ids:['pens'],title:t('עקבות של עבודה ביד','Traces of work by hand'),intro:t('שישה כלי כתיבה מחזירים את המבט מן הספר הגדול אל המלאכה היומיומית.','Six writing tools bring the immense book back to the daily work of making it.')}].map((group,gi)=>`<section class="hugo-cluster ${gi===2?'hugo-object':''}"><div class="hugo-cluster-heading"><span>0${gi+1}</span><div><h2>${group.title}</h2><p>${group.intro}</p></div></div><div class="hugo-sections">${group.ids.map(id=>{const a=H.sections.find(x=>x.id===id),i=H.sections.indexOf(a);return `<article data-hugo-section="${id}"><span class="hugo-section-no" aria-hidden="true">${gi===2?'6':'0'+(i+1)}</span><div><h3>${h(a.title)}</h3><p>${h(a.body)}</p>${sources(a.sourceIds)}</div></article>`}).join('')}</div></section>`).join('')}</div>`}
function hugoPage(){const H=R.hugo;if(!H)return top(t('הוגו והספר','Hugo & the novel'),'',t('15 / הוגו והספר','15 / HUGO & THE NOVEL'));return top(h(H.title),h(H.subtitle),t('15 / הוגו והספר','15 / HUGO & THE NOVEL'))+`<div class="wrap section"><div class="hugo-introduction"><div class="hugo-wordmark" aria-hidden="true"><span>VICTOR</span><b>H</b><strong>HUGO</strong><small>LES MISÉRABLES · 1862</small><div></div></div><div><div class="eyebrow">${t('להכיר, בלי לגלות את העלילה','MEET THE BOOK, WITHOUT THE PLOT')}</div><h2>${t('ספר ששואל<br>איך רואים אדם.','A book that asks<br>how we see a person.')}</h2><p>${h(H.lead)}</p><div class="button-row">${link('novel',t('קראתם ורוצים להיזכר? · ספוילרים באישור','Read it and want a refresh? · opt-in spoilers'),'btn secondary')}</div></div></div>${hugoClusters()}<section class="hugo-dates"><div class="section-head"><div><div class="eyebrow">${t('ספרים נכתבים בתוך חיים','BOOKS ARE WRITTEN INSIDE LIVES')}</div><h2>${t('כמה תאריכים.<br>דרך ארוכה ל־1862.','A few dates.<br>A long road to 1862.')}</h2></div></div><div class="hugo-timeline">${H.timeline.map(e=>`<article><span>${esc(e.year)}</span><div><h3>${h(e.title)}</h3><p>${h(e.body)}</p>${sources(e.sourceIds)}</div></article>`).join('')}</div></section><section class="hugo-themes"><div class="eyebrow">${t('השאלות לא התיישנו','THE QUESTIONS DIDN’T EXPIRE')}</div><h2>${t('מה לוקחים מהספר, עוד לפני שקוראים?','What can you take in, before you even read?')}</h2><div>${H.themes.map(x=>`<article><h3>${h(x.title)}</h3><p>${h(x.question)}</p>${link('ideas',t('לפתוח את הדיון','Open the discussion'),'text-link')}</article>`).join('')}</div></section><div class="note">${t('העמוד הזה נשאר ברקע ובסופר. תקציר הספר המלא, הקשרים בין הדמויות והסוף נמצאים במסלולים נפרדים, עם אזהרות ספוילרים. הטקסטים כאן מקוריים; תרגומים ועיבודים מודרניים הם יצירות בעלות זכויות נפרדות.','This page stays with context and the author. The full recap, character relationships and ending have their own routes and spoiler warnings. This guide uses original writing; modern translations and adaptations have separate rights.')}</div></div>`}

let novelConsent=getStored('barricade-novel-consent',true)==='on';
let novelPart='all';
function novelEvents(){return R.novel.milestones.filter(m=>novelPart==='all'||m.partIds.includes(novelPart))}
function novelPartName(p){return tr(p.title).split(' · ').slice(1).join(' · ')}
function novelPartLabel(index){return t('חלק '+['א׳','ב׳','ג׳','ד׳','ה׳'][index],'PART '+['I','II','III','IV','V'][index])}
function novelSelection(){const N=R.novel,events=novelEvents(),part=N.parts.find(p=>p.id===novelPart);return `<section class="novel-selection" aria-labelledby="novel-selection-heading"><div class="novel-selection-head"><div><div class="eyebrow">${t('לפי סדר האירועים, גם כשמסננים','EVENT ORDER, EVEN WHEN FILTERED')}</div><h2 id="novel-selection-heading">${part?`${novelPartLabel(N.parts.indexOf(part))}: ${esc(novelPartName(part))}`:t('כל ארבע־עשרה התחנות','All fourteen milestones')}</h2></div>${part?`<button class="btn secondary" data-novel-part="all">${t('חזרה לכל התחנות','Show all milestones')}</button>`:''}</div><p id="novel-result-count" aria-live="polite">${t('מוצגות '+events.length+' מתוך '+N.milestones.length+' תחנות.','Showing '+events.length+' of '+N.milestones.length+' milestones.')}</p>${part?`<p class="novel-part-overview">${h(part.overview)}</p>${part.sourceUrl?`<div class="source-links">${external(part.sourceUrl,t('החלק הזה ברומן','This part in the novel'))}</div>`:''}${part.id==='p5'?`<p class="novel-filter-example">${t('למה תחילת חייו של ולז׳אן לא כאן? כי “ז׳אן ולז׳אן” הוא שמו של חלק ה׳, ולא מסנן דמויות. גניבת הלחם והמפגש עם הבישוף מסופרים בחלק א׳, “פנטין”.','Why isn’t Valjean’s early life here? “Jean Valjean” is the title of Part V, not a character filter. The bread theft and meeting with the bishop are told in Part I, “Fantine”.')}</p>`:''}`:`<p class="novel-parts-invitation">${t('רוצים להיזכר במה עוסק כל חלק? פתחו כותרת. כדי לצמצם את ציר הזמן לחלק מסוים, השתמשו בכפתורי הסינון שמעל.','Want a reminder of what each part covers? Open a heading. To narrow the timeline to a part, use the filter buttons above.')}</p><div class="novel-parts-overviews">${N.parts.map((p,i)=>`<details><summary><span>${novelPartLabel(i)}</span>${esc(novelPartName(p))}</summary><p>${h(p.overview)}</p>${p.sourceUrl?`<div class="source-links">${external(p.sourceUrl,t('למקור ברומן','Read this part in the novel'))}</div>`:''}</details>`).join('')}</div>`}</section>`}
function novelTimeline(){const N=R.novel;const events=novelEvents();return `${novelSelection()}<div class="novel-timeline">${events.length?events.map(m=>`<article class="novel-event" data-novel-event="${esc(m.id)}"><div class="novel-date"><span>${h(m.dateLabel)}</span><b>${String(N.milestones.indexOf(m)+1).padStart(2,'0')}</b></div><div class="novel-event-card"><div class="novel-part-tags">${m.partIds.map(id=>{const p=N.parts.find(p=>p.id===id);return `<span>${novelPartLabel(N.parts.indexOf(p))} · ${esc(novelPartName(p))}</span>`}).join('')}</div><h2>${h(m.title)}</h2><p>${h(m.summary)}</p>${m.remember?`<p class="novel-remember"><b>${t('מה לזכור מכאן?','WHAT TO CARRY FORWARD')}</b>${h(m.remember)}</p>`:''}<details class="novel-depth"><summary>${t('רגע, מה בדיוק קרה שם?','Wait, what exactly happened there?')}</summary>${m.details.map(d=>`<p>${h(d)}</p>`).join('')}${m.characterIds?.length?`<div class="button-row">${link('characters',t('לחבר מחדש את הדמויות','Reconnect the characters'),'text-link')}</div>`:''}</details><div class="source-links">${m.references.map(r=>external(r.url,tr(r.label))).join('')}</div></div></article>`).join(''):`<div class="note">${t('אין תחנות תחת הבחירה הזאת. אפשר לחזור למסלול המלא.','No milestones match this choice. Return to the full journey.')}<button class="text-button" data-novel-part="all">${t('הצגת הכול','Show all')}</button></div>`}</div>`}
function novelEditionNote(){const N=R.novel;return `<details class="novel-edition"><summary>${t('מאיזו מהדורה קוראים כאן?','Which edition are we reading?')}</summary><p>${t('התקציר נכתב למדריך הזה. קישורי הפרקים מאפשרים לבדוק את האירועים בטקסט שעליו הוא מבוסס.','This recap was written for the guide. The chapter links let you check its events against the text used here.')}</p><p>${h(N.sourceNote)}</p><p class="source-caution">${t('הקישורים פותחים טקסט מלא ועשויים לחשוף גם את סוף הרומן.','These links open complete texts and may reveal the novel’s ending.')}</p><div class="source-links">${N.primarySources.map(x=>external(x.url,tr(x.label||x.title))).join('')}</div></details>`}
function novelContents(){const N=R.novel;return `<div class="novel-memory-head"><div class="novel-volume-mark" aria-hidden="true"><span>I</span><span>II</span><span>III</span><span>IV</span><span>V</span></div><div><div class="eyebrow">${t('הרומן המלא · רענון זיכרון','THE COMPLETE NOVEL · A MEMORY REFRESH')}</div><h2>${t('החלוקה של הוגו.<br>המסלול שלכם.','Hugo’s structure.<br>Your way through.')}</h2><p>${h(N.chronologyNote)}</p></div></div><div class="spoiler-banner"><span>${t('ספוילרים מלאים פתוחים: זה כולל את סופו של הרומן.','Full novel spoilers are open, including the ending.')}</span><button class="text-button" data-action="novel-hide">${t('לסגור את הספר','Close the book')}</button></div><section class="novel-two-orders"><article><strong>5</strong><div><h3>${t('חלקים מקוריים של הוגו','Hugo’s five original parts')}</h3><p>${t('פנטין, קוזט, מריוס, האידיליה והאפוס, וז׳אן ולז׳אן. אלה שמות חלקים ברומן; כל אחד מהם כולל גם דמויות אחרות. הם אינם חמישה מסלולי דמויות.','Fantine, Cosette, Marius, the Idyll and the Epic, and Jean Valjean. These are the novel’s part titles; each includes other characters too. They are not five character journeys.')}</p></div></article><article><strong>14</strong><div><h3>${t('תחנות זיכרון שבחרנו למדריך','Milestones selected for this guide')}</h3><p>${t('המספור כאן הוא שלנו, לפי סדר האירועים בחיי הדמויות. אלה אינם פרקי הספר המקוריים. תגית החלק בכל תחנה מציינת היכן הוגו מספר עליה, וקישור המקור מפנה לפרק המתאים.','Our numbering follows events in the characters’ lives. These are not the novel’s original chapters. Each part tag tells you where Hugo recounts an event, and the source link points to the relevant chapter.')}</p></div></article></section>${novelEditionNote()}<section aria-labelledby="novel-filter-title"><h2 id="novel-filter-title" class="novel-filter-title">${t('באיזה חלק של הספר רוצים להתמקד?','Which part of the book would you like to explore?')}</h2><p class="novel-filter-note">${t('הסינון הוא לפי חלקי הרומן, לא לפי הדמות ששמה מופיע בכותרת. לדוגמה: ולז׳אן מופיע כבר בחלק א׳, ששמו “פנטין”.','Filter by the novel’s parts, not by the character named in a title. For example, Valjean appears in Part I, which is called “Fantine”.')}</p><div class="novel-filters" role="group" aria-label="${t('סינון לפי חמשת החלקים המקוריים של הוגו','Filter by Hugo’s five original parts')}"><button data-novel-part="all" class="${novelPart==='all'?'active':''}" aria-pressed="${novelPart==='all'}">${t('כל 14 התחנות','All 14 milestones')}</button>${N.parts.map((p,i)=>`<button data-novel-part="${esc(p.id)}" class="${novelPart===p.id?'active':''}" aria-pressed="${novelPart===p.id}"><span>${novelPartLabel(i)}</span>${esc(novelPartName(p))}</button>`).join('')}</div><p class="small muted novel-filter-note">${t('הסדר נשאר כרונולוגי. תחנה המחברת אירועים מכמה חלקים מופיעה תחת כל אחד מהם; תגיות החלקים מבהירות זאת.','Events stay chronological. A milestone combining events from several parts appears under each of them, as its part tags indicate.')}</p></section><div id="novel-timeline-container">${novelTimeline()}</div><div class="novel-closing"><h2>${t('זוכרים עכשיו?<br>הבמה עושה בחירות אחרות.','Remember now?<br>The stage makes different choices.')}</h2><div class="button-row">${link('compare',t('מה השתנה בדרך לבמה?','What changed on the way to the stage?'))}${link('characters',t('אל מפת הקשרים','Into the relationship map'),'btn secondary')}${link('quiz',t('לבדוק מה נשאר בזיכרון','See what stayed with you'),'btn secondary')}<a class="btn secondary" data-hugo-entry href="${afterStoryHref()}">${t('ארבעה סיפורים מעבר לשירים','Four stories beyond the songs')}</a></div></div>`}
function novelPage(){const N=R.novel;if(!N)return top(t('הספר המקורי','The original novel'),'',t('14 / הספר המקורי','14 / THE ORIGINAL NOVEL'));return top(h(N.title),h(N.subtitle),t('14 / הספר המקורי','14 / THE ORIGINAL NOVEL'))+`<div class="wrap section"><div id="novel-room">${novelConsent?novelContents():`<div class="novel-gate"><div class="closed-book" aria-hidden="true"><span>VICTOR<br>HUGO</span><b>LES<br>MISÉRABLES</b><small>1862</small></div><div><div class="eyebrow">${t('לפני שפותחים את הספר','BEFORE YOU OPEN THE BOOK')}</div><h2>${h(N.spoilerWarning.title)}</h2><p>${h(N.spoilerWarning.body)}</p><p class="novel-gate-note">${t('העלילה אינה נמצאת בדף הנוכחי לפני האישור, גם אם מצב הספוילרים הכללי כבר פעיל. המקורות החיצוניים עשויים לחשוף הכול.','The plot is absent from this page before consent, even if general spoiler mode is already on. External source pages may reveal everything.')}</p><button class="btn" data-action="novel-open">${h(N.spoilerWarning.consentLabel)}${arrow}</button><div class="button-row">${link('resources',t('בינתיים, מקומות לקרוא בהם','For now, places to read'),'text-link')}</div></div></div>`}</div></div>`}

let showIndex=0;
let showAct='all';
let featuredSong='on-my-own';
const songPerformanceChoices={};
let humorCategory='all';
function addedMediaCredits(item){if(item.existingCredits)return `<details class="added-media-credits"><summary>${t('מי מופיע כאן? קרדיטים ורקע','Who appears here? Credits and background')}</summary>${performerCredits(item.id,true)}</details>`;return `<details class="added-media-credits"><summary>${t('מי מופיע כאן? קרדיטים ורקע','Who appears here? Credits and background')}</summary>${item.creditLine?`<p class="added-credit-line">${h(item.creditLine)}</p>`:''}${item.dateNote?`<p class="media-date-note">${h(item.dateNote)}</p>`:''}${(item.credits||[]).map(p=>`<div class="added-performer"><h4>${h(p.name)}</h4><b>${h(p.role)}</b><p>${h(p.bio)}</p>${p.url?external(p.url,t('על המשתתף או ההפקה','Performer or production profile')):''}</div>`).join('')}${sources(item.sourceIds)}</details>`}
function addedMedia(item){const sourceUrl=item.externalUrl||'https://www.youtube.com/watch?v='+item.id;const registered=videos.find(v=>v.id===item.id);return `<div class="added-media" data-added-media="${esc(item.id)}"><div class="added-media-heading">${item.provider?`<span class="media-provider">${h(item.provider)} · ${t('צפייה באתר המקור','WATCH AT SOURCE')}</span>`:''}<span class="media-language ${item.languageCode==='he'?'hebrew':''}">${h(item.language)}</span><h4>${h(item.title)}</h4><p>${h(item.label)}</p>${videoReach(item.id)}</div><p class="added-media-context">${h(item.context)}</p>${item.notice?`<p class="added-media-notice">${h(item.notice)}</p>`:''}${item.embeddable&&!item.externalUrl&&registered?video(registered):`<div class="link-only-media">${external(sourceUrl,item.externalUrl?t('לצפייה באתר המקור','Watch on the original site'):t('צפייה אצל המפרסם המקורי','Watch with the original publisher'))}</div>`}${item.additionalLinks?`<div class="source-links">${item.additionalLinks.map(l=>external(l.url,tr(l.label))).join('')}</div>`:''}${addedMediaCredits(item)}</div>`}
function songMedia(songId){return gallerySongLinks(songId)}
function humorCards(){const items=(R.humor?.items||[]).filter(x=>humorCategory==='all'||x.category===humorCategory);return items.map(item=>`<article class="humor-card"><div class="humor-editorial"><div class="humor-card-number" aria-hidden="true">${String(R.humor.items.indexOf(item)+1).padStart(2,'0')}</div><span class="eyebrow">${h(R.humor.categories.find(c=>c.id===item.category)?.label)}</span><h2>${h(item.title)}</h2><p>${h(item.hook)}</p><div class="humor-question"><b>${t('אחרי החיוך, שימו לב','AFTER THE LAUGH, NOTICE')}</b><p>${h(item.question)}</p></div>${item.relatedSong?`<button class="text-link" data-listen-song="${esc(item.relatedSong)}">${t('לחזור לשיר במדריך','Return to the song guide')}${arrow}</button>`:''}</div><div>${addedMedia(item)}</div></article>`).join('')}
function humorCount(n){return n+' '+t(n===1?'קטע מוצג':'קטעים מוצגים',n===1?'clip shown':'clips shown')}
function humorPage(){const H=R.humor;return top(h(H.title),h(H.intro),t('22 / פאנץ׳ אחר','22 / A DIFFERENT PUNCHLINE'))+`<div class="wrap section humor-room"><div class="humor-curator-note"><span aria-hidden="true">↻</span><p>${h(H.note)}</p></div><div class="humor-filters filter-row" role="group" aria-label="${t('סוגי קומדיה','Comedy formats')}">${[{id:'all',label:{he:'כל הקריצות',en:'All the angles'}},...H.categories].map(c=>`<button class="filter ${humorCategory===c.id?'active':''}" data-humor-category="${esc(c.id)}" aria-pressed="${humorCategory===c.id}">${h(c.label)}</button>`).join('')}</div><p class="small muted" id="humor-count" role="status">${humorCount(H.items.filter(x=>humorCategory==='all'||x.category===humorCategory).length)}</p><div id="humor-cards">${humorCards()}</div><div class="humor-closing"><h2>${t('מה נשאר כשמשנים את ההקשר?','What remains when the context changes?')}</h2><p>${t('בחרו שיר אחד מהקטעים וחזרו לביצוע הרציני שלו. האם אחרי הפרודיה אתם מבחינים אחרת בעוצמה, ברגש או בדרך שבה הקולות מצטרפים?','Choose a song from a clip and return to a serious performance. After the parody, do you notice its scale, emotion or gathering voices differently?')}</p>${link('musical',t('אל השירים באור הזרקורים','Into the song spotlight'))}</div></div>`}
function featuredSongBadge(id){return (R.musical.spotlight?.songs||[]).some(x=>x.id===id)?`<span class="featured-song-badge">${t('באור הזרקורים','IN THE SPOTLIGHT')}</span>`:''}
function spotlightDetail(){const F=R.musical.spotlight;if(!F)return '';const s=F.songs.find(x=>x.id===featuredSong)||F.songs[0];return `<article class="spotlight-detail" aria-labelledby="spotlight-title"><div class="spotlight-detail-head"><span class="spotlight-symbol" aria-hidden="true">${s.symbol||'♫'}</span><div><div class="eyebrow">${h(s.hook)}</div><h3 id="spotlight-title" dir="ltr">${esc(s.title)}</h3></div></div><div class="spotlight-background"><p>${h(s.background)}</p>${sources(s.sourceIds)}</div>${songReading(s.id,'spotlight')}<div class="spotlight-question"><b>${t('קחו את השאלה הזאת להאזנה','TAKE THIS QUESTION INTO YOUR LISTENING')}</b><p>${h(s.question)}</p></div>${spoiler?`<div class="spotlight-context"><b>${t('בתוך המחזמר','INSIDE THE MUSICAL')}</b><p>${h(s.plot)}</p>${s.connection?`<p>${h(s.connection)}</p>`:''}${sources(s.plotSourceIds)}</div>`:`<p class="spotlight-spoiler-note">${t('המיקום בעלילה והקשרים לסצנות אחרות נשארים מאחורי אזהרת הספוילרים.','The plot context and links between scenes stay behind the spoiler warning.')}</p>`}<button class="btn" data-song-journey="${esc(s.id)}">${spoiler?t('לתחנה של השיר במסע','Go to this song’s story stop'):t('אל השיר במסע · עם אזהרת ספוילרים','Find its story stop · spoiler warning')}${arrow}</button>${songMedia(s.id)}</article>`}
function musicalSpotlight(){const F=R.musical.spotlight;if(!F)return '';return `<section class="musical-section musical-spotlight" id="musical-spotlight"><div class="section-head"><div><div class="eyebrow">${t('שירים מוכרים · הקשבה קצת אחרת','FAMILIAR SONGS · A FRESH WAY TO LISTEN')}</div><h2>${h(F.title)}</h2></div><p>${h(F.intro)}</p></div><div class="spotlight-layout"><div class="spotlight-selector" role="group" aria-label="${t('בחירת שיר באור הזרקורים','Choose a featured song')}">${F.songs.map((s,i)=>`<button data-featured-song="${esc(s.id)}" aria-controls="featured-song-detail" aria-pressed="${featuredSong===s.id}" class="${featuredSong===s.id?'active':''}"><span class="spotlight-number" aria-hidden="true">0${i+1}</span><span><b dir="ltr">${esc(s.title)}</b><small>${h(s.hook)}</small></span><span class="spotlight-select-arrow" aria-hidden="true">${arrow}</span></button>`).join('')}</div><div id="featured-song-detail">${spotlightDetail()}</div></div><p class="small muted spotlight-edition-note">${h(F.context)}</p></section>`}
function musicalCreationDepth(){const C=R.musical.creationStory;if(!C)return '';return `<div class="creation-reception"><div class="creation-reception-heading"><span class="eyebrow">${t('מאחורי סיפור ההצלחה','BEHIND THE SUCCESS STORY')}</span><h3>${h(C.title)}</h3><p>${h(C.intro)}</p></div><div class="reception-contrasts">${C.panels.map(p=>`<article><div class="reception-date">${h(p.date)}</div><h4>${h(p.title)}</h4><p>${h(p.body)}</p>${sources(p.sourceIds)}</article>`).join('')}</div><p class="reception-takeaway">${h(C.takeaway)}</p></div><details class="composition-notebook"><summary>${t('מה עיצב את המחזמר? לפתוח את פנקס היצירה','What shaped the show? Open the creative notebook')}</summary><div>${C.craft.map(c=>`<article id="craft-${esc(c.id)}" data-craft-id="${esc(c.id)}" tabindex="-1"><h3>${h(c.title)}</h3><p>${h(c.body)}</p>${sources(c.sourceIds)}</article>`).join('')}</div></details>`}
function showStops(){const entries=R.musical?.songentries||[];const list=[];entries.forEach(x=>{list.push(x);if(x.id===R.musical.reference.intervalAfterId||x.id===R.musical.intervalAfterId)list.push({id:'interval',act:1,interval:true,title:{he:'הפסקה. תנו להדהוד רגע.',en:'Interval. Let it resonate.'},scene:{he:'בין מערכה א׳ למערכה ב׳',en:'BETWEEN ACT I AND ACT II'}})});return list}
function filteredShowStops(){return showStops().filter(s=>showAct==='all'||String(s.act)===showAct)}
function currentShowStop(){const stops=filteredShowStops();if(showIndex>=stops.length)showIndex=stops.length-1;if(showIndex<0)showIndex=0;return stops[showIndex]}
function showActLabel(s){return s?.interval?t('הפסקה · בין המערכות','Interval · between the acts'):s?.act===2?t('מערכה ב׳','Act II'):t('מערכה א׳','Act I')}
function showMoveLabel(direction,compact=false){const stops=filteredShowStops(),index=showIndex+(direction==='next'?1:-1),next=stops[index],current=stops[showIndex];if(!next)return direction==='next'?(compact?t('הבאה','Next'):showAct==='1'?t('סוף מערכה א׳','End of Act I'):t('סוף המסע','Journey complete')):t('הקודמת','Previous');if(next.interval)return direction==='next'?t('אל ההפסקה','To the interval'):t('חזרה להפסקה','Back to the interval');if(current?.interval)return direction==='next'?t('מתחילים מערכה ב׳','Begin Act II'):t('לסיום מערכה א׳','Act I’s finale');return direction==='next'?(compact?t('הבאה','Next'):t('לתחנה הבאה','Next stop')):(compact?t('הקודמת','Previous'):t('לתחנה הקודמת','Previous stop'))}
function showActRibbon(){const s=currentShowStop(),phase=s.interval?'interval':String(s.act);return `<ol class="show-act-ribbon" aria-label="${t('המערכות וההפסקה','Acts and interval')}">${[['1',t('מערכה א׳','Act I')],['interval',t('הפסקה','Interval')],['2',t('מערכה ב׳','Act II')]].map(([id,label])=>`<li class="${phase===id?'current':''}" ${phase===id?'aria-current="step"':''}><span aria-hidden="true">${id==='interval'?'Ⅱ':id==='1'?'I':'II'}</span>${label}</li>`).join('')}</ol>`}
function showActOptions(stops){let group=null;return stops.map((x,i)=>{const phase=x.interval?'interval':String(x.act),start=phase!==group,close=start&&group!==null?'</optgroup>':'';group=phase;return close+(start?`<optgroup label="${h(showActLabel(x))}">`:'')+`<option value="${i}" ${i===showIndex?'selected':''}>${String(i+1).padStart(2,'0')} · ${featuredSongBadge(x.id)?'★ ':''}${h(x.title)}</option>`}).join('')+(group!==null?'</optgroup>':'')}
function showBoundary(s){const entries=R.musical.songentries,firstSecond=entries.find(x=>x.act===2)?.id,lastFirst=entries.filter(x=>x.act===1).at(-1)?.id;return s.id===lastFirst?`<p class="show-boundary" data-act-boundary="end-one">${t('סיום מערכה א׳ · אחריו ההפסקה','Act I finale · the interval follows')}</p>`:s.id===firstSecond?`<p class="show-boundary" data-act-boundary="begin-two">${t('מערכה ב׳ מתחילה כאן','Act II begins here')}</p>`:''}
function showSlide(){const s=currentShowStop();if(!s)return '';if(s.interval)return `<article class="show-slide interval-slide"><div class="interval-mark" aria-hidden="true">Ⅱ</div><div><div class="eyebrow">${h(s.scene)}</div><h2 id="show-current-title">${h(s.title)}</h2><p>${t('מערכה א׳ מסתיימת עם One Day More. כל הדמויות פונות אל אותו מחר, מסיבות שונות. רגע לנשום, לפני שההבטחות פוגשות את הרחוב.','Act I ends with One Day More. The characters face the same tomorrow for very different reasons. Take a breath before promises meet the street.')}</p><div class="interval-fact">${h(R.musical.reference.runtime.label)}</div><p class="small">${h(R.musical.reference.runtime.scope)}</p><button class="btn" data-show-open-act="2">${t('עולים למערכה ב׳','Into Act II')}${arrow}</button></div></article>`;const cast=(s.characters||[]).map(v=>typeof v==='object'?tr(v):(R.characters.find(c=>c.id===v)?tr(R.characters.find(c=>c.id===v).name):v)).join(' · ');const clip=s.id?.toLowerCase().includes('stars')?'_6nTyXcmgLc':s.title?.en==='Bring Him Home'?'JMGMSgPHJoI':s.title?.en==='One Day More'?'6yRGaY4UU04':null;return `<article class="show-slide"><div class="show-art" aria-hidden="true"><span class="show-act-label">${t('מערכה','ACT')} ${s.act===1?'I':'II'}</span><span class="show-stop-number">${String(showStops().findIndex(x=>x.id===s.id)+1).padStart(2,'0')}</span><svg viewBox="0 0 150 170"><path d="M32 164V10M15 164h120" stroke="currentColor" stroke-width="3" fill="none"/><path d="M34 18c40-25 42 26 100 0v72c-53 27-65-26-100 0" fill="#ed2939"/></svg><span>LES MISÉRABLES<br>${t('בעקבות המוזיקה','FOLLOW THE MUSIC')}</span></div><div class="show-slide-copy">${showBoundary(s)}${featuredSongBadge(s.id)}<div class="eyebrow">${h(s.scene)}</div><h2 id="show-current-title" dir="auto">${h(s.title)}</h2>${lang==='he'?`<div class="show-original-title" dir="ltr">${esc(s.title.en)}</div>`:''}${cast?`<div class="show-voices">${esc(cast)}</div>`:''}<p class="show-summary">${h(s.summary)}</p>${songReading(s.id)}<div class="show-mood"><b>${t('הדופק של הרגע','THE FEEL OF THE MOMENT')}</b><span>${h(s.mood)}</span></div><div class="show-listen"><b>${t('שאלה להקשבה','A LISTENING QUESTION')}</b><p>${h(s.question)}</p></div>${(R.gallery?.groups||[]).some(v=>v.songId===s.id)?`<button class="text-link" data-listen-song="${esc(s.id)}">${t('לשמוע ביצוע של השיר כאן','Hear a performance of this song here')}${arrow}</button>`:clip?`<a class="text-link" href="${url('listening')}">${t('לפגוש ביצוע באוסף הביצועים','Find a performance in the performance collection')}${arrow}</a>`:''}${sources(s.sourceIds)}</div></article>`}
function showJourney(){const stops=filteredShowStops(),s=currentShowStop();return `<div class="show-journey" id="show-journey"><div class="show-control-head"><div><div class="eyebrow">${t('משיר לשיר, מסצנה לסצנה','SONG TO SONG, SCENE TO SCENE')}</div><h2>${t('המחזמר, בתנועה.','The musical, in motion.')}</h2></div><div class="filter-row" role="group" aria-label="${t('בחירת מערכה','Choose an act')}">${[['all',t('כל המסע','The whole journey')],['1',t('מערכה א׳','Act I')],['2',t('מערכה ב׳','Act II')]].map(([id,l])=>`<button class="filter ${showAct===id?'active':''}" data-show-act="${id}" aria-pressed="${showAct===id}">${l}</button>`).join('')}</div></div><div class="show-reference"><b>${h(R.musical.reference.version||R.musical.reference.title)}</b><p>${t('תחנות דרמטיות בסדר העלילה, עם קטעי מעבר ורפריזות. הסדר עשוי להשתנות בין הפקות.','Dramatic stops in story order, with transitions and reprises. The order may vary between productions.')}</p></div><div class="show-navigator"><button data-show-move="prev" aria-label="${showMoveLabel('prev')}" ${showIndex===0?'disabled':''}>${showMoveLabel('prev',true)}</button><label><span>${t('מעבר ישיר לתחנה','Jump to a stop')}</span><select data-show-select aria-label="${t('מעבר ישיר לתחנה','Jump to a stop')}">${showActOptions(stops)}</select></label><button data-show-move="next" aria-label="${showMoveLabel('next')}" ${showIndex===stops.length-1?'disabled':''}>${showMoveLabel('next',true)}</button></div><div id="show-act-ribbon">${showActRibbon()}</div><div class="show-range-wrap"><label for="show-range">${t('גררו לאורך המסע או השתמשו במקשי החצים','Move through the journey or use the arrow keys')}</label><input id="show-range" data-show-range type="range" min="0" max="${stops.length-1}" step="1" value="${showIndex}" aria-valuetext="${esc(showActLabel(s)+' · '+tr(s?.title))}" dir="ltr"><span id="show-index">${showIndex+1} / ${stops.length}</span></div><div id="show-slide">${showSlide()}</div><div class="show-bottom-nav"><button class="btn secondary" data-show-move="prev" ${showIndex===0?'disabled':''}>${showMoveLabel('prev')}</button><span>${t('בלי ניגון אוטומטי. אתם קובעים את הקצב.','No autoplay. You set the pace.')}</span><button class="btn" data-show-move="next" ${showIndex===stops.length-1?'disabled':''}>${showMoveLabel('next')}</button></div><details class="show-outline"><summary>${t('לראות את כל התחנות במבט אחד','See every stop at a glance')}</summary><div>${stops.map((x,i)=>`${i===0||x.interval||stops[i-1]?.act!==x.act?`<h3 class="show-outline-act">${showActLabel(x)}</h3>`:''}<button data-show-stop="${i}" aria-current="${showIndex===i?'step':'false'}" class="${showIndex===i?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><b>${h(x.title)}</b><small>${x.interval?t('הפסקה','INTERVAL'):x.act===1?t('מערכה א׳','ACT I'):t('מערכה ב׳','ACT II')}</small></button>`).join('')}</div></details></div>`}
function updateShow(){clearReadingSearchTarget();const stops=filteredShowStops(),s=currentShowStop();A.track('content_open',{content_type:'musical_stop',content_id:s.id});document.getElementById('show-slide').innerHTML=showSlide();mountPlayers();document.getElementById('show-index').textContent=`${showIndex+1} / ${stops.length}`;const range=document.getElementById('show-range');range.value=showIndex;range.setAttribute('aria-valuetext',showActLabel(s)+' · '+tr(s.title));document.getElementById('show-act-ribbon').innerHTML=showActRibbon();document.querySelector('[data-show-select]').value=showIndex;document.querySelectorAll('[data-show-move]').forEach(b=>{const direction=b.dataset.showMove;b.disabled=direction==='prev'?showIndex===0:showIndex===stops.length-1;b.textContent=showMoveLabel(direction,!!b.closest?.('.show-navigator'));b.setAttribute('aria-label',showMoveLabel(direction))});document.querySelectorAll('[data-show-stop]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.showStop)===showIndex);b.setAttribute('aria-current',Number(b.dataset.showStop)===showIndex?'step':'false')});announce(showActLabel(s)+' · '+tr(s.title))}
function musicFormPrimer(){const P=R.musical.listeningPrimer;return `<section class="music-form-primer"><div class="eyebrow">${t('להקשיב לצורה, לא רק לשיר','LISTEN TO THE FORM, NOT ONLY THE SONG')}</div><h2>${h(P.title)}</h2><p>${h(P.intro)}</p><dl>${P.rows.map((r,i)=>`<div><dt><span>0${i+1}</span>${h(r.title)}</dt><dd><p>${h(r.body)}</p><p class="form-question">${h(r.question)}</p></dd></div>`).join('')}</dl><p class="small muted">${h(P.sourceNote)}</p>${sources([...new Set(P.rows.flatMap(r=>r.sourceIds))])}</section>`}
function officialLondonFacts(){const F=R.officialLondon;if(!F)return '';return `<aside class="london-snapshot"><div class="london-snapshot-head"><span class="eyebrow">${t('ההפקה הרשמית · תמונת מצב','THE OFFICIAL PRODUCTION · A SNAPSHOT')}</span><h3>${h(F.title)}</h3><p>${h(F.intro)}</p></div><div class="london-reach">${F.factcards.slice(0,4).map(c=>`<div><strong>${h(c.value)}</strong><span>${h(c.title)}</span></div>`).join('')}</div><div class="london-now">${F.factcards.slice(4).map(c=>`<div><span>${h(c.title)}</span><b>${h(c.value)}</b><p>${h(c.text)}</p></div>`).join('')}</div><p class="london-fact-note">${t('ההפקה הרשמית בלונדון · אוקטובר 2026','Official London production · October 2026')} <a href="${url('about')}#about-provenance">${t('מקורות ותאריכים','Sources and dates')}</a></p>${sources(['london-official-about'])}</aside>`}
function readingParagraphs(value){const paragraphs=Array.isArray(value)?value:tr(value);return (Array.isArray(paragraphs)?paragraphs:[paragraphs]).filter(Boolean).map(p=>`<p>${typeof p==='object'?h(p):esc(p)}</p>`).join('')}
function readingLinks(links=[]){return links.length?`<div class="source-links">${links.map(x=>external(x.url,tr(x.label))).join('')}</div>`:''}
function israelCast(id){const g=R.israel.castGroups.find(x=>x.id===id);return g?`<details class="israel-cast reading-sources"><summary>${h(g.title)}</summary><p>${h(g.intro)}</p><dl class="reading-cast">${g.cards.map(c=>`<div id="israel-cast-${esc(c.id)}" data-israel-id="cast-${esc(c.id)}" tabindex="-1"><dt>${h(c.name)}</dt><dd>${h(c.role)}</dd></div>`).join('')}</dl>${sources(g.sourceIds)}</details>`:''}
function israelBooks(){const B=R.israel.novelTranslations;return `<div class="israel-books"><h3>${h(B.title)}</h3><p>${h(B.intro)}</p><div class="reading-grid">${B.items.map(c=>`<article class="reading-card" id="israel-book-${esc(c.id)}" data-israel-id="book-${esc(c.id)}" tabindex="-1"><h3>${h(c.name)}</h3><b>${h(c.edition)}</b><p>${h(c.body)}</p>${readingLinks(c.links)}</article>`).join('')}</div></div>`}
function israelPage(){const I=R.israel;return top(h(I.hero.title),h(I.hero.dek),h(I.hero.eyebrow))+`<div class="wrap section reading-hub"><p class="lede">${h(I.intro)}</p><nav class="reading-index" aria-label="${t('חלקי ההיסטוריה הישראלית','Sections of the Israeli story')}">${I.sections.map(s=>`<a href="#israel-${esc(s.id)}">${h(s.title)}</a>`).join('')}<a href="#israel-listen-in-hebrew">${h(I.media.title)}</a></nav><section class="israel-timeline" aria-labelledby="israel-timeline-title"><h2 id="israel-timeline-title">${h(I.timeline.title)}</h2><ol>${I.timeline.items.map(x=>`<li><strong>${esc(x.date)}</strong><h3>${h(x.title)}</h3><p>${h(x.body)}</p></li>`).join('')}</ol></section>${I.sections.map(s=>`<section class="reading-section" id="israel-${esc(s.id)}" data-israel-id="${esc(s.id)}" tabindex="-1"><h2>${h(s.title)}</h2>${readingParagraphs(s.paragraphs)}${sources(s.sourceIds)}${s.id==='cameri-1987'?israelCast('cameri-cast'):s.id==='habima-2016'?israelCast('habima-cast'):s.id==='read-in-hebrew'?israelBooks():''}</section>`).join('')}<section class="reading-section" id="israel-listen-in-hebrew" data-israel-id="listen-in-hebrew" tabindex="-1"><h2>${h(I.media.title)}</h2><p>${h(I.media.intro)}</p><div class="reading-grid">${I.media.items.map(m=>`<article class="reading-card"><h3>${h(m.title)}</h3><p>${h(m.body)}</p><a class="text-link" href="${url('listening')}?clip=${esc(m.galleryId)}" data-gallery-link="${esc(m.galleryId)}">${t('לצפייה בגלריה','Watch in the gallery')}${arrow}</a></article>`).join('')}</div></section><div class="button-row">${I.relatedLinks.map(x=>link(x.route,tr(x.label),'btn secondary')).join('')}</div></div>`}

function watchPage(){const W=R.watch;return top(h(W.title),h(W.intro),t('24 / לבחור את הבמה','24 / FIND YOUR STAGE'))+`<div class="wrap section reading-hub"><p class="reading-date"><time datetime="${esc(W.checkedDate)}">${h(W.checkedLabel)}</time></p><nav class="reading-index" aria-label="${t('בחירת יעד','Choose a destination')}">${W.cards.map(c=>`<a href="#watch-${esc(c.id)}">${h(c.title)}</a>`).join('')}</nav><div class="reading-grid">${W.cards.map(c=>`<article class="reading-card" id="watch-${esc(c.id)}" data-watch-id="${esc(c.id)}" tabindex="-1"><span class="reading-status">${h(c.statusLabel)}</span><h2>${h(c.title)}</h2>${readingParagraphs(c.paragraphs)}<div class="button-row">${external(c.officialLink.url,tr(c.officialLink.label))}</div>${readingLinks(c.additionalLinks)}${c.id==='israel'?link('israel',t('ההפקות והקולות הישראליים','Israel’s productions and voices'),'text-link'):''}<details class="reading-sources"><summary>${t("מקורות לפרטי ההפקה","Production sources")}</summary>${sources(c.sourceIds)}</details></article>`).join('')}</div>${W.sections.map(s=>`<section class="reading-section" id="watch-${esc(s.id)}"><h2>${h(s.title)}</h2>${readingParagraphs(s.paragraphs)}${s.items?`<div class="reading-grid">${s.items.map(x=>`<article><h3>${h(x.title)}</h3><p>${h(x.text)}</p></article>`).join('')}</div>`:''}${sources(s.sourceIds)}</section>`).join('')}${link('before',t('לפני שהמסך עולה: להכין את הערב','Before the curtain: plan your evening'),'btn secondary')}</div>`}

function musicalPage(){const M=R.musical;if(!M)return top(t('המחזמר','The musical'),'',t('13 / המחזמר','13 / THE MUSICAL'));return top(t('מרעיון על נייר.<br>לקולות בכל העולם.','From an idea on paper.<br>To voices around the world.'),t('האנשים שיצרו אותו. הבמות שנתנו לו חיים. ומסע חכם לאורך המחזמר, תחנה אחת בכל פעם.','The people who made it. The stages that gave it life. And an interactive journey through the musical, one dramatic stop at a time.'),t('13 / להכיר את המחזמר','13 / A MUSICAL WORTH KNOWING'))+`<div class="wrap section"><nav class="musical-index" aria-label="${t('קפיצה בתוך הדף','Sections on this page')}">${[['musical-spotlight',t('שבעה שירים באור הזרקורים','Seven songs in the spotlight')],['musical-genesis',t('איך הכול התחיל','How it began')],['musical-creators',t('מי יצר את זה','Who made it')],['musical-stages',t('איפה עלה','Where it played')],['musical-journey',t('המסע משיר לשיר','The song-by-song journey')]].map(([id,title],i)=>`<button data-jump="${id}"><b>0${i+1}</b>${title}</button>`).join('')}</nav><div class="musical-facts"><article><span>01</span><h3>${h(M.reference.runtime.label)}</h3><p>${h(M.reference.runtime.scope)}</p>${sources(M.reference.runtime.sourceIds||M.reference.sourceIds||[])}</article><article><span>02</span><h3>${t('שתי מערכות. הפסקה אחת.','Two acts. One interval.')}</h3><p>${t('ההפסקה מגיעה אחרי One Day More. האורכים והחיבורים עשויים להשתנות בין גרסאות והפקות.','The interval follows One Day More. Lengths and connective material can vary between versions and productions.')}</p></article><article><span>03</span><h3>${(M.songentries||[]).length} ${t('תחנות להקשיב דרכן','stops to listen through')}</h3><p>${t('שירים מרכזיים, קטעי מעבר ורפריזות, עם רקע ושאלות להקשבה.','Major songs, transitions and reprises, with context and listening questions.')}</p></article></div>${musicalSpotlight()}<section class="musical-section" id="musical-genesis"><div class="section-head"><div><div class="eyebrow">${t('לא נולד ישר על במה מסתובבת','IT DIDN’T BEGIN ON A REVOLVING STAGE')}</div><h2>${t('איך סיפור הופך למחזה מוזיקלי?','How does a story become a musical?')}</h2></div></div><div class="genesis-grid">${(M.genesis||[]).map((x,i)=>`<article><span class="genesis-number">0${i+1}</span><div><h3>${h(x.title)}</h3><p>${h(x.text)}</p>${sources(x.sourceIds)}</div></article>`).join('')}</div>${musicalCreationDepth()}</section><section class="musical-section" id="musical-creators"><div class="section-head"><div><div class="eyebrow">${t('כל תפקיד משנה את הצליל','EACH ROLE CHANGES THE SOUND')}</div><h2>${t('לא אדם אחד. יצירה משותפת.','Not one person. A collective work.')}</h2></div></div><div class="creator-grid">${(M.creators||[]).map((c,i)=>`<article class="creator-card"><div class="creator-monogram" aria-hidden="true">${String(i+1).padStart(2,'0')}</div><div><h3>${h(c.name)}</h3><div class="creator-role">${h(c.role)}</div><p>${h(c.bio)}</p>${sources(c.sourceIds)}</div></article>`).join('')}</div></section><section class="musical-section" id="musical-stages"><div class="section-head"><div><div class="eyebrow">${t('כמה תחנות במסע הבינלאומי','LANDMARKS IN THE INTERNATIONAL JOURNEY')}</div><h2>${t('במה מקומית. הד עולמי.','A local stage. A global echo.')}</h2></div><p>${t('אבני דרך בתולדות ההפקות.','Milestones in the production’s history.')}</p></div>${officialLondonFacts()}<div class="production-doorways">${link('israel',t('כשהסיפור שר בעברית','Israeli productions and Hebrew performances'),lang==='he'?'btn secondary':'text-link')}${link('watch',t('איפה רואים עכשיו?','Where can I see it now?'),'btn secondary')}</div><div class="stage-grid">${(M.stages||[]).map(c=>`<article><div class="stage-date">${h(c.dateLabel)}</div><h3>${h(c.city)}</h3><b>${h(c.venue)}</b><p>${h(c.summary)}</p>${sources(c.sourceIds)}</article>`).join('')}</div></section><section class="musical-section"><details class="music-primer-disclosure"><summary>${t("לפני שמקשיבים: ארבע דרכים שבהן המוזיקה מספרת","Before listening: four ways music tells the story")}</summary>${musicFormPrimer()}</details><div id="musical-journey" tabindex="-1">${spoiler?banner()+showJourney():`<div class="gate show-gate"><span class="gate-icon" aria-hidden="true">♫</span><div class="eyebrow">${t('המסע המלא · עם סוף הסיפור','THE FULL JOURNEY · INCLUDING THE ENDING')}</div><h2>${t('לפתוח את כל המחזמר?','Open the whole musical?')}</h2><p>${t('התחנות כוללות את העלילה, יחסים, אובדן וסוף הסיפור. רשימת הסצנות וההסברים תופיע רק אחרי בחירה מפורשת.','These stops include plot, relationships, loss and the ending. The scene list and explanations appear only after you choose to reveal them.')}</p><button class="btn" data-action="show-open">${t('כן, לפתוח את המסע','Yes, open the journey')}${arrow}</button></div>`}<details class="show-version-notes"><summary>${t('איזו גרסה זו, ומה יכול להשתנות?','Which version is this, and what can change?')}</summary>${(M.reference.caveats||[]).map(c=>`<p>${h(c)}</p>`).join('')}${sources(M.reference.sourceIds||[])}</details></div></section></div>`}

const Q = window.QuizEngine;
function persistQuiz(){save('barricade-quiz-run',JSON.stringify(quizRun));save('barricade-quiz-consent',quizConsent?'on':'off',true)}
function initQuiz(){if(quizInitialized)return;quizInitialized=true;try{const saved=JSON.parse(getStored('barricade-quiz-run')||'null');if(Q.valid(R.quiz,saved)){quizRun=Q.normalize(R.quiz,saved);quizTrack=quizRun.track;quizLength=quizRun.length}}catch{}quizConsent=getStored('barricade-quiz-consent',true)==='on'}
function quizBadge(){const s=Q.score(quizRun);return R.quiz.badgeTiers.find(b=>s.percent>=b.minPercent&&s.percent<b.maxPercentExclusive)||R.quiz.badgeTiers[0]}
function quizSetup(){return `<div class="quiz-setup compact-quiz"><h2 class="quiz-setup-heading">${t('מה משחקים?','What shall we play?')}</h2><div class="quiz-track-grid" role="group" aria-label="${t('בחירת מסלול','Choose a track')}">${['story','musical'].map((track,i)=>{const d=R.quiz.trackInfo[track];return `<button class="quiz-track ${quizTrack===track?'active':''}" data-quiz-track="${track}" aria-pressed="${quizTrack===track}"><span class="track-emblem" aria-hidden="true">${i?'♫':'↗'}</span><h3>${h(d.title)}</h3><small>${t('25 שאלות לבחירה','25 questions available')}</small><span class="track-choice">${quizTrack===track?t('נבחר ✓','Selected ✓'):t('לבחירה','Choose')}</span></button>`}).join('')}</div><h3 class="quiz-length-title">${t('כמה שאלות?','How many questions?')}</h3><div class="quiz-modes" role="group" aria-label="${t('מספר השאלות','Number of questions')}">${R.quiz.modes.map(m=>`<button class="${quizLength===m.count?'active':''}" data-quiz-length="${m.count}" aria-pressed="${quizLength===m.count}" aria-label="${h(m.title)}"><b>${m.count}</b><span>${m.count===5?t('טעימה','A taste'):m.count===10?t('סיבוב','A round'):t('הכול','The full track')}</span></button>`).join('')}</div><div class="quiz-warning"><div><h3>${t('גם הסוף נמצא בשאלות','The ending is in these questions')}</h3><p>${h(R.quiz.spoilerWarning)}</p><p class="small">${t('התחלה או חזרה למקצה תפעיל ספוילרים בלשונית הזאת. אפשר להסתיר שוב בכותרת.','Starting or resuming turns on spoilers in this tab. Hide them again from the header.')}</p><button class="btn" data-action="quiz-start">${t('מסכימים לספוילרים ומתחילים','Accept spoilers & start')} · ${quizLength}</button>${quizRun?`<button class="btn secondary" data-action="quiz-resume">${t('מסכימים וחוזרים למקצה השמור','Accept & resume saved round')} (${h(R.quiz.trackInfo[quizRun.track].title)} · ${Q.score(quizRun).answered}/${quizRun.length})</button>`:''}</div></div><p class="quiz-privacy">${t('בלי חשבון או טבלת מובילים. זכירת ההתקדמות מעבר לביקור הזה היא לבחירתכם בהעדפות הפרטיות. החלפת שפה שומרת את המקצה הנוכחי.','No account or leaderboard. Remembering progress beyond this visit is optional in privacy settings. Changing language keeps your current round.')}</p><details class="quiz-setup-details"><summary>${t('מה בכל מסלול, ואיך נקבע התג?','What is in each track, and how do badges work?')}</summary>${['story','musical'].map(track=>`<h3>${h(R.quiz.trackInfo[track].title)}</h3><p>${h(R.quiz.trackInfo[track].description)}</p>`).join('')}<p>${h(R.quiz.scoring.instruction)}</p><p>${h(R.quiz.songTitleNote)}</p></details>${quizRun?`<button class="text-button" data-action="quiz-delete">${t('מחיקת המקצה השמור מהדפדפן','Delete saved round from this browser')}</button>`:''}</div>`}

function quizQuestion(){const q=Q.question(R.quiz,quizRun.ids[quizRun.index]),answer=quizRun.answers[q.id],s=Q.score(quizRun);return `<section class="quiz-play"><div class="quiz-progress-top"><span>${h(R.quiz.trackInfo[quizRun.track].title)} · ${quizRun.length} ${t('שאלות','questions')}</span><button class="text-button" data-action="quiz-change">${t('בחירת מקצה אחר','Choose another round')}</button></div><div class="quiz-progress" aria-label="${t('התקדמות','Progress')}"><div style="width:${s.answered/s.total*100}%"></div></div><div class="quiz-counter"><strong>${String(quizRun.index+1).padStart(2,'0')}</strong><span>/ ${quizRun.length}</span><small>${s.answered} ${t('נענו','answered')} · ${s.correct} ${t('נכונות','correct')}</small></div><div class="quiz-question-heading"><span class="tag">${q.scope==='novel'?t('ברומן','IN THE NOVEL'):quizRun.track==='musical'?t('על הבמה','ON STAGE'):t('בסיפור','IN THE STORY')} · ${t('דרגת קושי','LEVEL')} ${q.difficulty}</span><h2 id="quiz-question-title" tabindex="-1">${h(q.question)}</h2></div><div class="quiz-options" role="group" aria-label="${h(q.question)}">${q.options.map((o,i)=>`<button class="quiz-option ${quizRun.selected===i?'selected':''} ${answer&&i===q.correctIndex?'correct':''} ${answer&&answer.choice===i&&i!==q.correctIndex?'incorrect':''}" data-quiz-option="${i}" aria-pressed="${quizRun.selected===i}" ${answer?'disabled':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${h(o.text)}</span>${answer&&i===q.correctIndex?`<b>${t('נכון ✓','Correct ✓')}</b>`:answer&&answer.choice===i?`<b>${t('הבחירה שלך','Your choice')}</b>`:''}</button>`).join('')}</div>${answer?`<div class="quiz-explanation" tabindex="-1" role="status"><h3>${answer.correct?t('בדיוק. ועכשיו, למה זה מעניין?','Exactly. Now, why does it matter?'):t('כמעט שם. הנה החיבור שחיפשנו.','Here is the connection we were looking for.')}</h3><p>${h(q.explanation)}</p><div class="source-links">${q.sources.map(s=>external(s.url,s.title)+(s.reference?`<span>${esc(s.reference)}</span>`:'')).join('')}</div></div>`:''}<div class="quiz-actions">${quizRun.index?`<button class="btn secondary" data-action="quiz-previous">${t('לשאלה הקודמת','Previous question')}</button>`:''}${answer?`<button class="btn" data-action="quiz-next">${quizRun.index===quizRun.length-1?t('לראות את התוצאה והתג','See result & badge'):t('השאלה הבאה','Next question')}</button>`:`<button class="btn" data-action="quiz-submit" ${quizRun.selected===null?'disabled':''}>${t('זוהי התשובה שלי','Lock in my answer')}</button>`}</div><p class="small muted">${t('תשובה שנבדקה נשארת נעולה. שאלה שעוד לא נענתה אינה נספרת כטעות.','Checked answers stay locked. Unanswered questions do not count as mistakes.')}</p></section>`}
function badgeArt(){return `<svg viewBox="0 0 200 210" aria-hidden="true"><path d="M40 140L22 207 70 180 101 210 106 150M97 150L128 207 150 175 191 186 164 128" fill="#ed2939"/><path d="M100 8L122 20 148 17 162 40 186 53 183 80 196 104 180 126 174 153 148 160 128 180 102 173 76 183 56 163 29 158 23 132 7 111 18 86 15 59 39 45 51 22 77 23Z" fill="#002395"/><circle cx="100" cy="96" r="59" fill="#fff"/><path d="M72 129V55M73 58c25-17 28 16 58-2v46c-26 17-37-13-58 2" fill="#ed2939" stroke="#002395" stroke-width="3"/><path d="M58 138h76" stroke="#002395" stroke-width="4"/></svg>`}
function quizResult(){const s=Q.score(quizRun),badge=quizBadge();return `<section class="quiz-result"><div class="result-main"><div class="badge-art">${badgeArt()}</div><div><div class="eyebrow">${t('המקצה הושלם · התג שלך','ROUND COMPLETE · YOUR BADGE')}</div><h2 tabindex="-1" id="quiz-question-title">${h(badge.name)}</h2><div class="result-score"><strong>${s.correct}<span> / ${s.total}</span></strong><b>${s.percent}%</b></div><p>${h(badge.description)}</p><p class="small">${h(R.quiz.trackInfo[quizRun.track].title)} · ${quizRun.length} ${t('שאלות. הדרגה מתייחסת למקצה הזה בלבד.','questions. This badge applies to this round only.')}</p></div></div><div class="result-tools"><button class="btn" data-action="quiz-share" disabled>${t('שיתוף ההישג','Share achievement')}</button><button class="btn secondary" data-action="quiz-copy">${t('העתקת ההישג','Copy achievement')}</button><button class="btn secondary" data-action="quiz-download-png" disabled>${t('הורדת תמונה','Download image')}</button><button class="btn secondary" data-action="quiz-download">${t('הורדת תג SVG','Download SVG badge')}</button><button class="text-button" data-action="quiz-change">${t('לבחור את המקצה הבא','Choose your next round')}</button></div><details class="quiz-card-preview"><summary>${t('תצוגת תמונת ההישג','Preview achievement image')}</summary><img id="quiz-achievement-preview" width="1080" height="1080" hidden alt="${esc(t('כרטיס ההישג: ','Achievement card: ')+tr(badge.name))}"></details><div id="share-feedback" aria-live="polite"></div><p class="small muted">${t('התמונה כוללת את שם האתר, המסלול, התוצאה והתג. אתם בוחרים איפה ועם מי לשתף.','The image includes the site name, track, score and badge. You choose where and with whom to share.')}</p><details class="quiz-review"><summary>${t('לעבור שוב על התשובות וההסברים','Review answers & explanations')}</summary>${quizRun.ids.map(id=>{const q=Q.question(R.quiz,id),a=quizRun.answers[id];return `<article><h3>${a.correct?'✓':'○'} ${h(q.question)}</h3><p><b>${t('התשובה הנכונה:','Correct answer:')}</b> ${h(q.options[q.correctIndex].text)}</p>${!a.correct?`<p>${t('בחרת:','You chose:')} ${h(q.options[a.choice].text)}</p>`:''}<p>${h(q.explanation)}</p><div class="source-links">${q.sources.map(s=>external(s.url,s.title)).join('')}</div></article>`}).join('')}</details><p class="quiz-privacy">${h(R.quiz.unofficialNotice)}</p></section>`}
function quizPage(){initQuiz();return top(t('מה נשאר איתכם?','What stayed with you?'),t('שני מסלולים. 5, 10 או 25 שאלות. הסבר אחרי כל תשובה, ותג בסיום.','Two tracks. 5, 10 or 25 questions. An explanation after each answer, and a badge at the end.'),t('12 / חדרי החידון','12 / THE QUIZ ROOMS')).replace('class="page-top"','class="page-top quiz-page-top"')+`<div class="wrap section quiz-room" id="quiz-room" tabindex="-1">${quizRun&&quizConsent?(quizRun.finished?quizResult():quizQuestion()):quizSetup()}</div>`}
function updateQuiz(focus=false){persistQuiz();document.getElementById('quiz-room').innerHTML=quizRun&&quizConsent?(quizRun.finished?quizResult():quizQuestion()):quizSetup();if(focus){const title=document.getElementById('quiz-question-title');if(title){title.focus({preventScroll:true});title.scrollIntoView({block:'center',behavior:'auto'})}}mountQuizAchievement();}
let quizTextShareBusy = false;
let quizCopyBusy = false;
function currentQuizAchievement() {
  if (route !== 'quiz' || !quizConsent || !quizRun?.finished) return null;
  const s = Q.score(quizRun);
  return { round: quizRun, language: lang, track: quizRun.track, trackTitle: tr(R.quiz.trackInfo[quizRun.track].title), badgeName: tr(quizBadge().name), correct: s.correct, total: s.total };
}
function quizAchievementIsCurrent(snapshot) {
  const current = currentQuizAchievement();
  return current && snapshot && current.round === snapshot.round && current.language === snapshot.language && current.correct === snapshot.correct && current.total === snapshot.total;
}
function paintQuizAchievement(state) {
  if (!currentQuizAchievement()) return;
  const share = document.querySelector('[data-action="quiz-share"]');
  const download = document.querySelector('[data-action="quiz-download-png"]');
  if (share) { share.disabled = state.status === 'preparing' || state.busy || quizTextShareBusy; share.setAttribute?.('aria-busy', String(state.status === 'preparing' || state.busy || quizTextShareBusy)); }
  if (download) download.disabled = state.status !== 'ready';
  const image = document.getElementById('quiz-achievement-preview');
  if (image) { image.hidden = !state.previewURL; if (state.previewURL) image.src = state.previewURL; else image.removeAttribute?.('src'); }
}
function quizAchievementFeedback(code) {
  const target = document.getElementById('share-feedback'); if (!target || !currentQuizAchievement()) return;
  if (code === 'share-unsupported' || code === 'share-failed') { shareFallback(); return; }
  const words = {
    'image-preparing': ['מכינים את התמונה. בעוד רגע אפשר לשתף.', 'Preparing the image. You can share it in a moment.'],
    'image-unavailable': ['לא הצלחנו להכין תמונה. אפשר להעתיק את ההישג או להוריד תג SVG.', 'The image could not be prepared. You can copy the achievement or download the SVG badge.'],
    'shared': ['חלונית השיתוף הסתיימה.', 'The share dialog has closed.'],
    'download-ready': ['התמונה הוכנה להורדה.', 'Your image is ready to download.'],
    'download-failed': ['הורדת התמונה לא זמינה כאן. אפשר להוריד תג SVG או להעתיק את ההישג.', 'Image download is unavailable here. You can download the SVG badge or copy the achievement.']
  };
  if (words[code]) target.textContent = t(...words[code]);
}
const quizAchievement = window.QuizAchievement?.createController({
  getCurrent: currentQuizAchievement,
  onState: paintQuizAchievement,
  onFeedback: quizAchievementFeedback,
  onShared: () => A.track('share', { content_type: 'quiz_achievement', method: 'native' }),
  onDownload: data => A.track('badge_download', { quiz_track: data.track, question_count: data.total })
});
function mountQuizAchievement() {
  if (quizAchievement) quizAchievement.prepare();
  else paintQuizAchievement({ status: 'unavailable', busy: false, previewURL: null });
}
// Clear memory on page exit; pageshow rebuilds after a back-forward-cache restore.
window.addEventListener('pagehide', () => quizAchievement?.clear());
window.addEventListener('pageshow', () => mountQuizAchievement());

// REPLACE existing quizShareText(), shareFallback(), shareQuiz() with these.
function quizShareText() {
  const d = currentQuizAchievement(); if (!d) return '';
  return window.QuizAchievement?.shareText(d) || `LesMisNotes · ${d.trackTitle} · ${d.correct}/${d.total} (${Math.round(d.correct/d.total*100)}%) · ${d.badgeName}`;
}
function shareFallback() {
  const target = document.getElementById('share-feedback'), data = currentQuizAchievement(); if (!target || !data) return;
  const text = quizShareText();
  // This URL opens only when the visitor clicks it. Nothing is posted automatically.
  const whatsApp = 'https://wa.me/?text=' + encodeURIComponent(text);
  target.innerHTML = `<div class="quiz-share-fallback"><p>${t('אפשר להוריד את התמונה ולצרף אותה, או לבחור איך לשתף את הטקסט:','Download the image to attach it, or choose how to share the text:')}</p><div class="result-tools">${navigator.share ? `<button class="btn secondary" data-action="quiz-share-text">${t('שיתוף טקסט','Share text')}</button>` : ''}<a class="btn secondary" href="${esc(whatsApp)}" target="_blank" rel="noopener noreferrer">${t('פתיחה ב־WhatsApp','Open WhatsApp')}</a></div><label class="share-fallback">${t('הטקסט של ההישג:','Achievement text:')}<textarea readonly rows="3">${esc(text)}</textarea></label></div>`;
}
async function shareQuiz(copy = false) {
  const snapshot = currentQuizAchievement(); if (!snapshot) return;
  if (!copy) { if (!quizTextShareBusy) { if (quizAchievement) return quizAchievement.shareImage(); shareFallback(); } return; }
  if (quizCopyBusy) return;
  quizCopyBusy = true;
  try {
    if (!navigator.clipboard?.writeText) { shareFallback(); return; }
    await navigator.clipboard.writeText(quizShareText());
    if (!quizAchievementIsCurrent(snapshot)) return;
    A.track('share', { content_type: 'quiz_achievement', method: 'clipboard' });
    document.getElementById('share-feedback').textContent = t('ההישג הועתק. עכשיו אפשר לבחור עם מי לשתף.','Achievement copied. You choose who to share it with.');
  } catch {
    if (quizAchievementIsCurrent(snapshot)) { shareFallback(); const field = document.querySelector('.share-fallback textarea'); field?.focus(); field?.select(); }
  } finally { quizCopyBusy = false; }
}
async function shareQuizText() {
  const snapshot = currentQuizAchievement();
  if (!snapshot || !navigator.share || quizTextShareBusy || quizAchievement?.state().busy) return;
  quizTextShareBusy = true; if (quizAchievement) paintQuizAchievement(quizAchievement.state());
  try {
    await navigator.share({ title: t('ההישג שלי','My achievement'), text: quizShareText() });
    if (quizAchievementIsCurrent(snapshot)) A.track('share', { content_type: 'quiz_achievement', method: 'native' });
  } catch (error) {
    if (error.name !== 'AbortError' && quizAchievementIsCurrent(snapshot)) shareFallback();
  } finally { quizTextShareBusy = false; if (quizAchievement) paintQuizAchievement(quizAchievement.state()); }
}


function downloadQuizBadge(){if(!quizRun?.finished)return;const s=Q.score(quizRun),b=quizBadge();const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="700" viewBox="0 0 900 700"><rect width="900" height="700" rx="25" fill="#fff"/><path d="M0 0h300v15H0" fill="#002395"/><path d="M600 0h300v15H600" fill="#ed2939"/><rect x="15" y="15" width="870" height="670" rx="18" fill="none" stroke="#002395" stroke-width="5"/><g transform="translate(350 35)">${badgeArt().replace('<svg viewBox="0 0 200 210" aria-hidden="true">','<svg width="200" height="210" viewBox="0 0 200 210">')}</g><g text-anchor="middle" font-family="Arial,sans-serif" fill="#002395"><text x="450" y="310" font-size="26">LesMisNotes</text><text x="450" y="370" font-size="32">${esc(tr(b.name))}</text><text x="450" y="460" font-size="64">${s.correct} / ${s.total} · ${s.percent}%</text><text x="450" y="520" font-size="24">${esc(tr(R.quiz.trackInfo[quizRun.track].title))} · ${quizRun.length} ${esc(t('שאלות','questions'))}</text><text x="450" y="600" font-size="18">${esc(t('תג משחק עצמאי ולא רשמי','An independent, unofficial fan-quiz badge'))}</text></g></svg>`;const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`lesmisnotes-${quizRun.track}-${quizRun.length}.svg`;a.click();A.track('badge_download',{quiz_track:quizRun.track,question_count:quizRun.length});setTimeout(()=>URL.revokeObjectURL(u),1000);document.getElementById('share-feedback').textContent=t('התג הוכן להורדה.','Your badge is ready to download.')}
function handleQuizAction(action){if(action==='quiz-start'){A.track('quiz_start',{quiz_track:quizTrack,question_count:quizLength});quizRun=Q.start(R.quiz,quizTrack,quizLength);quizConsent=true;spoiler=true;save('barricade-spoilers','on',true);render();updateQuiz(true)}else if(action==='quiz-resume'){if(quizRun&&!quizRun.finished)A.track('quiz_resume',{quiz_track:quizRun.track,question_count:quizRun.length,step_index:quizRun.index+1});quizConsent=true;spoiler=true;save('barricade-spoilers','on',true);render();updateQuiz(true)}else if(action==='quiz-submit'){const previousQuiz=quizRun;quizRun=Q.submit(R.quiz,quizRun);if(quizRun!==previousQuiz)A.track('quiz_step',{quiz_track:quizRun.track,question_count:quizRun.length,step_index:quizRun.index+1});updateQuiz();document.querySelector('.quiz-explanation')?.focus({preventScroll:true})}else if(action==='quiz-next'){const wasFinished=quizRun.finished;quizRun=Q.next(quizRun);if(quizRun.finished&&!wasFinished)A.track('quiz_complete',{quiz_track:quizRun.track,question_count:quizRun.length,correct_count:Q.score(quizRun).correct});updateQuiz(true)}else if(action==='quiz-previous'){quizRun=Q.previous(quizRun);updateQuiz(true)}else if(action==='quiz-change'){quizConsent=false;updateQuiz();document.getElementById('quiz-room').focus({preventScroll:true})}else if(action==='quiz-delete'){quizRun=null;quizConsent=false;updateQuiz()}else if(action==='quiz-share')shareQuiz();else if(action==='quiz-copy')shareQuiz(true);else if(action==='quiz-download-png')quizAchievement?.downloadImage();else if(action==='quiz-share-text')shareQuizText();else if(action==='quiz-download')downloadQuizBadge()}

